(E'THPT', E'NGU_VAN', 180, E'11', E'Video/ clip/phim tài liệu', E'Tác giả Nam Cao', E'Video/clip/ phim tư liệu về sự nghiệp văn chương của Nam Cao', E'Minh hoạ, phục vụ cho hoạt động tìm hiểu về về truyện ngắn, tiểu thuyết của Nam Cao', E'Các video/clip/phim tư liệu cung cấp tư liệu dạy học về sự nghiệp văn chương của Nam Cao, bao gồm:\n- Phim tư liệu về bối cảnh thời đại, cuộc đời, sự nghiệp văn học của Nam Cao;\n- Ý kiến phát biểu của một số nhà phê bình văn học nhận định, đánh giá về truyện ngắn, tiếu thuyết của Nam Cao (giá trị nội dung và nghệ thuật).', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'11,12', E'Dùng cho lớp 11, 12', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-NV-018', E'DM-THPT-NV-018', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'NGU_VAN', 190, E'12', E'Video/ clip/phim tài liệu', E'Tác giả Vũ Trọng Phụng', E'Video/clip/ phim tư liệu tiểu thuyết, phóng sự của Vũ Trọng Phụng', E'Minh hoạ, phục vụ cho hoạt động tìm hiểu về tiểu thuyết, phóng sự của Vũ Trọng Phụng', E'Các video/clip/phim tư liệu cung cấp tư liệu dạy học về tiểu thuyết, phóng sự của Vũ Trọng Phụng, bao gồm:\n- Phim tư liệu về cuộc đời, sự nghiệp văn học của Vũ Trọng Phụng.\n- Ý kiến phát biểu của một số nhà phê bình văn học nhận định, đánh giá về tiểu thuyết, phóng sự của Vũ Trọng Phụng (giá trị nội dung và nghệ thuật).', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'11,12', E'Dùng cho lớp 11, 12', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-NV-019', E'DM-THPT-NV-019', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'NGU_VAN', 200, E'13', E'Video/ clip/phim tài liệu', E'Tác giả Xuân Diệu', E'Video/clip/ phim tư liệu về thơ của Xuân Diệu trước Cách mạng tháng Tám', E'Minh hoạ, phục vụ cho hoạt động tìm hiểu về thơ của Xuân Diệu trước Cách mạng tháng Tám', E'Các video/clip/phim tư liệu, cung cấp tư liệu dạy học về thơ của Xuân Diệu trước Cách mạng tháng Tám, bao gồm:\n- Phim tư liệu về bối cảnh thời đại trước Cách mạng tháng Tám, về phong trào Thơ mới;\n- Phim tư liệu về cuộc đời, sự nghiệp văn học của Xuân Diệu;\n- Ý kiến phát biểu của một số nhà phê bình văn học nhận định, đánh giá về thơ của Xuân Diệu (giá trị nội dung và nghệ thuật).', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'11,12', E'Dùng cho lớp 11, 12', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-NV-020', E'DM-THPT-NV-020', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'NGU_VAN', 210, E'14', E'Video/ clip/phim tài liệu', E'Tác giả Tố Hữu', E'Video/clip/ phim tư liệu về thơ của Tố Hữu trước và sau Cách mạng tháng Tám', E'Minh hoạ, phục vụ cho hoạt động tìm hiểu về thơ của Tố Hữu trước và sau Cách mạng tháng Tám', E'Các video/clip/phim tư liệu cung cấp tư liệu dạy học về thơ của Tố Hữu, bao gồm:\n- Phim tư liệu về cuộc đời, sự nghiệp văn học của tác giả Tố Hữu;\n- Ý kiến phát biểu của một số nhà phê bình văn học nhận định, đánh giá về thơ của Tố Hữu (giá trị nội dung và nghệ thuật).', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'11,12', E'Dùng cho lớp 11, 12', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-NV-021', E'DM-THPT-NV-021', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'NGU_VAN', 220, E'15', E'Video/ clip/phim tài liệu', E'Tác giả Nguyễn Tuân', E'Video/clip/ phim tư liệu về truyện ngắn, kí của Nguyễn Tuân', E'Minh hoạ, phục vụ cho hoạt động tìm hiểu về truyện ngắn, kí của Nguyễn Tuân', E'Các video/clip/phim tư liệu cung cấp tư liệu dạy học về truyện ngắn, kí của Nguyễn Tuân, bao gồm:\n- Phim tư liệu về cuộc đời, sự nghiệp văn học của tác giả Nguyễn Tuân;\n- Ý kiến phát biểu của một số nhà phê bình văn học nhận định, đánh giá về truyện ngắn, kí của Nguyễn Tuân (giá trị nội dung và nghệ thuật);\n- Phim tư liệu về những sự vật/ địa danh được mô tả trong các tác phẩm kí của Nguyễn Tuân.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'11,12', E'Dùng cho lớp 11, 12', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-NV-022', E'DM-THPT-NV-022', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'NGU_VAN', 230, E'16', E'Video/ clip/phim tài liệu', E'Tác giả Nguyễn Huy Tưởng', E'Video/clip/ phim tư liệu về kịch của Nguyễn Huy Tưởng', E'Minh hoạ, phục vụ cho hoạt động tìm hiểu kịch của tác giả Nguyễn Huy Tưởng', E'Các video/clip/phim tư liệu, cung cấp tư liệu dạy học về kịch của Nguyễn Huy Tưởng, bao gồm:\n- Phim tư liệu về cuộc đời, sự nghiệp văn học của tác giả Nguyễn Huy Tưởng;\n- Ý kiến phát biểu của một số nhà phê bình văn học nhận định, đánh giá về kịch của Nguyễn Huy Tưởng (giá trị nội dung và nghệ thuật);\n- Trích đoạn tác phẩm kịch của Nguyễn Huy Tưởng được chuyển thể.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'11,12', E'Dùng cho lớp 11, 12', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-NV-023', E'DM-THPT-NV-023', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'NGU_VAN', 240, E'17', E'Video/ clip/phim tài liệu', E'Tác giả Lưu Quang Vũ', E'Video/clip/ phim tư liệu về kịch của Lưu Quang Vũ', E'Minh hoạ, phục vụ cho hoạt động tìm hiểu kịch của tác giả Lưu Quang Vũ', E'Các video/clip/phim tư liệu, cung cấp tư liệu dạy học về kịch của Lưu Quang Vũ, bao gồm:\n- Phim tư liệu về cuộc đời, sự nghiệp văn học của tác giả Lưu Quang Vũ;\n- Ý kiến phát biểu của một số nhà phê bình văn học nhận định, đánh giá về kịch của Lưu Quang Vũ (giá trị nội dung và nghệ thuật).\n- Trích đoạn tác phẩm kịch Lưu Quang Vũ được chuyển thể.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'11,12', E'Dùng cho lớp 11, 12', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-NV-024', E'DM-THPT-NV-024', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TOAN', 250, E'1', E'Thiết bị dùng chung', E'Hình học', E'Bộ thiết bị để vẽ trên bảng trong dạy học toán', E'Giáo viên sử dụng để vẽ trên bảng trong dạy học Toán', E'Bộ thiết bị để vẽ trên bảng gồm:\n- 01 chiếc thước thẳng dài tối thiểu 500mm, độ chia nhỏ nhất là 1mm;\n- 01 chiếc compa dài 400mm với đầu được thiết kế thuận lợi khi vẽ trên bảng bằng phấn, bút dạ, một đầu thuận lợi cho việc cố định trên mặt bảng. Tất cả các thiết bị trên được làm bằng nhựa/gỗ hoặc vật liệu khác có độ cứng tương đương, không cong vênh, màu sắc tươi sáng, an toàn với người sử dụng.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'THPT-TOAN-001', E'DM-THPT-TOAN-001', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TOAN', 260, E'1.1', E'Thiết bị theo các chủ đề › Mô hình', E'Hình học không gian', E'Bộ thiết dạy học về các đường cônic.', E'Giúp học sinh thực hành nhận biết, mô tả hình dạng và đặc điểm các đường cônic.', E'Mô hình ba đường conic:\n- Khối hình nón đáy có đường kính 200mm, cao 350mm bằng nhựa trong suốt; trục giữa bằng thép sơn màu trắng; các mặt cắt hình tròn, elip cố định; mặt cắt hypecbol, parabol bằng nhựa cứng với màu sắc phân biệt giữa các mặt cắt, có thể tháo lắp ở đáy hình nón; Giá đỡ hộp lập phương cạnh 100mm nhựa PS (hoặc tương đương) trong có lỗ với đường kính 58mm.\n- Tất cả được làm bằng vật liệu an toàn trong quá trình sử dụng.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'08/GV', 8, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10', E'MO_HINH_MAU_VAT', E'PHYSICAL', E'SERIAL', NULL, E'THPT-TOAN-002', E'DM-THPT-TOAN-002', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TOAN', 270, E'1.1', E'Thiết bị theo các chủ đề › Mô hình', E'Hình học không gian', E'Bộ thiết dạy học về hình chóp, hình chóp cụt, hình lăng trụ.', E'Giúp học sinh thực hành, nhận biết, mô tả hình dạng và đặc điểm, diện tích xung quanh, thể tích các hình chóp, hình chóp cụt, hình lăng trụ', E'Bộ thiết bị dạy học về hình chóp, hình chóp cụt, hình lăng trụ gồm:\n- 01 tứ diện 4 mặt là tam giác đều, độ dài cạnh 160mm;\n- 01 khối lăng trụ hình chữ nhật có đáy, nắp bằng nhựa, đáy hình vuông cạnh 120mm, cao 210mm, có khoét 1 khối lăng trụ tam giác bằng ¼ lăng trụ vuông (có cạnh đáy 120mm, 2 cạnh còn lại có kích thước bằng nhau và bằng ½ đường chéo đáy);\n- 01 khối lăng trụ tam giác gồm 3 tứ diện bằng nhựa ABS (hoặc tương đương) ghép lại: 2 tứ diện cao 210mm, một cạnh đáy 120mm, 2 cạnh còn lại bằng ½ đường chéo đáy lăng trụ hình chữ nhật; 1 tứ diện được ghép bởi 4 tam giác vuông bằng nhau (một cạnh góc vuông dài 210mm, cạnh góc vuông còn lại dài bằng ½ đường chéo lăng trụ hình chữ nhật). Các mặt thiết diện tiếp xúc nhau phải cùng màu và có định vị: Mặt tiếp xúc với lăng trụ hình chữ nhật bằng nhựa PSHI màu trắng đục (hoặc tương đương).\nTất cả được làm bằng vật liệu an toàn trong quá trình sử dụng.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'08/GV', 8, E'PER_TEACHER', NULL, E'11', E'Dùng cho lớp 11', E'MO_HINH_MAU_VAT', E'PHYSICAL', E'SERIAL', NULL, E'THPT-TOAN-003', E'DM-THPT-TOAN-003', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TOAN', 280, E'1.1', E'Thiết bị theo các chủ đề › Dụng cụ', E'Thống kê và Xác suất', E'Bộ thiết bị dạy học về Thống kê và Xác suất', E'Giúp học sinh khám phá, hình thành, thực hành, luyện tập về biểu đồ thống kê; làm quen với xác suất của biến cố ngẫu nhiên.', E'Bộ thiết bị dạy học về thống kê và xác suất gồm:\n- 01 quân xúc xắc có độ dài cạnh là 20mm, có\n6 mặt, số chấm xuất hiện ở mỗi mặt là một trong các số 1; 2; 3; 4; 5; 6 (mặt 1 chấm; mặt 2 chấm; ..., mặt 6 chấm);\n- 01 hộp nhựa để tung quân xúc xắc (kích thước phù hợp với quân xúc xắc);\n- 02 đồng xu gồm một đồng xu to có đường kính 25mm và một đồng xu nhỏ có đường kính 20mm; dày 1mm; làm bằng hợp kim (nhôm, đồng). Trên mỗi đồng xu, một mặt khắc nổi chữ N, mặt kia khắc nổi chữ S;\n- 01 hộp bóng có 3 quả, trong đó có 1 quả bóng xanh, 1 quả bóng đỏ và một quả bóng vàng, các quả bóng có kích thước và trọng lượng như nhau với đường kính 35mm (giống quả bóng bàn).', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'08/GV', 8, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10', E'DO_DUNG_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'THPT-TOAN-004', E'DM-THPT-TOAN-004', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TOAN', 290, E'1', E'Thiết bị theo các chủ đề › Tranh điện tử/phần mềm', E'Đại số và Giải tích', E'Tranh điện tử', E'Tranh điện tử hỗ trợ HS khám phá,hình thành, thực hành, luyện tập, tổng kết một số kiến thức đại số và giải tích.', E'Tranh điện tử gồm có:\n1. Bảng tổng kết tính chất và các dạng đồ thị của các hàm số y = ax2 + bx + c (a ≠0); y = ax3 +bx2 + cx+d (a ≠0);\n(c≠0, ad-bc ≠0); (a ≠0, m ≠0 và đa thức tử không chia hết cho đa thức mẫu); hàm số lượng giác; hàm số mũ; hàm số lôgarit.\n2. Bảng công thức nguyên hàm của một số hàm số sơ cấp.\n3. Bộ hình ảnh về các phép biến hình: phép tịnh tiến, phép vị tự, phép đối xứng trục, phép đối xứng tâm, phép quay; phép dời hình, phép đồng dạng.\n4. Bộ hình ảnh mô tả về cung, góc lượng giác, hàm số lượng giác (diễn tả quan hệ hàm số lượng giác).', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-TOAN-005', E'DM-THPT-TOAN-005', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TOAN', 300, E'1', E'Thiết bị theo các chủ đề › Tranh điện tử/phần mềm', E'Đại số và Giải tích', E'Phần mềm toán học', E'Phần mềm toán học hỗ trợ học sinh khám phá, hình thành, thực hành, luyện tập các kiến thức đại số và giải tích.', E'- Phần mềm toán học đảm bảo vẽ đồ thị của hàm số bậc hai; đồ thị hàm số lượng giác; đồ thị hàm số luỹ thừa, hàm số mũ, hàm số lôgarit và tìm hiểu đặc điểm của chúng;minh hoạ sự tương giao của các đồ thị; thực hiện các phép biến đổi đồ thị;tạo mô hình thao tác động mô tả giới hạn, mô tả hàm số liên tục; tạo mô hình mô tả đạo hàm, ý nghĩa hình học của tiếp tuyến; tạo hoa văn, hình khối, tính toán trong đại số và giải tích; tạo mô hình khối tròn xoay trong một số bài toán ứng dụng tích phân xác định;\n- Phải sử dụng phần mềm không vi phạm bản quyền.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-TOAN-006', E'DM-THPT-TOAN-006', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TOAN', 310, E'2', E'Thiết bị theo các chủ đề › Tranh điện tử/phần mềm', E'Hình học và đo lường', E'Phần mềm toán học', E'Phần mềm toán học hỗ trợ học sinh khám phá, hình thành, thực hành, luyện tập các kiến thức hình học.', E'- Phần mềm toán học đảm bảo biểu thị được điểm, vectơ, các phép toán vectơ trong hệ trục toạ độ Oxy; vẽ đường thẳng, đường tròn, các đường conic trên mặt phẳng toạ độ; tạo được sự thay đổi hình dạng của các hình khi thay đổi các yếu tố trong phương trình xác định chúng; thiết kế đồ hoạ liên quan đến đường tròn và các đường conic; vẽ đường thẳng, mặt phẳng, giao điểm, giao tuyến, tạo hình trong không gian, xác định hình biểu diễn; tạo mô hình khối tròn xoay trong một số bài toán ứng dụng tích phân xác định; vẽ đường thẳng, mặt phẳng, mặt cầu trong hệ trục toạ độ Oxyz; xem xét sự thay đổi hình dạng khi thay đổi các yếu tố trong phương trình của chúng;\n- Phải sử dụng phần mềm không vi phạm bản quyền;', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-TOAN-006', E'DM-THPT-TOAN-007', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TOAN', 320, E'3', E'Thiết bị theo các chủ đề › Tranh điện tử/phần mềm', E'Thống kê và Xác suất', E'Phần mềm toán học', E'Phần mềm toán học hỗ trợ học sinh khám phá, hình thành, thực hành, luyện tập các kiến thức thống kê và xác suất.', E'- Phần mềm toán học đảm bảo hỗ trợ HS thực hành tính số đặc trưng đo xu thế trung tâm và đo mức độ phân tán cho mẫu số liệu không ghép nhóm, ghép nhóm; tính xác suất; tính phân bố nhị thức, tính toán thống kê;\n- Phải sử dụng phần mềm không vi phạm bản quyền.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-TOAN-006', E'DM-THPT-TOAN-008', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 330, E'1', E'Thiết bị dạy học ngoại ngữ thông dụng (lựa chọn 1)', NULL, E'Đài đĩa CD', E'Phát các học liệu âm thanh.', E'- Phát các loại đĩa CD có các định dạng phổ thông;\n- Có cổng USB và/hoặc thẻ nhớ;\n- Có chức năng nhớ, tua tiến, tua lùi, tạm dừng;\n- Đài AM, FM;\n- Nguồn điện: AC 110-220V/50 Hz, sử dụng được pin.', TRUE, FALSE, FALSE, E'CHIEC', E'Chiếc', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, E'Có thể sử dụng thiết bị dùng chung', E'MAY_MOC_THIET_BI', E'PHYSICAL', E'SERIAL', NULL, E'THPT-NN-001', E'DM-THPT-NN-001', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 340, E'2', E'Thiết bị dạy học ngoại ngữ thông dụng (lựa chọn 1)', NULL, E'Đầu đĩa', E'Phát học liệu hình ảnh và âm thanh cho các hoạt động nghe và nói.', E'- Loại thông dụng;\n- Đọc đĩa DVD, VCD/CD, CD – RW và các chuẩn thông dụng khác;\n- Có cổng kết nối USB, thẻ nhớ;\n- Tín hiệu ra dưới dạng AV, HDMI;\n- Chức năng tua tiến, tua lùi, tạm dừng;\n- Điều khiển từ xa;\n- Nguồn điện: 90 V – 240 V/50 Hz.', TRUE, FALSE, FALSE, E'CHIEC', E'Chiếc', E'01', 1, E'PER_SCHOOL', NULL, NULL, E'Có thể sử dụng thiết bị dùng chung', E'MAY_MOC_THIET_BI', E'PHYSICAL', E'SERIAL', NULL, E'THPT-NN-002', E'DM-THPT-NN-002', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 350, E'3', E'Thiết bị dạy học ngoại ngữ thông dụng (lựa chọn 1)', NULL, E'Máy chiếu (hoặc Màn hình hiển thị)', E'Kết nối với máy tính và các thiết bị khác để phát âm thanh, hình ảnh.', E'Máy chiếu:\nLoại thông dụng.\n- Có đủ cổng kết nối phù hợp;\n- Cường độ sáng tối thiểu 3.500 Ansilumens;\n- Độ phân giải tối thiểu XGA;\n- Kích cỡ khi chiếu lên màn hình tối thiểu 100 inch;\n- Điều khiển từ xa;\n- Kèm theo màn chiếu và thiết bị điều khiển (nếu có).\nMàn hình hiển thị:\n- Loại thông dụng, màn hình tối thiểu 50 inch, FullHD.\n- Có đủ cổng kết nối phù hợp;\n- Có ngôn ngữ hiển thị Tiếng Việt;\n- Điều khiển từ xa;\n- Nguồn điện: AC 90-220V/50Hz.', TRUE, FALSE, FALSE, E'CHIEC', E'Chiếc', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'MAY_MOC_THIET_BI', E'PHYSICAL', E'SERIAL', NULL, E'THPT-NN-003', E'DM-THPT-NN-003', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 360, E'4', E'Thiết bị dạy học ngoại ngữ thông dụng (lựa chọn 1)', NULL, E'Bộ máy vi tính để bàn/hoặc máy tính xách tay', E'Kết nối với các thiết bị ngoại vi để trình chiếu bài giảng', E'- Loại thông dụng, có cấu hình tối thiểu cài đặt được các hệ điều hành và các phần mềm dạy học ngoại ngữ, thời điểm trang bị máy tính không quá 2 năm so với thời điểm sản xuất;\n- Màn hình tối thiểu: 17 inch (máy tính để bàn), 14 inch (máy tính xách tay);\n- Có các cổng kết nối tối thiểu: VGA, HDMI, USB, LAN, Wifi và Bluetooth.', TRUE, FALSE, FALSE, E'CHIEC', E'Chiếc', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_CNTT', E'PHYSICAL', E'SERIAL', NULL, E'THPT-NN-004', E'DM-THPT-NN-004', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 370, E'5', E'Thiết bị dạy học ngoại ngữ thông dụng (lựa chọn 1)', NULL, E'Thiết bị âm thanh đa năng di động', E'Phát các học liệu âm thanh và trợ âm cho giáo viên', E'- Tích hợp được nhiều tính năng âm ly, loa, micro, đọc các định dạng DVD, CD, SD, USB trên thiết bị;\n- Kết nối line-in, audio in, bluetooth với nguồn phát âm thanh;\n- Công suất phù hợp với lớp học;\n- Nguồn điện: AC 220V/50Hz; DC, có ắc quy/pin sạc;\n- Kèm theo micro.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'MAY_MOC_THIET_BI', E'PHYSICAL', E'SERIAL', NULL, E'THPT-NN-005', E'DM-THPT-NN-005', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 380, E'6', E'Thiết bị dạy học ngoại ngữ thông dụng (lựa chọn 1)', NULL, E'Bộ học liệu điện tử', E'Hỗ trợ giáo viên xây dựng kế hoạch bài dạy, giáo án (điện tử), bài giảng (điện tử), học liệu (điện tử), bài tập, bài kiểm tra đánh giá.', E'Bộ học liệu điện tử được xây dựng theo chương trình môn Ngoại ngữ cấp THPT (CTGDPT 2018), không vi phạm các quy định về bản quyền, pháp luật, chủ quyền, văn hóa, dân tộc, giới, các đối tượng dễ tổn thương, có hệ thống học liệu điện tử (bài nghe, video, hình ảnh, bài giảng điện tử để dạy luyện nghe/nói cho học sinh, hệ thống câu hỏi, đề kiểm tra,) đi kèm và được tổ chức, quản lý thành hệ thống thư viện điện tử, thuận tiện cho tra cứu và sử dụng. Bộ học liệu sử dụng trên máy tính trong môi trường không có kết nối internet. Đảm bảo các chức năng:\n- Chức năng hỗ trợ soạn giáo án điện tử;\n- Chức năng chuẩn bị bài giảng điện tử;\n- Chức năng chèn các học liệu điện tử (hình ảnh, video, âm thanh) vào giáo án điện tử;\n- Chức năng tạo câu hỏi, bài tập;\n- Chức năng kiểm tra đánh giá.\nBộ học liệu điện tử gồm các bài nghe, video, hình ảnh, bài giảng điện tử để dạy luyện: nghe, nói cho học sinh. Các nội dung phải phù hợp với chương trình.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-NN-006', E'DM-THPT-NN-006', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 390, E'1', E'Hệ thống thiết bị dạy học ngoại ngữ chuyên dụng (lựa chọn 2)', NULL, E'Máy chiếu đa năng hoặc Màn hình hiển thị', E'Kết nối với máy tính và các thiết bị khác để trình chiếu hoặc phát học liệu âm thanh hình ảnh.', E'Máy chiếu:\nLoại thông dụng.\n- Có đủ cổng kết nối phù hợp;\n- Cường độ sáng tối thiểu 3.500 Ansilumens;\n- Độ phân giải tối thiểu XGA;\n- Kích cỡ khi chiếu lên màn hình tối thiểu 100 inch;\n- Điều khiển từ xa;\n- Kèm theo màn chiếu và thiết bị điều khiển (nếu có).\nMàn hình hiển thị:\n- Loại thông dụng, màn hình tối thiểu 50 inch, FullHD.\n- Có đủ cổng kết nối phù hợp;\n- Có ngôn ngữ hiển thị Tiếng Việt;\n- Điều khiển từ xa;\n- Nguồn điện: AC 90-220V/50Hz.', TRUE, FALSE, TRUE, E'CHIEC', E'Chiếc', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'MAY_MOC_THIET_BI', E'PHYSICAL', E'SERIAL', NULL, E'THPT-NN-007', E'DM-THPT-NN-007', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 400, E'2', E'Hệ thống thiết bị dạy học ngoại ngữ chuyên dụng (lựa chọn 2)', NULL, E'Thiết bị âm thanh đa năng di động', E'Thu, phát, khuếch đại âm thanh', E'- Tích hợp được nhiều tính năng âm ly, loa, micro, đọc các định dạng DVD, CD, SD, USB trên thiết bị;\n- Kết nối line-in, audio in, bluetooth với nguồn phát âm thanh;\n- Công suất phù hợp với lớp học;\n- Kèm theo micro;\n- Nguồn điện: AC 220V/50Hz; DC, có ắc quy/pin sạc.', TRUE, FALSE, TRUE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'MAY_MOC_THIET_BI', E'PHYSICAL', E'SERIAL', NULL, E'THPT-NN-005', E'DM-THPT-NN-008', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 410, E'3', E'Hệ thống thiết bị dạy học ngoại ngữ chuyên dụng (lựa chọn 2)', NULL, E'Bộ học liệu điện tử', E'Hỗ trợ giáo viên xây dựng kế hoạch bài dạy, giáo án (điện tử), bài giảng (điện tử), học liệu (điện tử), bài tập, bài kiểm tra đánh giá.', E'Bộ học liệu điện tử được xây dựng theo chương trình môn Ngoại ngữ cấp THPT (CTGDPT 2018), không vi phạm các quy định về bản quyền, pháp luật, chủ quyền, văn hóa, dân tộc, giới, các đối tượng dễ tổn thương, có hệ thống học liệu điện tử (bài nghe, video, hình ảnh, bài giảng điện tử để dạy luyện nghe/nói cho học sinh, hệ thống câu hỏi, đề kiểm tra,) đi kèm và được tổ chức, quản lý thành hệ thống thư viện điện tử, thuận tiện cho tra cứu và sử dụng. Bộ học liệu sử dụng trên máy tính trong môi trường không có kết nối internet. Đảm bảo các chức năng:\n- Chức năng hỗ trợ soạn giáo án điện tử;\n- Chức năng chuẩn bị bài giảng điện tử;\n- Chức năng chèn các học liệu điện tử (hình ảnh, video, âm thanh) vào giáo án điện tử;\n- Chức năng tạo câu hỏi, bài tập;\n- Chức năng kiểm tra đánh giá.\nBộ học liệu điện tử gồm các bài nghe, video, hình ảnh, bài giảng điện tử để dạy luyện: nghe, nói cho học sinh. Các nội dung phải phù hợp với chương trình.', TRUE, FALSE, TRUE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-NN-006', E'DM-THPT-NN-009', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 420, E'4', E'Hệ thống thiết bị dạy học ngoại ngữ chuyên dụng (lựa chọn 2)', NULL, E'Thiết bị cho học sinh', E'Hỗ trợ học sinh học ngoại ngữ.', E'Bao gồm:\n- Khối thiết bị điều khiển: tối thiểu có các phím bấm để trả lời trắc nghiệm, điều chỉnh âm lượng, lựa chọn kênh âm thanh nghe, gọi giáo viên;\n- Tai nghe có micro;\n- Kết nối, tiếp nhận được các điều khiển từ thiết bị của giáo viên.', FALSE, TRUE, TRUE, E'BO', E'Bộ', E'01/HS', 1, E'PER_STUDENT', NULL, NULL, NULL, E'THIET_BI_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'THPT-NN-008', E'DM-THPT-NN-010', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 430, E'5', E'Hệ thống thiết bị dạy học ngoại ngữ chuyên dụng (lựa chọn 2)', NULL, E'Thiết bị dạy cho giáo viên', E'Hỗ trợ giáo viên thực hiện dạy học ngoại ngữ.', E'Hỗ trợ giáo viên thực hiện dạy học ngoại ngữ.', FALSE, FALSE, TRUE, NULL, E'Hỗ trợ giáo viên thực hiện dạy học ngoại ngữ.', E'Hỗ trợ giáo viên thực hiện dạy học ngoại ngữ.', NULL, NULL, NULL, NULL, E'Hỗ trợ giáo viên thực hiện dạy học ngoại ngữ.', E'THIET_BI_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'THPT-NN-009', E'DM-THPT-NN-011', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 440, E'5.1', E'Hệ thống thiết bị dạy học ngoại ngữ chuyên dụng (lựa chọn 2)', NULL, E'Bộ máy vi tính để bàn/hoặc máy tính xách tay', E'Kết nối với các thiết bị ngoại vi để trình chiếu bài giảng.', E'- Loại thông dụng có cấu hình tối thiểu cài đặt được các hệ điều hành và các phần mềm dạy học ngoại ngữ, thời điểm trang bị máy tính không quá 2 năm so với thời điểm sản xuất;\n- Màn hình tối thiểu: 17 inch (máy tính để bàn), 14 inch (máy tính xách tay);\n- Có các cổng kết nối tối thiểu: VGA, HDMI, USB, LAN, Wifi và Bluetooth.', TRUE, FALSE, TRUE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_CNTT', E'PHYSICAL', E'SERIAL', NULL, E'THPT-NN-004', E'DM-THPT-NN-012', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 450, E'5.2', E'Hệ thống thiết bị dạy học ngoại ngữ chuyên dụng (lựa chọn 2)', NULL, E'Khối thiết bị điều khiển của giáo viên', E'Kết nối thiết bị của giáo viên và học sinh. Điều khiển, tổ chức dạy học.', E'Bao gồm các khối chức năng:\n- Khuếch đại và xử lý tín hiệu;\n- Tai nghe có micro;\n- Bộ đọc và ghi bài giảng của giáo viên: tối thiểu có cổng cắm USB, khe cắm thẻ nhớ;\n- Phần mềm điều khiển;\n- Có thể kết nối được âm thanh, hình ảnh và máy chiếu vật thể.\nTối thiểu phải đảm bảo các chức năng:\n+ Có giao diện thể hiện các vị trí của học sinh trong lớp.\n+ Có thể kết nối tới khối thiết bị điều khiển của học sinh để truyền âm thanh từ giáo viên tới một học sinh, một nhóm học sinh bất kỳ hoặc cả lớp.\n+ Có thể kết nối tới khối thiết bị điều khiển của học sinh để truyền âm thanh từ một học sinh bất kỳ trong lớp học tới một hoặc một nhóm học sinh khác.\n+ Có thể chia lớp học thành nhiều nhóm để thực hành giao tiếp đồng thời.\n+ Có thể tạo tối thiểu hai kênh âm thanh độc lập để học sinh lựa chọn và luyện nghe.\n+ Giúp giáo viên thực hiện các bài kiểm tra trắc nghiệm.', TRUE, FALSE, TRUE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'THPT-NN-010', E'DM-THPT-NN-013', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 460, E'6', E'Hệ thống thiết bị dạy học ngoại ngữ chuyên dụng (lựa chọn 2)', NULL, E'Bàn, ghế dùng cho giáo viên', E'Giáo viên sử dụng trong quá trình dạy học.', E'Thiết kế phù hợp để lắp đặt thiết bị dạy học ngoại ngữ dành cho giáo viên.', TRUE, FALSE, TRUE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'THPT-NN-011', E'DM-THPT-NN-014', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 470, E'7', E'Hệ thống thiết bị dạy học ngoại ngữ chuyên dụng (lựa chọn 2)', NULL, E'Bàn, ghế dùng cho học sinh', E'Học sinh sử dụng trong quá trình học tập.', E'Thiết kế phù hợp để lắp đặt thiết bị dạy học ngoại ngữ dành cho học sinh.', FALSE, TRUE, TRUE, E'BO', E'Bộ', E'01/HS', 1, E'PER_STUDENT', NULL, NULL, E'Nơi chưa có điều kiện có thể sử dụng 01 bộ/2 HS', E'THIET_BI_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'THPT-NN-012', E'DM-THPT-NN-015', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 480, E'8', E'Hệ thống thiết bị dạy học ngoại ngữ chuyên dụng (lựa chọn 2)', NULL, E'Phụ kiện', E'Dùng để cung cấp điện cho các thiết bị và kết nối tín hiệu giữa các thiết bị', E'Hệ thống cáp điện và cáp tín hiệu đồng bộ (hoặc hệ thống thiết bị kết nối không dây), đủ cho cả hệ thống.', TRUE, TRUE, TRUE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'THPT-NN-013', E'DM-THPT-NN-016', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 490, E'1', E'Hệ thống thiết bị dạy học ngoại ngữ chuyên dụng có máy tính của học sinh (lựa chọn 3)', NULL, E'Thiết bị dạy cho giáo viên', E'Hỗ trợ giáo viên thực hiện dạy học ngoại ngữ.', E'1. Bộ máy vi tính để bàn hoặc máy tính xách tay\n- Loại thông dụng có cấu hình tối thiểu cài đặt được các hệ điều hành và các phần mềm dạy học ngoại ngữ, thời điểm trang bị máy tính không quá 2 năm so với thời điểm sản xuất;\n- Màn hình tối thiểu: 17 inch (máy tính để bàn), 14 inch (máy tính xách tay);\n- Có các cổng kết nối tối thiểu: VGA, HDMI, USB, LAN, Wifi và Bluetooth.\n2. Khối thiết bị điều khiển của giáo viên/phần mềm điều khiển cài đặt trên máy tính của giáo viên.\n3. Tai nghe có micro.\nThiết bị dạy ngoại ngữ dành cho giáo viên tối thiểu phải đảm bảo các chức năng:\n- Có thể kết nối tới máy tính của học sinh để truyền học liệu âm thanh, hình ảnh từ giáo viên tới một học sinh, một nhóm học sinh bất kỳ hoặc cả lớp;\n- Có thể kết nối tới máy tính của học sinh để truyền học liệu âm thanh, hình ảnh từ một học sinh bất kỳ trong lớp học tới một hoặc một nhóm học sinh khác;\n- Có thể chia lớp học thành nhiều nhóm để thực hành giao tiếp đồng thời;\n- Giúp giáo viên ghi âm quá trình hội thoại để phục vụ cho học sinh tự học hoặc chấm điểm;\n- Giúp giáo viên chuyển nội dung luyện đọc tới học sinh dưới dạng tệp tin;\n- Giúp giáo viên và học sinh có thể trao đổi với nhau theo dạng text (chat);\n- Giúp giáo viên giám sát các hoạt động trên máy tính của học sinh;\n- Giúp giáo viên thực hiện các bài kiểm tra trắc nghiệm hoặc tự luận.', TRUE, FALSE, TRUE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'THPT-NN-009', E'DM-THPT-NN-017', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 500, E'2', E'Hệ thống thiết bị dạy học ngoại ngữ chuyên dụng có máy tính của học sinh (lựa chọn 3)', NULL, E'Thiết bị cho học sinh', E'Hỗ trợ học sinh học ngoại ngữ.', E'Bao gồm:\n1. Máy tính/hoặc máy tính xách tay, là loại thông dụng có cấu hình tối thiểu cài đặt được các hệ điều hành và các phần mềm học ngoại ngữ, thời điểm trang bị máy tính không quá 2 năm so với thời điểm sản xuất, có các cổng kết nối tiêu chuẩn.\n2. Khối thiết bị điều khiển của học sinh/phần mềm điều khiển cài đặt trên máy tính của học sinh.\n3. Tai nghe có micro cho học sinh.\nThiết bị dạy ngoại ngữ dành cho học sinh tối thiểu phải đảm bảo chức năng:\n- Kết nối tiếp nhận được các điều khiển từ giáo viên để thực hiện các chức năng học ngoại ngữ.', FALSE, TRUE, TRUE, E'BO', E'Bộ', E'01/HS', 1, E'PER_STUDENT', NULL, NULL, NULL, E'THIET_BI_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'THPT-NN-008', E'DM-THPT-NN-018', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 510, E'3', E'Hệ thống thiết bị dạy học ngoại ngữ chuyên dụng có máy tính của học sinh (lựa chọn 3)', NULL, E'Máy chiếu đa năng hoặc Màn hình hiển thị', E'Kết nối với máy tính và các thiết bị khác để trình chiếu hoặc phát học liệu âm thanh, hình ảnh.', E'Máy chiếu:\n- Loại thông dụng.\n- Có đủ cổng kết nối phù hợp;\n- Cường độ sáng tối thiểu 3.500 Ansilumens;\n- Độ phân giải tối thiểu XGA;\n- Kích cỡ khi chiếu lên màn hình tối thiểu 100 inch;\n- Điều khiển từ xa;\n- Kèm theo màn chiếu và thiết bị điều khiển (nếu có).\nMàn hình hiển thị:\n- Loại thông dụng, màn hình tối thiểu 50 inch, FullHD.\n- Có đủ cổng kết nối phù hợp;\n- Có ngôn ngữ hiển thị Tiếng Việt;\n- Điều khiển từ xa;\n- Nguồn điện: AC 90-220V/50Hz.', TRUE, FALSE, TRUE, E'CHIEC', E'Chiếc', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'MAY_MOC_THIET_BI', E'PHYSICAL', E'SERIAL', NULL, E'THPT-NN-007', E'DM-THPT-NN-019', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 520, E'4', E'Hệ thống thiết bị dạy học ngoại ngữ chuyên dụng có máy tính của học sinh (lựa chọn 3)', NULL, E'Thiết bị âm thanh đa năng di động', E'Sử dụng trong tình huống giáo viên phát âm thanh chung cho cả lớp nghe.', E'- Tích hợp được nhiều tính năng âm ly, loa, micro, đọc các định dạng DVD, CD, SD, USB trên thiết bị;\n- Kết nối line-in, audio in, bluetooth với nguồn phát âm thanh;\n- Công suất phù hợp với lớp học;\n- Kèm theo micro;\n- Nguồn điện: AC 220V/50Hz; DC, có ắc quy/pin sạc.', TRUE, FALSE, TRUE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'MAY_MOC_THIET_BI', E'PHYSICAL', E'SERIAL', NULL, E'THPT-NN-005', E'DM-THPT-NN-020', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 530, E'5', E'Hệ thống thiết bị dạy học ngoại ngữ chuyên dụng có máy tính của học sinh (lựa chọn 3)', NULL, E'Phụ kiện', E'Dùng để cung cấp điện cho các thiết bị và mạng cho máy tính.', E'Hệ thống cáp điện và cáp mạng đủ cho cả hệ thống (hoặc hệ thống thiết bị kết nối không dây).', TRUE, TRUE, TRUE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'THPT-NN-013', E'DM-THPT-NN-021', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'TIENG_ANH', 540, E'6', E'Hệ thống thiết bị dạy học ngoại ngữ chuyên dụng có máy tính của học sinh (lựa chọn 3)', NULL, E'Bộ học liệu điện tử', E'Hỗ trợ giáo viên xây dựng kế hoạch dạy học, giáo án (điện tử), bài giảng (điện tử), học liệu (điện tử), bài tập, bài kiểm tra đánh giá.', E'Bộ học liệu điện tử được xây dựng theo chương trình môn Ngoại ngữ cấp THPT (CTGDPT 2018), không vi phạm các quy định về bản quyền, pháp luật, chủ quyền, văn hóa, dân tộc, giới, các đối tượng dễ tổn thương, có hệ thống học liệu điện tử (bài nghe, video, hình ảnh, bài giảng điện tử để dạy luyện nghe/nói cho học sinh, hệ thống câu hỏi, đề kiểm tra,) đi kèm và được tổ chức, quản lý thành hệ thống thư viện điện tử, thuận tiện cho tra cứu và sử dụng. Bộ học liệu sử dụng trên máy tính trong môi trường không có kết nối internet. Đảm bảo các chức năng:\n- Chức năng hỗ trợ soạn giáo án điện tử;\n- Chức năng chuẩn bị bài giảng điện tử;\n- Chức năng chèn các học liệu điện tử (hình ảnh, video, âm thanh) vào giáo án điện tử;\n- Chức năng tạo câu hỏi, bài tập;\n- Chức năng kiểm tra đánh giá.\nBộ học liệu điện tử gồm các bài nghe, video, hình ảnh, bài giảng điện tử để dạy luyện: nghe, nói cho học sinh. Các nội dung phải phù hợp với chương trình.', TRUE, FALSE, TRUE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-NN-006', E'DM-THPT-NN-022', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
