(E'THPT', E'THE_DUC', 960, E'12.3', E'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', E'Cầu lông', E'Cột, lưới', E'Dùng cho hoạt động giảng dạy của GV và tập luyện kĩ thuật, thực hành của HS môn Cầu lông', E'- Cột: Chất liệu bằng kim loại, có bánh xe, chốt khóa, tay quay căng lưới; chiều cao 1550mm;\nLưới: Hình chữ nhật dài, chất liệu bằng sợi vải dù hoặc tương đương. Kích thước (6100x750)mm, viền lưới rộng 20mm, kích thước mắt lưới 20-23mm. (Theo tiêu chuẩn qui định, loại dùng cho tập luyện)', TRUE, TRUE, TRUE, E'BO', E'Bộ', E'03/trường', 3, E'PER_SCHOOL', NULL, NULL, NULL, E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-GDTC-034', E'DM-THPT-GDTC-040', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'THE_DUC', 970, E'13.1', E'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', E'Cầu mây', E'Quả cầu mây', E'Dùng cho hoạt động giảng dạy của GV và tập luyện kĩ thuật, thực hành của HS môn Cầu mây', E'Hình tròn, chất liệu bằng nhựa hoặc tương đương, đàn hồi, độ nảy ổn định. Chu vi khoảng 420-450mm, trọng lượng khoảng 150-180g (Theo tiêu chuẩn qui định, loại dùng cho tập luyện)', TRUE, TRUE, TRUE, E'QUA', E'Quả', E'20/GV', 20, E'PER_TEACHER', NULL, NULL, NULL, E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-GDTC-037', E'DM-THPT-GDTC-041', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'THE_DUC', 980, E'13.2', E'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', E'Cầu mây', E'Cột, lưới', NULL, E'- Cột: Chất liệu bằng kim loại, có bánh xe, chốt khóa, tay quay căng lưới; chiều cao 1450mm (nữ) và 1550mm (nam); Lưới: Hình chữ nhật, chất liệu bằng sợi vải dù hoặc tương đương. Kích thước (6100x700)mm, viền lưới rộng 50mm, kích thước mắt lưới 60-80mm.\n(Theo tiêu chuẩn qui định, loại dùng cho tập luyện)', TRUE, TRUE, TRUE, E'BO', E'Bộ', E'03/trường', 3, E'PER_SCHOOL', NULL, NULL, NULL, E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-GDTC-034', E'DM-THPT-GDTC-042', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'THE_DUC', 990, E'14.1', E'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', E'Võ thuật', E'Trụ đấm, đá', E'Dùng cho hoạt động giảng dạy của GV và luyện tập, thực hành của HS phù hợp với đặc điểm từng môn Võ thuật', E'Hình trụ đứng, chất liệu bằng da hoặc tương đương, ruột đặc, mềm. Cao 1500- 1750mm (Theo tiêu chuẩn qui định, loại dùng cho tập luyện).', TRUE, TRUE, TRUE, E'CHIEC', E'Chiếc', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-GDTC-038', E'DM-THPT-GDTC-043', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'THE_DUC', 1000, E'14.2', E'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', E'Võ thuật', E'Đích đấm, đá (cầm tay)', E'Dùng cho hoạt động giảng dạy của GV và luyện tập, thực hành của HS phù hợp với đặc điểm từng môn Võ thuật', E'Hình elip có tay cầm hoặc bộ phận gắn lên tay, chất liệu bằng da hoặc giả da mềm, ruột đặc, mềm (Theo tiêu chuẩn qui định, loại dùng cho tập luyện).', TRUE, TRUE, TRUE, E'CHIEC', E'Chiếc', E'10/GV', 10, E'PER_TEACHER', NULL, NULL, NULL, E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-GDTC-039', E'DM-THPT-GDTC-044', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)');
INSERT INTO dm03_rows VALUES
(E'THPT', E'THE_DUC', 1010, E'14.3', E'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', E'Võ thuật', E'Thiết bị bảo hộ', E'Dùng cho hoạt động giảng dạy của GV và luyện tập, thực hành của HS phù hợp với đặc điểm từng môn Võ thuật', E'Bao gồm trang phục, phụ kiện bảo hộ các bộ phận đầu, tay, bộ hạ…như mũ, giáp, găng, xà cạp, lót ống quyển,... (Theo tiêu chuẩn được qui định cụ thể cho từng môn võ thuật, loại dùng cho tập luyện).', FALSE, TRUE, TRUE, E'BO', E'Bộ', E'02/GV', 2, E'PER_TEACHER', NULL, NULL, NULL, E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-GDTC-040', E'DM-THPT-GDTC-045', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'THE_DUC', 1020, E'14.4', E'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', E'Võ thuật', E'Thảm xốp', E'Dùng cho hoạt động giảng dạy của GV và luyện tập, thực hành của HS phù hợp với đặc điểm từng môn Võ thuật', E'Hình vuông, chất liệu bằng xốp mút hoặc tương đương, có độ đàn hồi. Kích thước (1000x1000)mm, độ dày 25mm, có thể gắn vào nhau, mặt nhám, không ngấm nước, không trơn trượt.', TRUE, TRUE, TRUE, E'CHIEC', E'Chiếc', E'40/trường', 40, E'PER_SCHOOL', NULL, NULL, NULL, E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-GDTC-041', E'DM-THPT-GDTC-046', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'THE_DUC', 1030, E'15', E'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', E'Đẩy gậy', E'Gậy', E'Dùng cho hoạt động giảng dạy của GV và tập luyện kĩ thuật, thực hành của HS môn Đẩy gậy', E'Dạng ống tròn, chất liệu bằng tre hoặc chất liệu khác phù hợp, gậy thẳng, có chiều dài 2000mm, đường kính từ 40- 50mm, mỗi nửa gậy sơn 1 màu; đầu và thân gậy phải được bào nhẵn và có đường kính bằng nhau.', TRUE, TRUE, TRUE, E'CHIEC', E'Chiếc', E'10/GV', 10, E'PER_TEACHER', NULL, NULL, NULL, E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-GDTC-042', E'DM-THPT-GDTC-047', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'THE_DUC', 1040, E'16.1', E'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', E'Cờ Vua', E'Bàn cờ, quân cờ', E'Dùng cho HS học và tập luyện môn Cờ vua', E'- Bàn cờ: Hình vuông, chất liệu bằng gỗ hoặc chất liệu khác phù hợp. Kích thước (400x400)mm;\n- Quân cờ: chất liệu bằng nhựa hoặc chất liệu khác phù hợp, kích thước: Vua cao 80mm, đế 25mm; Binh cao 33mm, đế 20mm.\n(Theo tiêu chuẩn qui định, loại dùng cho tập luyện).', FALSE, TRUE, TRUE, E'BO', E'Bộ', E'20/GV', 20, E'PER_TEACHER', NULL, NULL, NULL, E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-GDTC-043', E'DM-THPT-GDTC-048', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'THE_DUC', 1050, E'16.2', E'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', E'Cờ Vua', E'Bàn và quân cờ treo tường', E'Dùng cho GV giảng dạy môn Cờ vua', E'- Bàn cờ: Hình vuông, chất liệu mặt bàn bằng kim loại có từ tính, kích thước (800x800)mm, có móc treo;\n- Quân cờ: chất liệu bằng nhựa hoặc chất liệu khác phù hợp, kích thước phù hợp với các ô trên bàn cờ, có nam châm gắn mặt sau.\n(Theo tiêu chuẩn qui định, loại dùng cho tập luyện).', TRUE, FALSE, TRUE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-GDTC-044', E'DM-THPT-GDTC-049', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'THE_DUC', 1060, E'17.1', E'Dụng cụ, thiết bị dạy học môn thể thao tự chọn', E'Bơi', E'Phao bơi', E'Dùng cho hoạt động giảng dạy của GV và tập luyện kĩ thuật, thực', E'Chất liệu bằng cao su bơm hơi hoặc chất liệu khác phù hợp. Loại thông dụng dùng cho tập luyện', FALSE, TRUE, TRUE, E'CHIEC', E'Chiếc', E'20/trường', 20, E'PER_SCHOOL', NULL, NULL, NULL, E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-GDTC-045', E'DM-THPT-GDTC-050', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
