(E'THPT', E'LICH_SU', 1160, E'1', E'Thiết bị dùng chung', NULL, E'Bộ học liệu điện tử hỗ trợ GV', E'Giúp GV xây dựng kế hoạch dạy học (giáo án) điện tử, chuẩn bị bài giảng điện tử, các học liệu điện tử, các bài tập, bài kiểm tra, đánh giá điện tử phù hợp với Chương trình môn học 2018', E'Bộ học liệu điện tử được xây dựng theo Chương trình môn Lịch sử cấp THPT (CTGDPT 2018), có hệ thống học liệu điện tử (hình ảnh, bản đồ, sơ đồ, lược đồ, âm thanh, video, các câu hỏi, đề kiểm tra) đi kèm và được tổ chức, quản lý thành hệ thống thư viện điện tử, thuận lợi cho tra cứu và sử dụng. Bộ học liệu sử dụng được trên PC trong môi trường không kết nối internet. Phải đảm bảo tối thiểu các chức năng:\n- Chức năng hỗ trợ soạn kế hoạch bài học (giáo án) điện tử;\n- Chức năng hướng dẫn chuẩn bị bài giảng điện tử;\n- Chức năng hướng dẫn, chuẩn bị và sử dụng học liệu điện tử (hình ảnh, bản đồ, sơ đồ, lược đồ, âm thanh);\n- Chức năng hướng dẫn và chuẩn bị các bài tập;\n- Chức năng hỗ trợ chuẩn bị công tác đánh giá.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10,11,12', E'Dùng cho lớp 10,11, 12', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-LS-001', E'DM-THPT-LS-001', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'LICH_SU', 1170, E'1.1', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Một số nền văn minh thế giới thời kì cổ - trung đại', E'Lược đồ các quốc gia cổ đại phương Đông và phương Tây', E'Xác định vị trí địa lí của các quốc gia cổ đại phương Đông và phương Tây', E'- Lược đồ treo tường. Nội dung lược đồ thể hiện vị trí địa lí, điều kiện tự nhiên của các quốc gia cổ đại phương Đông và phương Tây (Ai Cập, Trung Hoa, Ấn Độ, Hy Lạp – La Mã);\n- Đảm bảo tính khoa học, phản ánh đầy đủ các đối tượng có ảnh hưởng trực tiếp đến sự kiện, hiện tượng lịch sử trên lược đồ về màu sắc, kí hiệu, kích thước, phân bố, vị trí địa lí, địa danh;\n- Tỉ lệ 1:15.000.000; kích thước (720x1020)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-LS-002', E'DM-THPT-LS-002', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'LICH_SU', 1180, E'2.1', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Văn minh Đông Nam Á', E'Lược đồ các quốc gia Đông Nam Á cổ và phong kiến', E'Xác định vị trí địa lí của các quốc gia Đông Nam Á cổ và phong kiến', E'- Lược đồ treo tường. Nội dung lược đồ thể hiện vị trí địa lí, điều kiện tự nhiên của các quốc gia Đông Nam Á cổ và phong kiến;\n- Đảm bảo tính khoa học, phản ánh đầy đủ các đối tượng có ảnh hưởng trực tiếp đến sự kiện, hiện tượng lịch sử trên lược đồ về màu sắc, kí hiệu, kích thước, phân bố, vị trí địa lí, địa danh;\n- Tỉ lệ 1:6.000.000; kích thước (720x1020)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-LS-003', E'DM-THPT-LS-003', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'LICH_SU', 1190, E'3.1', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Chuyên đề 10.2: Bảo tồn và phát huy giá trị di sản văn hóa ở Việt Nam', E'Lược đồ di sản văn hóa ở Việt Nam', E'Xác định vị trí phân bố và giới thiệu nét cơ bản của các di sản văn hóa ở Việt Nam', E'- Lược đồ treo tường. Nội dung lược đồ thể hiện sự phân bố và những nét cơ bản về các di sản văn hóa ở Việt Nam (Di sản được UNESCO công nhận);\n- Lược đồ có kèm ảnh về các di sản văn hóa phi vật thể, di sản văn hóa vật thể, di sản thiên nhiên, di sản phức hợp;\n- Đảm bảo tính khoa học, phản ánh đầy đủ các đối tượng có ảnh hưởng trực tiếp đến sự kiện, hiện tượng lịch sử trên lược đồ về màu sắc, kí hiệu, kích thước, phân bố, vị trí địa lí, địa danh. Thể hiện đầy đủ quần đảo Trường Sa và Hoàng Sa;\n- Tỉ lệ 1:15.000.000; kích thước (720x1020)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-LS-004', E'DM-THPT-LS-004', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'LICH_SU', 1200, E'1.1', E'Thiết bị theo các chủ đề › Băng/đĩa/phần mềm/video-clip', E'Lịch sử và sử học', E'Phim tài liệu: Một số hiện vật tiêu biểu của nền văn minh sông Hồng và văn minh Đại Việt', E'Giúp HS nhận diện hình dáng, đặc điểm hiện vật của nền văn minh sông Hồng, văn minh Đại Việt', E'02 phim tài liệu có nội dung thể hiện một số hiện vật tiêu biểu của nền văn minh sông Hồng và văn minh Đại Việt:\n- 01 phim giới thiệu hiện vật khảo cổ học Hoàng thành Thăng Long;\n- 01 phim giới thiệu hiện vật gồm một số hiện vật như Trống đồng Đông Sơn, các công cụ khai hoang (rìu, dao), công cụ làm đất (lưỡi cày, mai, thuổng), công cụ gặt hái (liềm, nhíp, hái);\n- 01 phim giới thiệu hiện vật gồm một số hiện vật như đầu rồng, lá đề hình rồng, phượng, gạch, ngói.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-LS-005', E'DM-THPT-LS-005', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'LICH_SU', 1210, E'2.1', E'Thiết bị theo các chủ đề › Băng/đĩa/phần mềm/video-clip', E'Một số nền văn minh thế giới thời kì cổ - trung đại', E'Phim tài liệu: Thành tựu tiêu biểu của một số nền văn minh phương Đông', E'Giúp HS khái quát thành tựu tiêu biểu của một số nền văn minh phương Đông', E'03 phim tài liệu có nội dung giới thiệu về thành tựu tiêu biểu của một số nền văn minh phương Đông:\n- 01 phim giới thiệu về thành tựu của văn minh Ai Cập (chữ viết, khoa học tự nhiên, kiến trúc, điêu khắc);\n- 01 phim giới thiệu về thành tựu của văn minh Trung Hoa (chữ viết, văn học nghệ thuật, sử học, khoa học tự nhiên, y học, thiên văn học, lịch pháp, tư tưởng);\n- 01 phim giới thiệu về thành tựu của văn minh Ấn Độ (chữ viết, văn học nghệ thuật, khoa học tự nhiên, tư tưởng).', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-LS-006', E'DM-THPT-LS-006', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'LICH_SU', 1220, E'2.2', E'Thiết bị theo các chủ đề › Băng/đĩa/phần mềm/video-clip', E'Một số nền văn minh thế giới thời kì cổ - trung đại', E'Phim tài liệu: Thành tựu tiêu biểu của một số nền văn minh phương Tây', E'Giúp HS khái quát thành tựu tiêu biểu của một số nền văn minh phương Tây', E'02 phim tài liệu có nội dung giới thiệu về thành tựu tiêu biểu của một số nền văn minh phương Tây:\n- 01 phim giới thiệu về thành tựu của văn minh Hy Lạp-La Mã (chữ viết, thiên văn học, lịch pháp, văn học, nghệ thuật, khoa học tự nhiên, tư tưởng, thể thao);\n- 01 phim giới thiệu về thành tựu của văn minh thời Phục Hưng (tư tưởng, văn học, nghệ thuật, khoa học kĩ thuật, thiên văn học).', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-LS-007', E'DM-THPT-LS-007', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'LICH_SU', 1230, E'3.1', E'Thiết bị theo các chủ đề › Băng/đĩa/phần mềm/video-clip', E'Các cuộc cách mạng công nghiệp trong lịch sử thế giới', E'Phim tài liệu: Thành tựu của cuộc cách mạng công nghiệp lần thứ nhất', E'Giúp HS khái quát bối cảnh lịch sử và thành tựu cơ bản của Cách mạng công nghiệp lần thứ nhất', E'02 phim tài liệu có nội dung giới thiệu về thành tựu của cuộc cách mạng công nghiệp lần thứ nhất:\n- 01 phim giới thiệu những nét chính về bối cảnh lịch sử diễn ra Cách mạng công nghiệp lần thứ nhất (nửa sau thế kỉ XVIII – nửa đầu thế kỉ XIX);\n- 01 phim giới thiệu thành tựu cơ bản của Cách mạng công nghiệp lần thứ nhất (phát minh và sử dụng máy hơi nước, động cơ đốt trong).', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-LS-008', E'DM-THPT-LS-008', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'LICH_SU', 1240, E'3.2', E'Thiết bị theo các chủ đề › Băng/đĩa/phần mềm/video-clip', E'Các cuộc cách mạng công nghiệp trong lịch sử thế giới', E'Phim tài liệu: Thành tựu của cuộc cách mạng công nghiệp lần thứ hai', E'Giúp HS khái quát bối cảnh lịch sử và thành tựu cơ bản của Cách mạng công nghiệp lần thứ hai', E'02 phim tài liệu có nội dung giới thiệu về thành tựu của cuộc cách mạng công nghiệp lần thứ hai:\n- 01 phim giới thiệu những nét chính về bối cảnh lịch sử diễn ra Cách mạng công nghiệp lần thứ hai (nửa sau thế kỉ XIX – đầu thế kỉ XX);\n- 01 phim giới thiệu thành tựu cơ bản của Cách mạng công nghiệp lần thứ hai (sử dụng điện năng, động cơ điện gắn với quá trình điện khí hoá, sản xuất dây chuyền, sự phát triển của các ngành công nghiệp hoá chất, dầu mỏ, thép, điện lực, in ấn).', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-LS-009', E'DM-THPT-LS-009', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'LICH_SU', 1250, E'3.3', E'Thiết bị theo các chủ đề › Băng/đĩa/phần mềm/video-clip', E'Các cuộc cách mạng công nghiệp trong lịch sử thế giới', E'Phim tài liệu: Thành tựu của cuộc cách mạng công nghiệp lần thứ ba', E'Giúp HS khái quát bối cảnh lịch sử và thành tựu cơ bản của Cách mạng công nghiệp lần thứ ba', E'02 phim tài liệu có nội dung giới thiệu về thành tựu của cuộc cách mạng công nghiệp lần thứ ba:\n- 01 phim giới thiệu những nét chính về bối cảnh lịch sử diễn ra Cách mạng công nghiệp lần thứ ba (nửa sau thế kỉ XX);\n- 01 phim giới thiệu thành tựu cơ bản của Cách mạng công nghiệp lần thứ ba (tự động hoá dựa vào máy tính, sử dụng thiết bị điện tử, công nghệ thông tin, internet).', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-LS-010', E'DM-THPT-LS-010', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'LICH_SU', 1260, E'3.4', E'Thiết bị theo các chủ đề › Băng/đĩa/phần mềm/video-clip', E'Các cuộc cách mạng công nghiệp trong lịch sử thế giới', E'Phim tài liệu: Thành tựu của cuộc cách mạng công nghiệp lần thứ tư', E'Giúp HS khái quát bối cảnh lịch sử và thành tựu cơ bản của Cách mạng công nghiệp lần thứ tư', E'02 phim tài liệu có nội dung giới thiệu về thành tựu của cuộc cách mạng công nghiệp lần thứ tư:\n- 01 phim giới thiệu những nét chính về bối cảnh lịch sử diễn ra Cách mạng công nghiệp lần thứ tư (những năm đầu thế kỉ XXI);\n- 01 phim giới thiệu thành tựu cơ bản của Cách mạng công nghiệp lần thứ tư (sự phát triển kĩ thuật số, trí tuệ nhân tạo, công nghệ sinh học và sự phát triển của các công nghệ liên ngành, đa ngành).', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-LS-011', E'DM-THPT-LS-011', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'LICH_SU', 1270, E'4.1', E'Thiết bị theo các chủ đề › Băng/đĩa/phần mềm/video-clip', E'Văn minh Đông Nam Á', E'Phim tư liệu: Thành tựu của văn minh Đông Nam Á', E'Giúp HS khái quát cơ sở hình thành, thời kì phát triển và thành tựu tiêu biểu của văn minh Đông Nam Á', E'Phim gồm một số đoạn giới thiệu sơ lược cơ sở hình thành, thời kì phát triển và thành tựu tiêu biểu của văn minh Đông Nam Á (văn hoá, kiến trúc và điêu khắc).', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-LS-012', E'DM-THPT-LS-012', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'LICH_SU', 1280, E'5.1', E'Thiết bị theo các chủ đề › Băng/đĩa/phần mềm/video-clip', E'Một số nền văn minh trên đất nước Việt Nam (trước năm 1858)', E'Phim mô phỏng: Thành tựu của các nền văn minh trên đất nước Việt Nam (trước năm 1858)', E'Giúp HS khái quát cơ sở hình thành và thành tựu tiêu biểu của các nền văn minh trên đất nước Việt Nam (trước năm 1858)', E'04 phim có nội dung giới thiệu về cơ sở hình thành và thành tựu tiêu biểu của các nền văn minh trên đất nước Việt Nam (trước năm 1858):\n- 01 phim về cơ sở hình thành (điều kiện tự nhiên, cơ sở xã hội) và thành tựu tiêu biểu (đời sống vật chất, đời sống tinh thần, tổ chức xã hội, nhà nước) của văn minh sông Hồng;\n- 01 phim về cơ sở hình thành và thành tựu (đời sống vật chất, đời sống tinh thần, tổ chức xã hội, nhà nước) của Văn minh Champa;\n- 01 phim về cơ sở hình thành và thành tựu (đời sống vật chất, đời sống tinh thần, tổ chức xã hội, nhà nước) của Văn minh Phù Nam;\n- 01 phim giới thiệu được cơ sở hình thành, quá trình phát triển và thành tựu cơ bản về (kinh tế, chính trị, tư tưởng, văn hoá, giáo dục, văn học, nghệ thuật) của văn minh Đại Việt.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-LS-013', E'DM-THPT-LS-013', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'LICH_SU', 1290, E'6.1', E'Thiết bị theo các chủ đề › Băng/đĩa/phần mềm/video-clip', E'Cộng đồng các dân tộc Việt Nam', E'Phim tư liệu: Đời sống vật chất và tinh thần của cộng đồng các dân tộc Việt Nam', E'Giúp HS mô tả đời sống vật chất và tinh thần của cộng đồng các dân tộc Việt Nam', E'Phim gồm một số đoạn tư liệu giới thiệu nét chính về đời sống vật chất (sản xuất nông nghiệp, ngành nghề thủ công) và nêu được nét chính về đời sống tinh thần (sự đa dạng về văn hóa, lễ hội, phong tục, tập quán) của cộng đồng các dân tộc Việt Nam.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-LS-014', E'DM-THPT-LS-014', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'LICH_SU', 1300, E'7.1', E'Thiết bị theo các chủ đề › Băng/đĩa/phần mềm/video-clip', E'Chuyên đề 10.2: Bảo tồn và phát huy giá trị di sản văn hóa ở Việt Nam', E'Video/clip: Di sản văn hóa ở Việt Nam', E'Giới thiệu nét cơ bản về di sản văn hóa ở Việt Nam', E'04 Video/clip có nội dung về các loại hình Di sản văn hoá ở Việt Nam:\n- 01 Video/clip giới thiệu những nét cơ bản về di sản văn hóa phi vật thể tiêu biểu (dân ca quan họ Bắc Ninh, ca trù, không gian văn hóa cồng chiêng Tây Nguyên, nhã nhạc cung đình Huế, đờn ca tài tử Nam Bộ);\n- 01 Video/clip giới thiệu những nét cơ bản về di sản văn hóa vật thể tiêu biểu (trống đồng Đông Sơn, thành Cổ Loa, Hoàng thành Thăng Long, Văn Miếu– Quốc Tử Giám, Quảng trường Ba Đình và Di tích lịch sử Khu lưu niệm Chủ tịch Hồ Chí Minh, thành nhà Hồ, cố đô Huế, tháp Chăm).\n- 01 Video/clip giới thiệu những nét cơ bản về di sản văn hóa thiên nhiên tiêu biểu (Cao nguyên đá Đồng Văn, Non nước Cao Bằng, Vịnh Hạ Long, vườn quốc gia Cát Tiên);\n- 01 Video/clip giới thiệu những nét cơ bản về di sản văn hóa phức hợp tiêu biểu (Khu di tích – danh thắng Tràng An (Ninh Bình), khu di tích – danh thắng Yên Tử (Quảng Ninh).', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-LS-015', E'DM-THPT-LS-015', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'LICH_SU', 1310, E'1.1', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Cách mạng tư sản và sự phát triển của chủ nghĩa tư bản', E'Lược đồ thế giới thế kỉ XVI – thế kỉ XVIII', E'HS biết được vị trí các địa điểm diễn ra các cuộc cách mạng tư sản tiêu biểu từ thế kỉ XVI đến thế kỉ XVIII', E'- 03 lược đồ treo tường, mỗi lược đồ thể hiển một nội dung:\n+ 01 lược đồ thể hiện vị trí của các địa điểm – nơi diễn ra các sự kiện lịch sử quan trọng của cuộc cách mạng tư sản Anh ở thế kỉ XVII;\n+ 01 lược đồ thể hiện địa điểm và tiến trình lịch sử một số sự kiện tiêu biểu của cuộc chiến tranh giành độc lập của 13 thuộc địa Anh ở Bắc Mỹ (thế kỉ XVIII);\n+ 01 lược đồ thể hiện địa điểm và tiến trình lịch sử của một số sự kiện tiêu biểu của cuộc cách mạng tư sản Pháp (thế kỉ XVIII);\n- Lược đồ có kèm hình ảnh các vị trí diễn ra các cuộc cách mạng, cuộc đấu tranh.\n- Đảm bảo tính khoa học, phản ánh đầy đủ các đối tượng có ảnh hưởng trực tiếp đến sự kiện, hiện tượng lịch sử trên lược đồ về màu sắc, kí hiệu, kích thước, phân bố, vị trí địa lí, địa danh.\n- Tỉ lệ 1:15.000.000, kích thước (720x1020)mm.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-LS-016', E'DM-THPT-LS-016', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'LICH_SU', 1320, E'2.1', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Quá trình giành độc lập dân tộc của các quốc gia Đông Nam Á', E'Lược đồ Đông Nam Á cuối thế kỉ XIX đầu thế kỉ XX', E'Giúp HS xác định vị trí, phạm vi của các quốc gia hay khu vực thuộc địa ở khu vực Đông Nam Á cuối thế kỉ XIX đầu thế kỉ XX', E'- 03 Lược đồ Đông Nam Á, bao gồm:\n+ 01 Lược đồ Đông Nam Á cuối thế kỉ XIX đến năm 1920;\n+ 01 Lược đồ Đông Nam Á từ năm 1920 đến năm 1945;\n+ 01 Lược đồ Đông Nam Á từ năm 1945 đến năm 1975;\n- Lược đồ thể hiện được vị trí, phạm vi của các quốc gia hay các khu vực thuộc địa ở khu vực Đông Nam Á trong từng thời kỳ lịch sử.\n- Đảm bảo tính khoa học, phản ánh đầy đủ các đối tượng có ảnh hưởng trực tiếp đến sự kiện, hiện tượng lịch sử trên lược đồ về màu sắc, kí hiệu, kích thước, phân bố, vị trí địa lí, địa danh.\n- Tỉ lệ 1:15.000.000, kích thước (720x1020)mm.', FALSE, TRUE, FALSE, E'BO', E'Bộ', NULL, NULL, NULL, NULL, NULL, E'01/GV', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-LS-017', E'DM-THPT-LS-017', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'LICH_SU', 1330, E'3.1', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Chiến tranh bảo vệ Tổ quốc và chiến tranh giải phóng dân tộc trong lịch sử Việt Nam (trước Cách mạng tháng Tám năm 1945)', E'Lược đồ Chiến thắng Bạch Đằng (năm 938)', E'Giúp HS xác định các vị trí diễn ra và diễn biến của trận Bạch Đằng trên lược đồ', E'- Lược đồ treo tường. Nội dung lược đồ thể hiện các vị trí diễn ra và diễn biến của trận Bạch Đằng năm 938. Lược đồ có kèm hình ảnh các vị trí diễn ra trận Bạch Đằng.\n- Đảm bảo tính khoa học, phản ánh đầy đủ các đối tượng có ảnh hưởng trực tiếp đến sự kiện, hiện tượng lịch sử trên lược đồ về màu sắc, kí hiệu, kích thước, phân bố, vị trí địa lí, địa danh.\n- Tỉ lệ 1:15.000.000, kích thước (720x1020)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-LS-018', E'DM-THPT-LS-018', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'LICH_SU', 1340, E'3.2', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Chiến tranh bảo vệ Tổ quốc và chiến tranh giải phóng dân tộc trong lịch sử Việt Nam (trước Cách mạng tháng Tám năm 1945)', E'Lược đồ Kháng chiến chống Tống thời Lý (1075-1077)', E'Giúp HS xác định các vị trí diễn ra và diễn biến của cuộc kháng chiến chống Tống trên lược đồ', E'- Lược đồ treo tường. Nội dung lược đồ thể hiện các vị trí diễn ra và diễn biến của cuộc kháng chiến chống Tống (1075-1077). Lược đồ có kèm hình ảnh các vị trí diễn ra cuộc kháng chiến.\n- Đảm bảo tính khoa học, phản ánh đầy đủ các đối tượng có ảnh hưởng trực tiếp đến sự kiện, hiện tượng lịch sử trên lược đồ về màu sắc, kí hiệu, kích thước, phân bố, vị trí địa lí, địa danh.\n- Tỉ lệ 1:15.000.000, kích thước (720x1020)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-LS-019', E'DM-THPT-LS-019', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
