(E'THPT', E'LICH_SU', 1500, E'3.1', E'Thiết bị theo các chủ đề › Băng/đĩa/phần mềm/video-clip', E'Công cuộc đổi mới ở Việt Nam từ năm 1986 đến nay', E'Video/clip: Thành tựu của Việt Nam trong thời kì đổi mới đất nước', E'Giúp HS hiểu bối cảnh lịch sử và thành tựu của Việt Nam trong thời kì đổi mới đất nước', E'Video/clip gồm một số đoạn tư liệu giới thiệu về bối cảnh lịch sử, thành tựu của Việt Nam trong thời kì đổi mới đất nước qua các giai đoạn chính:\n- Giai đoạn 1986 – 1995: khởi đầu công cuộc đổi mới;\n- Giai đoạn 1996 – 2006: đẩy mạnh công nghiệp hoá, hiện đại hoá, hội nhập kinh tế quốc tế;\n- Giai đoạn từ năm 2007 đến nay: tiếp tục đẩy mạnh công nghiệp hoá, hiện đại hoá, hội nhập quốc tế sâu rộng.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-LS-035', E'DM-THPT-LS-035', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'LICH_SU', 1510, E'4.1', E'Thiết bị theo các chủ đề › Băng/đĩa/phần mềm/video-clip', E'Hồ Chí Minh trong lịch sử Việt Nam', E'Phim tư liệu: Hồ Chí Minh – Anh hùng giải phóng dân tộc', E'Giúp HS hiểu được những nét cơ bản về hành trình tìm đường cứu nước; vai trò sáng lập Đảng Cộng sản Việt Nam, lãnh đạo Cách mạng tháng Tám 1945, kháng chiến chống Pháp (1945 – 1954) và chống Mỹ (1954 – 1969)', E'05 phim tư liệu có nội dung về hành trình tìm đường cứu nước; vai trò sáng lập Đảng Cộng sản Việt Nam, lãnh đạo Cách mạng tháng Tám 1945, kháng chiến chống Pháp (1945 – 1954) và chống Mỹ (1954 – 1969):\n- 01 phim về hành trình đi tìm đường cứu nước của Hồ Chí Minh;\n- 01 phim về quá trình chuẩn bị về chính trị, tư tưởng, tổ chức của Hồ Chí Minh cho sự ra đời của Đảng Cộng sản Việt Nam;\n- 01 phim về vai trò của Hồ Chí Minh đối với việc lãnh đạo Cách mạng tháng Tám 1945 (triệu tập Hội nghị Ban chấp hành Trung ương lần thứ 8 (tháng 5 năm 1941); thành lập Mặt trận Việt Minh;\n- 01 phim về vai trò của Hồ Chí Minh trong kháng chiến chống Pháp (1946 – 1954);\n- 01 phim về vai trò của Hồ Chí Minh trong kháng chiến chống Mỹ (1954 – 1969).', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-LS-036', E'DM-THPT-LS-036', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'LICH_SU', 1520, E'4.2', E'Thiết bị theo các chủ đề › Băng/đĩa/phần mềm/video-clip', E'Hồ Chí Minh trong lịch sử Việt Nam', E'Phim tư liệu: Dấu ấn Hồ Chí Minh trong lòng nhân dân thế giới và Việt Nam', E'Giúp HS hiểu được những dấu ấn Hồ Chí Minh trong lòng nhân dân thế giới và Việt Nam', E'02 phim tư liệu có nội dung về dấu ấn Hồ Chí Minh trong lòng nhân dân thế giới và Việt Nam:\n- 01 phim giới thiệu dấu ấn của Hồ Chí Minh trong lòng nhân dân thế giới (Năm 1987, UNECO công nhận Hồ Chí Minh là anh hùng giải phóng dân tộc, nhà văn hoá lớn; những cống hiến về giá trị tư tưởng, văn hoá; Hình ảnh một số công trình tưởng niệm: Nhà lưu niệm, Đài kỉ niệm);\n- 01 phim giới thiệu về dấu ấn của Hồ Chí Minh trong lòng nhân dân Việt Nam (Bảo tàng, Nhà lưu niệm; Hình tượng văn học, nghệ thuật; Phong trào học tập và làm theo tư tưởng, đạo đức và phong cách Hồ Chí Minh).', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-LS-037', E'DM-THPT-LS-037', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1530, E'1.1', E'Thiết bị theo các chủ đề › Tranh ảnh', E'Chủ đề: Trái Đất', E'Tranh cấu trúc của Trái Đất', E'HS tìm hiểu cấu trúc của Trái Đất', E'- Nội dung tranh thể hiện cấu trúc của Trái Đất, gồm có: lớp vỏ Trái Đất, lớp Manti, nhân Trái Đất;\n- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DL-001', E'DM-THPT-DL-001', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1540, E'1.2', E'Thiết bị theo các chủ đề › Tranh ảnh', E'Chủ đề: Trái Đất', E'Tranh cấu tạo vỏ Trái Đất và vỏ địa lí', E'HS quan sát cấu tạo của vỏ Trái Đất và phân biệt vỏ địa lí với vỏ Trái Đất', E'Nội dung tranh thể hiện các nội dung:\n- Cấu tạo của vỏ Trái Đất ở lục địa và đại dương;\n- Giới hạn của vỏ địa lí ở lục địa và đại dương. Giới hạn trên: phía dưới lớp ô zôn; giới hạn dưới: đáy vực thẳm ở đại dương và đáy lớp vỏ phong hóa ở lục địa; chiều dày vỏ địa lí khoảng 30 – 35 km;\n- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10 Dùng chung với chủ đề: Một số quy luật của vỏ địa lí', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DL-002', E'DM-THPT-DL-002', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1550, E'2.1', E'Thiết bị theo các chủ đề › Tranh ảnh', E'Chủ đề: Thạch quyển', E'Tranh một số dạng địa hình được tạo thành do nội lực và ngoại lực', E'HS tìm hiểu tác động của nội lực và ngoại lực đến địa hình bề mặt Trái Đất', E'Nội dung tranh thể hiện các nội dung:\n- Một số dạng địa hình được tạo thành do nội lực như: núi, hẻm vực, thung lũng, núi lửa;\n- Một số dạng địa hình được tạo thành do ngoại lực như: bậc thềm sóng vỗ, cồn cát, bãi bồi, hang động.\n- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DL-003', E'DM-THPT-DL-003', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1560, E'3.1', E'Thiết bị theo các chủ đề › Tranh ảnh', E'Chủ đề: Sinh quyển', E'Sơ đồ giới hạn của sinh quyển', E'HS xác định giới hạn của sinh quyển', E'- Sơ đồ thể hiện nội dung: giới hạn của sinh quyển bao gồm toàn bộ thủy quyển, phần thấp của khí quyển, lớp phủ thổ nhưỡng và lớp vỏ phong hóa (Giới hạn phía trên: Là nơi tiếp giáp lớp ô dôn của khí quyển; Giới hạn phía dưới: ở đại dương >11km và ở lục địa là lớp vỏ phong hóa);\n- Kích thước (420x590)mm.', FALSE, TRUE, FALSE, E'TO', E'Tờ', E'04/GV', 4, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DL-004', E'DM-THPT-DL-004', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1570, E'1.1', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Chủ đề: Trái Đất', E'Lược đồ các mảng kiến tạo, các vành đai động đất và núi lửa trên Trái Đất', E'HS xác định các mảng kiến tạo; phân bố các vùng núi trẻ, vành đai động đất và núi lửa trên Trái Đất', E'Lược đồ treo tường thể hiện nội dung:\n- 07 mảng kiến tạo lớn: mảng Thái Bình Dương, mảng Ấn Độ - Ôxtrâylia, mảng Âu - Á, mảng Phi, mảng Bắc Mĩ, mảng Nam Mĩ, mảng Nam Cực và một số mảng nhỏ;\n- Hướng di chuyển của các mảng kiến tạo;\n- Phân bố các vùng núi trẻ, vành đai động đất và núi lửa.\nKích thước (1500x1090)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10 Dùng chung chủ đề :Thạch quyển', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DL-005', E'DM-THPT-DL-005', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1580, E'2.1', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Chủ đề: Khí quyển', E'Bản đồ nhiệt độ không khí trên Trái Đất', E'HS xác định sự phân bố nhiệt độ không khí trên Trái Đất theo vĩ độ; lục địa, đại dương và địa hình', E'Bản đồ treo tường thể hiện nội dung:\n- Phân bố nhiệt độ không khí trên Trái Đất theo vĩ độ địa lí.\n- Phân bố nhiệt độ không khí trên Trái Đất theo lục địa và đại dương.\n- Phân bố nhiệt độ không khí trên Trái Đất theo địa hình.\nKích thước (1500x1090)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DL-006', E'DM-THPT-DL-006', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1590, E'2.2', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Chủ đề: Khí quyển', E'Bản đồ các đới và kiểu khí hậu trên Trái Đất', E'HS xác định các đới khí hậu và một số kiểu khí hậu trên Trái Đất', E'Bản đồ treo tường thể hiện nội dung:\n- Trái Đất có 7 đới khí hậu xen kẽ nhau từ xích đạo về hai cực. Trong đới khí hậu có kiểu khí hậu, bao gồm:\n(1) Đới khí hậu xích đạo;\n(2) Đới khí hậu cận xích đạo;\n(3) Đới khí hậu nhiệt đới (Kiểu khí hậu nhiệt đới gió mùa và Kiểu khí hậu nhiệt đới lục địa);\n(4) Đới khí hậu cận nhiệt (Kiểu khí hậu cận nhiệt lục địa; Kiểu khí hậu cận nhiệt gió mùa và Kiểu khí hậu cận nhiệt địa trung hải);\n(5) Đới khí hậu ôn đới (Kiểu khí hậu ôn đới lục địa và Kiểu khí hậu ôn đới hải dương);\n(6) Đới khí hậu cận cực; (7) Đới khí hậu cực.\n- Biểu đồ nhiệt độ, lượng mưa ở một số địa điểm có các kiểu khí hậu khác nhau;\n- Kích thước (1500x1090)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DL-007', E'DM-THPT-DL-007', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1600, E'2.3', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Chủ đề: Khí quyển', E'Bản đồ phân bố lượng mưa trung bình năm trên Trái Đất', E'HS xác định sự phân bố lượng mưa trung bình năm trên Trái Đất', E'Bản đồ treo tường thể hiện nội dung:\n- Phân bố lượng mưa trung bình năm trên các lục địa;\n- Một số địa điểm có lượng mưa trung bình năm rất nhiều hoặc rất ít so với các địa điểm khác trong cùng vĩ độ;\n- Kích thước (1500x1090)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DL-008', E'DM-THPT-DL-008', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1610, E'3.1', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Chủ đề: Thủy quyển', E'Bản đồ các dòng biển trong đại dương trên thế giới', E'HS xác định sự phân bố của các dòng biển trong đại dương trên thế giới', E'- Bản đồ treo tường thể hiện nội dung: các dòng biển nóng và các dòng biển lạnh trong 5 đại dương trên thế giới (nơi phát sinh, hướng chuyển động);\n- Kích thước (1500x1090)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DL-009', E'DM-THPT-DL-009', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1620, E'4.1', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Chủ đề: Sinh quyển', E'Bản đồ phân bố của các nhóm đất và sinh vật trên Trái Đất', E'HS xác định sự phân bố các nhóm đất chính và các kiểu thảm thực vật chính trên Trái Đất', E'Bản đồ treo tường thể hiện nội dung:\n- Bản đồ phân bố các nhóm đất chính theo vĩ độ, từ cực đến xích đạo bao gồm:\n(1) Băng tuyết;\n(2) Đất đài nguyên;\n(3) Đất pốt dôn;\n(4) Đất nâu, xám rừng lá rộng ôn đới;\n(5) Đất đen, hạt dẻ thảo nguyên, đồng cỏ núi cao;\n(6) Đất đỏ nâu rừng và cây bụi lá cứng;\n(7) Đất đỏ vàng cận nhiệt ẩm;\n(8) Đất xám hoang mạc, bán hoang mạc;\n(9) Đất đỏ, nâu đỏ xa van;\n(10) Đất đỏ vàng (feralit), đen nhiệt đới;\n- Bản đồ phân bố các kiểu thảm thực vật chính theo vĩ độ, từ cực đến xích đạo bao gồm:\n(1) Hoang mạc lạnh;\n(2) Đài nguyên;\n(3) Rừng lá kim;\n(4) Rừng lá rộng và rừng hỗn hợp ôn đới;\n(5) Rừng cận nhiệt ẩm;\n(6) Rừng và cây bụi lá cứng cận nhiệt; (7) Hoang mạc, bán hoang mạc;\n(8) Thảo nguyên, cây bụi chịu hạn và đồng cỏ núi cao;\n(9) Xa van, cây bụi;\n(10) Rừng nhiệt đới, xích đạo;\n- Kích thước (1090x1500)mm;', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DL-010', E'DM-THPT-DL-010', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1630, E'5.1', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Chủ đề: Địa lí các ngành kinh tế', E'Bản đồ phân bố cây trồng và vật nuôi trên thế giới', E'HS xác định sự phân bố của một số cây trồng và vật nuôi phổ biến trên thế giới', E'Bản đồ treo tường thể hiện nội dung:\n- Phân bố của một số cây trồng phổ biến trên thế giới như: Cây lương thực (lúa gạo, lúa mì, ngô); Cây công nghiệp (mía, củ cải đường, cà phê, chè, cao su);\n- Phân bố của một số vật nuôi phổ biến trên thế giới như: Gia súc lớn (trâu, bò); Gia súc nhỏ (lợn, cừu, dê); Gia cầm.\n- Kích thước (1500x1090)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DL-011', E'DM-THPT-DL-011', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1640, E'5.2', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Chủ đề: Địa lí các ngành kinh tế', E'Bản đồ phân bố một số ngành công nghiệp trên thế giới', E'HS xác định sự phân bố của một số ngành công nghiệp trên thế giới', E'- Bản đồ treo tường thể hiện nội dung: phân bố của một số ngành công nghiệp trên thế giới (Khai thác than, dầu khí, quặng kim loại; Điện lực; Điện tử, tin học; Sản xuất hàng tiêu dùng; Thực phẩm).\n- Kích thước (1500x1090)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DL-012', E'DM-THPT-DL-012', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
