(E'THPT', E'DIA_LY', 1810, E'19.1', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Chủ đề: Vấn đề phát triển dịch vụ', E'Bản đồ giao thông vận tải và bưu chính viễn thông Việt Nam', E'HS xác định sự phân bố ngành giao thông vận tải và bưu chính viễn thông ở nước ta', E'- Bản đồ treo tường thể hiện nội dung:\n+ Phân bố hệ thống giao thông vận tải: đường ô tô (quốc lộ, tỉnh lộ), đường sắt, đường thủy (đường sông, đường biển), đường hàng không, đường ống;\n+ Vị trí các bến cảng (cảng sông, cảng biển), sân bay, cửa khẩu quốc tế, các điểm bưu chính viễn thông lớn.\n- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'12', E'Dùng cho lớp 12', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DL-029', E'DM-THPT-DL-029', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1820, E'19.2', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Chủ đề: Vấn đề phát triển dịch vụ', E'Bản đồ thương mại và du lịch Việt Nam', E'HS xác định sự phân bố ngành thương mại và du lịch ở nước ta', E'- Bản đồ treo tường thể hiện nội dung:\n+ Vị trí các bến cảng (cảng sông, cảng biển), sân bay, cửa khẩu quốc tế, các trung tâm thương mại lớn;\n+ Phân bố các điểm du lịch như: di sản thế giới, di tích lịch sử - văn hóa, danh lam thắng cảnh, vườn quốc gia, khu bảo tồn thiên nhiên, khu dự trữ sinh quyển, hang động, biển đảo, khu vui chơi giải trí, nghỉ dưỡng.\n- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'12', E'Dùng cho lớp 12', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DL-030', E'DM-THPT-DL-030', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1830, E'20.1', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Chủ đề: Khai thác thế mạnh ở Trung du và miền núi Bắc Bộ', E'Bản đồ Trung du và miền núi Bắc Bộ', E'HS tìm hiểu một số thế mạnh về khoáng sản, thủy điện, cây trồng, chăn nuôi và kinh tế biển để phát kinh tế của vùng Trung du và miền núi Bắc Bộ', E'Bản đồ treo tường thể hiện nội dung:\n- Sự phân bố một số yếu tố là thế mạnh để phát triển kinh tế của vùng như:\n+ Khoáng sản (than, sắt, thiếc, apatit, đồng);\n+ Hệ thống sông ngòi và các nhà máy thủy điện (Hòa Bình, Sơn La, Lai châu);\n+ Cây trồng có nguồn gốc cận nhiệt đới và ôn đới (cây công nghiệp, rau quả), chăn nuôi gia súc lớn;\n+ Kinh tế biển (nuôi trồng và đánh bắt hải sản, cảng biển, du lịch biển - đảo).\n- Ranh giới với các nước láng giềng, các vùng giáp ranh; vùng biển, đảo.\n- Bản đồ phụ: Vị trí vùng Trung du và miền núi Bắc Bộ trên lãnh thổ Việt Nam.\n- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'12', E'Dùng cho lớp 12', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DL-031', E'DM-THPT-DL-031', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1840, E'21.1', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Chủ đề: Phát triển kinh tế - xã hội ở Đồng bằng sông Hồng', E'Bản đồ Đồng bằng sông Hồng', E'HS tìm hiểu một số thế mạnh để phát triển kinh tế của vùng Đồng bằng sông Hồng', E'Bản đồ treo tường thể hiện nội dung:\n- Sự phân bố một số yếu tố là thế mạnh để phát triển kinh tế của vùng như:\n+ Hệ thống sông ngòi, cây trồng và vật nuôi chính, các khu vực nuôi trồng và đánh bắt thủy, hải sản;\n+ Khoáng sản, các trung tâm công nghiệp, các ngành công nghiệp;\n+ Hệ thống giao thông vận tải, sân bay, cảng sông, cảng biển, các điểm du lịch (di sản thế giới, di tích lịch sử - văn hóa, danh lam thắng cảnh, bãi biển);\n- Ranh giới các vùng giáp ranh; vùng biển, đảo;\n- Bản đồ phụ: Vị trí vùng Đồng bằng sông Hồng trên lãnh thổ Việt Nam.\n- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'12', E'Dùng cho lớp 12', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DL-032', E'DM-THPT-DL-032', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1850, E'22.1', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Chủ đề: Phát triển nông nghiệp, lâm nghiệp và thủy sản ở Bắc Trung Bộ', E'Bản đồ Bắc Trung Bộ', E'HS tìm hiểu một số thế mạnh để phát triển nông nghiệp, lâm nghiệp và thủy sản của vùng Bắc Trung Bộ', E'Bản đồ treo tường thể hiện nội dung:\n- Sự phân bố một số yếu tố là thế mạnh để phát triển nông nghiệp, lâm nghiệp và thủy sản của vùng như:\n+ Các vùng nông nghiệp (vùng rừng, vùng nông lâm kết hợp, vùng cây công nghiệp lâu năm, vùng cây lương thực và chăn nuôi);\n+ Cây trồng và vật nuôi chính;\n+ Hệ thống sông ngòi và các khu vực nuôi trồng, đánh bắt thủy - hải sản;\n- Ranh giới với các nước lán giềng, các vùng giáp ranh; vùng biển, đảo;\n- Bản đồ phụ: Vị trí vùng Bắc Trung Bộ trên lãnh thổ Việt Nam;\n- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'12', E'Dùng cho lớp 12', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DL-033', E'DM-THPT-DL-033', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1860, E'23.1', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Chủ đề: Phát triển kinh tế biển ở Duyên hải Nam Trung Bộ', E'Bản đồ Duyên hải Nam Trung Bộ', E'HS tìm hiểu một số thế mạnh để phát triển kinh tế biển ở Duyên hải Nam Trung Bộ', E'Bản đồ treo tường thể hiện nội dung:\n- Sự phân bố một số yếu tố là thế mạnh để phát triển kinh tế biển của vùng như:\n+ Tài nguyên sinh vật biển (Các bãi cá, bãi tôm, khu vực nuôi trồng và đánh bắt hải sản);\n+ Hệ thống giao thông vận tải biển, các cảng biển (Đà Nẵng, Quy Nhơn, Nha Trang, Dung Quất);\n+ Các điểm du lịch biển;\n+ Tài nguyên khoáng sản (dầu mỏ, khí tự nhiên, cát trắng) và các vùng sản xuất muối;\n- Ranh giới với các nước láng giềng, các vùng giáp ranh; vùng biển, đảo;\n- Bản đồ phụ: Vị trí vùng Duyên hải Nam Trung Bộ trên lãnh thổ Việt Nam;\n- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'12', E'Dùng cho lớp 12', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DL-034', E'DM-THPT-DL-034', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1870, E'24.1', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Chủ đề: Khai thác thế mạnh để phát triển kinh tế Tây Nguyên', E'Bản đồ Tây Nguyên', E'HS tìm hiểu một số thế mạnh về cây công nghiệp lâu năm, thủy điện, khoáng sản, du lịch để phát triển kinh tế ở Tây Nguyên', E'Bản đồ treo tường thể hiện các nội dung:\n- Sự phân bố một số yếu tố là thế mạnh để phát triển kinh tế của vùng như:\n+ Cây công nghiệp lâu năm (cao su, cà phê, bông, điều, chè, hồ tiêu);\n+ Hệ thống sông ngòi (sông Sê San, sông Đồng Nai, sông Srêpok) và các nhà máy thủy điện (Yaly, Sê San, Plây Krông, Đak Ru);\n+ Tài nguyên khoáng sản bô xít;\n+ Các điểm du lịch (di sản thế giới, di tích lịch sử - văn hóa, vườn quốc gia, danh lam thắng cảnh);\n- Ranh giới vói các nước láng giềng, các vùng giáp ranh;\n- Bản đồ phụ: Vị trí vùng Tây Nguyên trên lãnh thổ Việt Nam;\n- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'12', E'Dùng cho lớp 12', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DL-035', E'DM-THPT-DL-035', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1880, E'25.1', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Chủ đề: Phát triển kinh tế - xã hội ở Đông Nam Bộ', E'Bản đồ Đông Nam Bộ', E'HS tìm hiểu một số thế mạnh để phát triển kinh tế ở Đông Nam Bộ', E'Bản đồ treo tường thể hiện nội dung:\n- Sự phân bố một số yếu tố là thế mạnh để phát triển kinh tế của vùng như:\n+ Các vùng nông nghiệp (vùng rừng, vùng nông lâm kết hợp, vùng cây công nghiệp lâu năm, vùng cây lương thực và chăn nuôi), cây trồng và vật nuôi chính;\n+ Hệ thống sông Đồng Nai, hồ Dầu Tiếng, các nhà máy thủy điện (Trị An, Thác Mơ, Cần Đơn), khu vực nuôi trồng thủy hải sản nước lợ;\n+ Tài nguyên khoáng sản (dầu khí trên vùng thềm lục địa, đất sét, cao lanh), một số trung tâm công nghiệp, cơ cấu các ngành công nghiệp;\n+ Các điểm du lịch;\n- Ranh giới với nước láng giềng, các vùng giáp ranh; vùng biển, đảo;\n- Bản đồ phụ: Vị trí vùng Đông Nam Bộ trên lãnh thổ Việt Nam;\n- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'12', E'Dùng cho lớp 12', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DL-036', E'DM-THPT-DL-036', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1890, E'26.1', E'Thiết bị theo các chủ đề › Bản đồ/lược đồ', E'Chủ đề: Sử dụng hợp lí tự nhiên để phát triển kinh tế ở Đồng bằng sông Cửu Long', E'Bản đồ Đồng bằng sông Cửu Long', E'HS tìm hiểu một số thế mạnh về tự nhiên để phát triển kinh tế ở Đồng bằng sông Cửu Long', E'Bản đồ treo tường thể hiện nội dung:\n- Sự phân bố một số yếu tố là thế mạnh về tự nhiên để phát triển kinh tế của vùng như:\n+ Các nhóm đất (đất phù sa ngọt, đất phèn, đất mặn và đất khác);\n+ Cây trồng (cây lương thực, cây ăn quả), vật nuôi (gia cầm);\n+ Mạng lưới sông ngòi (sông Tiền, sông Hậu), kênh rạch, cửa sông (cửa Tiểu, Đại, Hàm Luông, Cổ Chiên), khu vực nuôi trồng và đánh bắt thủy, hải sản;\n+ Tài nguyên sinh vật (chim, bãi cá, bãi tôm, rừng ngập mặn, rừng tràm;\n+ Tài nguyên khoáng sản: đá vôi (Hà Tiên, Kiên Lương), than bùn (U Minh, Tứ giác Long Xuyên), dầu khí (thềm lục địa);\n+ Các điểm du lịch (khu dự trữ sinh quyển, vườn quốc gia, bãi tắm, du lịch sông nước, miệt vườn);\n- Ranh giới với nước láng giềng, vùng giáp ranh; vùng biển, đảo;\n- Bản đồ phụ: Vị trí vùng Đồng bằng sông Cửu Long trên lãnh thổ Việt Nam;\n- Kích thước (1090x790)mm.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'12', E'Dùng cho lớp 12', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DL-037', E'DM-THPT-DL-037', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1900, E'1.1', E'Thiết bị theo các chủ đề › Video/clip', E'Chủ đề: Trái Đất', E'Video/clip về Trái Đất', E'HS tìm hiểu về nguồn gốc hình thành Trái Đất; các chuyển động chính của Trái Đất và một số quy luật của vỏ địa lí', E'Video/clip mô phỏng các nội dung sau:\n- Nguồn gốc hình thành Trái Đất, đặc điểm của vỏ Trái Đất và cấu tạo vỏ Trái Đất;\n- Các chuyển động chính của Trái Đất: chuyển động tự quay (luân phiên ngày đêm, giờ trên Trái Đất); chuyển động quanh Mặt Trời (các mùa trong năm, ngày đêm dài ngắn theo vĩ độ);\n- Biểu hiện của quy luật thống nhất và hoàn chỉnh của vỏ địa lí; quy luật địa đới và phi địa đới.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10 (Sử dụng chung với chủ đề: Một số quy luật của vỏ địa lí)', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-DL-038', E'DM-THPT-DL-038', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1910, E'2.1', E'Thiết bị theo các chủ đề › Video/clip', E'Chủ đề: Biến đổi khí hậu', E'Video/clip về biến đổi khí hậu trên thế giới', E'HS tìm hiểu về các biểu hiện, nguyên nhân, hậu quả và giải pháp ứng phó với biến đổi khí hậu trên thế giới', E'Video/clip thể hiện các nội dung:\n- Các biểu hiện của biến đổi khí hậu (nhiệt độ Trái Đất ấm lên, băng tan, nước biển dâng, gia tăng thiên tai);\n- Nguyên nhân và hậu quả trên phạm vi toàn cầu;\n- Một số giải pháp ứng phó với biến đổi khí hậu.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-DL-039', E'DM-THPT-DL-039', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1920, E'3.1', E'Thiết bị theo các chủ đề › Video/clip', E'Chủ đề: Một số vấn đề về du lịch thế giới', E'Video/clip về du lịch thế giới và Việt Nam', E'HS tìm hiểu một số loại hình du lịch phổ biến hiện nay và một số điểm du lịch nổi tiếng trên thế giới', E'Video/clip thể hiện các nội dung:\n- Một số loại hình du lịch phổ biến hiện nay trên thế giới (có liên hệ với Việt Nam);\n- Một số điểm lịch nổi tiếng trên thế giới.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'11', E'Dùng cho lớp 11', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-DL-040', E'DM-THPT-DL-040', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1930, E'4.1', E'Thiết bị theo các chủ đề › Video/clip', E'Chủ đề: Vấn đề sử dụng hợp lí tài nguyên thiên nhiên và bảo vệ môi trường', E'Video/clip về bảo vệ môi trường', E'HS tìm hiểu tác động tiêu cực của con người tới môi trường và hoạt động bảo vệ môi trường của học sinh', E'Video/clip thể hiện các nội dung:\n- Tác động tiêu cực của con người gây ảnh hưởng tới môi trường (sự nóng lên toàn cầu, ô nhiễm môi trường, suy giảm tài nguyên, mất cân bằng sinh thái);\n- Hoạt động của học sinh tham gia bảo vệ môi trường ở nhà trường và địa phương (vệ sinh trường lớp, ngõ xóm; trồng cây xanh; thu gom và phân loại rác; tái chế rác thải; tuyên truyền về môi trường).', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'12', E'Dùng cho lớp 12', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-DL-041', E'DM-THPT-DL-041', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1940, E'5.1', E'Thiết bị theo các chủ đề › Video/clip', E'Chủ đề: Phát triển kinh tế và đảm bảo quốc phòng an ninh ở biển Đông và các đảo, quần đảo', E'Video/clip về khai thác tổng hợp tài nguyên biển - đảo Việt Nam', E'HS tìm hiểu về khai thác tổng hợp tài nguyên biển - đảo ở nước ta', E'Video/clip thể hiện các nội dung:\n- Các bộ phận của vùng biển Việt Nam, các đảo và quần đảo, trong đó có quần đảo Hoàng Sa và Trường Sa;\n- Các hoạt động khai thác sinh vật, khai thác khoáng sản, giao thông vận tải và du lịch biển – đảo.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'12', E'Dùng cho lớp 12', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-DL-042', E'DM-THPT-DL-042', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1950, E'6.1', E'Thiết bị theo các chủ đề › Video/clip', E'Chủ đề: Thiên tai và biện pháp phòng chống', E'Video/clip về thiên tai và biện pháp phòng chống', E'HS tìm hiểu về thiên tai và biện pháp phòng chống thiên tai', E'Video/clip thể hiện các nội dung:\n- Một số thiên tai và nơi thường xảy ra (bão, hạn hán, lũ quét, lũ ống, xâm nhập mặn, triều cường, sạt lở đất);\n- Nguyên nhân, hậu quả của một số thiên tai và các biện pháp phòng chống.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'12', E'Dùng cho lớp 12', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-DL-043', E'DM-THPT-DL-043', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'DIA_LY', 1960, E'1', E'Học liệu điện tử', NULL, E'Bộ học liệu điện tử hỗ trợ giáo viên', E'GV xây dựng kế hoạch bài dạy (giáo án) điện tử, chuẩn bị bài giảng điện tử, chuẩn bị các học liệu điện tử, chuẩn bị các bài tập, bài kiểm tra, đánh giá điện tử phù hợp với Chương trình', E'Bộ học liệu điện tử được xây dựng theo Chương trình môn Địa lí cấp THPT (CTGDPT 2018), có hệ thống học liệu điện tử (hình ảnh, bản đồ, sơ đồ, video/clip, các câu hỏi, đề kiểm tra…) đi kèm và được tổ chức, quản lí thành hệ thống thư viện điện tử, thuận lợi cho tra cứu và sử dụng. Bộ học liệu sử dụng được trên máy tính trong môi trường không kết nối internet. Phải đảm bảo tối thiểu các chức năng:\n- Chức năng hỗ trợ soạn giáo án điện tử;\n- Chức năng hướng dẫn chuẩn bị bài giảng điện tử;\n- Chức năng hướng dẫn chuẩn bị và sử dụng học liệu điện tử (hình ảnh, bản đồ, sơ đồ, video/clip…);\n- Chức năng hướng dẫn và chuẩn bị các bài tập;\n- Chức năng hỗ trợ chuẩn bị công tác kiểm tra, đánh giá.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10,11,12', E'Dùng cho lớp 10, 11, 12', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-DL-044', E'DM-THPT-DL-044', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'GDKT_PL', 1970, E'1.1', NULL, E'Nền kinh tế và các chủ thể của nền kinh tế', E'Tranh thể hiện sơ đồ mô phỏng về các chủ thể tham gia trong nền kinh tế và vai trò của các chủ thể tham gia trong nền kinh tế', E'- HS kể được tên các chủ thể tham gia trong nền kinh tế;\n- Nhận biết được vai trò của các chủ thể tham gia trong nền kinh tế.', E'Tranh gồm 2 tờ, nội dung phản ảnh sơ đồ:\n- Các chủ thể kinh tế cơ bản tham gia trong nền kinh tế:\n+ Người sản xuất (gồm các nhà sản xuất, đầu tư, kinh doanh hàng hóa, dịch vụ);\n+ Người tiêu dùng (những người mua hàng hóa, dịch vụ trên thị trường đề thỏa mãn nhu cầu tiêu dùng);\n+ Các chủ thể trung gian trong thị trường (những cá nhân, tổ chức đảm nhiệm vai trò cầu nối giữa các chủ thể sản xuất, tiêu dùng hàng hóa, dịch vụ trên thị trường);\n+ Nhà nước.\n- Vai trò của các chủ thể tham gia thị trường (trong đó Nhà nước đặt ở vị trí trung tâm):\n+ Người sản xuất (người trực tiếp tạo ra của cái vật chất, sản phẩm cho xã hội để phục vụ tiêu dùng);\n+ Người tiêu dùng (là động lực quan trọng của sự phát triển sản xuất, ảnh hưởng trực tiếp tới sản xuất);\n+ Các chủ thể trung gian trong thị trường (kết nối, thông tin trong các quan hệ mua, bán);\n+ Nhà nước (vai trò quản lý nhà nước về kinh tế đồng thời thực hiện những biện pháp để khắc phục những khuyết tật của thị trường).', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-KTPL-001', E'DM-THPT-KTPL-001', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'GDKT_PL', 1980, E'1.2', NULL, E'Thị trường và cơ chế thị trường', E'Tranh thể hiện sơ đồ các loại hình thị trường cơ bản', E'Liệt kê được các loại thị trường', E'Tranh gồm 1 tờ, nội dung phản ánh sơ đồ các loại hình thị trường cơ bản gồm:\n- Căn cứ theo đối tượng trao đổi, mua bán cụ thể, có: thị trường hàng hóa, thị trường dịch vụ;\n- Căn cứ vào phạm vi các quan hệ, có : thị trường trong nước, thị trường thế giới;\n- Căn cứ vào vai trò của các yếu tố được trao đổi, mua bán, có: thị trường tư liệu tiêu dùng; thị trường tư liệu sản xuất;\n- Căn cứ vào tính chất và cơ chế vận hành có: thị trường tự do; thị trường có điều tiết; thị trường cạnh tranh hoàn hảo, thị trường cạnh tranh không hoàn hảo (độc quyền).', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-KTPL-002', E'DM-THPT-KTPL-002', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'GDKT_PL', 1990, E'1.3', NULL, E'Hội nhập kinh tế quốc tế', E'Tranh về hoạt động kí kết hợp tác kinh tế quốc tế giữa chính phủ Việt Nam với một số tổ chức quốc tế và khu vực', E'HS biết được một số hoạt động kí kết hợp tác kinh tế quốc tế giữa chính phủ Việt Nam với một số tổ chức quốc tế và khu vực', E'Tranh gồm 3 tờ, nội dung có tính giáo dục và tác động lan toả, minh họa hình ảnh cụ thể sau:\n+ Hình ảnh Việt Nam tham gia WTO;\n+ Hình ảnh Việt Nam tham gia AFTA;\n+ Hình ảnh Việt Nam tham gia CPTTP.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'12', E'Dùng cho lớp 12', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-KTPL-003', E'DM-THPT-KTPL-003', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'GDKT_PL', 2000, E'2.1', NULL, E'Ngân sách Nhà nước và Thuế', E'Tranh thể hiện sơ đồ mô phỏng một số loại thuế phổ biến', E'Nhận biết và gọi tên được một số loại thuế phổ biến', E'Tranh gồm 1 tờ, có hình rõ nét, đẹp, màu sắc rõ minh hoạ sơ đồ một số loại thuế phổ biến:\n- Thuế trực thu: Thuế thu nhập doanh nghiệp; Thuế thu nhập cá nhân; Thuế sử dụng đất;\n- Thuế gián thu: Thuế giá trị gia tăng; Thuế tiêu thụ đặc biệt; Thuế xuất nhập khẩu; Thuế tài nguyên; Thuế môn bài.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-KTPL-004', E'DM-THPT-KTPL-004', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)');
INSERT INTO dm03_rows VALUES
(E'THPT', E'GDKT_PL', 2010, E'2.2', NULL, E'Bảo hiểm và An sinh xã hội', E'Tranh thể hiện một số loại hình bảo hiểm và chính sách an sinh xã hội cơ bản', E'- Liệt kê được một số loại hình bảo hiểm;\n- Gọi tên được một số chính sách an sinh xã hội cơ bản.', E'Tranh gồm 2 tờ, nội dung thể hiện qua sơ đồ:\n- Một số loại hình bảo hiểm cơ bản gồm:\n+ Các loại hình bảo hiểm bắt buộc: Bảo hiểm xã hội; Bảo hiểm tai nạn lao động, Bệnh nghề nghiệp; Bảo hiểm y tế; Bảo hiểm thất nghiệp;\n+ Các loại hình bảo hiểm thương mại: Bảo hiểm phi nhân thọ; Bảo hiểm sức khoẻ; Bảo hiểm nhân thọ.\n- Một số chính sách An sinh xã hội cơ bản gồm 4 nhóm chính sách sau:\n+ Chính sách việc làm, đảm bảo thu nhập tối thiểu và giảm nghèo (tạo việc làm; tín dụng ưu đãi; hỗ trợ học nghề; hỗ trợ tìm việc làm; giảm nghèo);\n+ Bảo hiểm xã hội (Bảo hiểm xã hội bắt buộc; Bảo hiểm thất nghiệp; Bảo hiểm tự nguyện; Bảo hiểm y tế);\n+ Trợ giúp xã hội cho các nhóm đặc thù (Trợ giúp xã hội thường xuyên; trợ giúp xã hội đột xuất; chăm sóc nuôi dưỡng tại cộng đồng; chăm sóc tại cơ sở thương binh xã hội);\n+ Dịch vụ xã hội cơ bản (giáo dục; y tế; nhà ở; nước sạch; thông tin).', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'12', E'Dùng cho lớp 12', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-KTPL-005', E'DM-THPT-KTPL-005', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'GDKT_PL', 2020, E'3.1', NULL, E'Tín dụng và cách sử dụng các dịch vụ tín dụng', E'Tranh thể hiện sơ đồ một số dịch vụ tín dụng cơ bản', E'HS kể tên được một số dịch vụ tín dụng và mô tả đặc điểm của chúng', E'Tranh gồm 1 tờ, có hình rõ nét, đẹp, màu sắc sinh động, thể hiện sơ đồ một số dịch vụ tín dụng cơ bản trong nền kinh tế và đặc điểm của chúng:\n- Tín dụng ngân hàng\n+ Là mối quan hệ vay mượn giữa ngân hàng và các cá nhân hay doanh nghiệp dưới dạng hợp đồng tín dụng;\n+ Chủ thể là Ngân hàng (trung gian giữa người cần vốn và người có vốn), các cá nhân hoặc doanh nghiệp).\n- Tín dụng thương mại\n+ Là mối quan hệ vay mượn hàng hóa giữa những người kinh doanh sản xuất với nhau;\n+ Chủ thể là các doanh nghiệp với nhau và thường không có người trung gian).', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-KTPL-006', E'DM-THPT-KTPL-006', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'GDKT_PL', 2030, E'3.2', NULL, E'Ý tưởng, cơ hội kinh doanh và các năng lực cần thiết của người kinh doanh', E'Tranh thể hiện sơ đồ các nguồn giúp tạo ý tưởng kinh doanh', E'Chỉ ra được các nguồn giúp tạo ý tưởng kinh doanh', E'Tranh gồm 1 tờ, có hình rõ nét, đẹp, màu sắc sinh động, minh hoạ bằng sơ đồ các nội dung sau: Các nguồn giúp tạo ý tưởng kinh doanh\n+ Lợi thế nội tại (đam mê; hiểu biết; khả năng huy động các nguồn lực);\n+ Cơ hội bên ngoài (nhu cầu; nguồn cung ứng; sự cạnh tranh; vị trí triển khai; chính sách vĩ mô).', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'11', E'Dùng cho lớp 11', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-KTPL-007', E'DM-THPT-KTPL-007', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'GDKT_PL', 2040, E'3.3', NULL, E'Lạm phát, thất nghiệp', E'Tranh thể hiện sơ đồ các loại hình lạm phát và thất nghiệp', E'Liệt kê được các loại hình lạm phát và thất nghiệp', E'Tranh gồm 2 tờ, có hình rõ nét, đẹp, màu sắc sinh động, minh hoạ bằng sơ đồ các nội dung sau:\n- Các loại hình lạm phát:\n+ Lạm phát tự nhiên: (0-10%);\n+ Lạm phát phi mã: 10- <1000%;\n+ Siêu lạm phát : >1000%.\n- Các loại hình thất nghiệp\n+ Theo đặc trưng của người thất nghiệp: Thất nghiệp chia theo giới tính; thất nghiệp theo lứa tuổi; thất nghiệp chia theo vùng, lãnh thổ; thất nghiệp chia theo ngành nghề;\n+ Theo lí do thất nghiệp: thất nghiệp tự nguyện; thất nghiệp không tự nguyện; thất nghiệp trá hình;\n+ Theo nguồn gốc thất nghiệp: thất nghiệp tạm thời; thất nghiệp có tính cơ cấu; thất nghiệp do thiếu cầu; thất nghiệp do yếu tố ngoài thị trường.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'11', E'Dùng cho lớp 11', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-KTPL-008', E'DM-THPT-KTPL-008', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'GDKT_PL', 2050, E'3.4', NULL, E'Đạo đức kinh doanh', E'Tranh thể hiện sơ đồ: - Vai trò của đạo đức kinh doanh. - Các biểu hiện của đạo đức kinh doanh.', E'- HS hiểu được vai trò của đạo đức kinh doanh;\n- Chỉ ra được các biểu hiện của đạo đức kinh doanh.', E'Tranh gồm 1 tờ, có hình rõ nét, đẹp, màu sắc sinh động, thể hiện bằng sơ đồ nội dung sau:\n- Vai trò của đạo đức kinh doanh: Điều chỉnh hành vi của các chủ thể kinh doanh; chất lượng của doanh nghiệp; làm hài lòng khách hàng; sự vững mạnh của nền kinh tế quốc gia;\n- Các biểu hiện của đạo đức kinh doanh: Trách nhiệm; trung thực; nguyên tắc; tôn trọng con người; Gắn kết các lợi ích.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'11', E'Dùng cho lớp 11', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-KTPL-009', E'DM-THPT-KTPL-009', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'GDKT_PL', 2060, E'3.5', NULL, E'Trách nhiệm xã hội của doanh nghiệp', E'Tranh thể hiện sơ đồ các hình thức thực hiện trách nhiệm xã hội của doanh nghiệp', E'- HS liệt kê được các hình thức thực hiện trách nhiệm xã hội của doanh nghiệp;\n- Xác định được trách nhiệm của công dân khi tham gia điều hành doanh nghiệp.', E'Tranh gồm 1 tờ, có hình rõ nét, đẹp, màu sắc sinh động, thể hiện bằng sơ đồ nội dung sau:\n- Các hình thức thực hiện trách nhiệm xã hội của doanh nghiệp:\n+ Trách nhiệm từ thiện (đóng góp các nguồn lực cho cộng đồng; cải thiện chất lượng cuộc sống);\n+ Trách nhiệm đạo đức (làm điều đúng, chính đáng và công bằng; tránh gây hại cho con người và xã hội);\n+ Trách nhiệm pháp lí (tuân thủ pháp luật);\n+ Trách nhiệm kinh tế (đạt lợi nhuận; chất lượng, an toàn thực phẩm).', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'12', E'Dùng cho lớp 12', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-KTPL-010', E'DM-THPT-KTPL-010', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'GDKT_PL', 2070, E'4.1', NULL, E'Lập kế hoạch tài chính cá nhân', E'Tranh thể hiện sơ đồ các bước lập kế hoạch tài chính cá nhân', E'HS nhận thức được các bước lập kế hoạch tài chính cá nhân', E'Tranh gồm 1 tờ có hình rõ nét, đẹp, màu sắc sinh động, thể hiện cụ thể bằng sơ đồ tuần tự các bước lập kế hoạch tài chính cá nhân (theo chiều có mũi tên đi xuống):\n(1) Thiết lập mục tiêu cá nhân;\n(2) Kiểm tra lại tình hình tài chính;\n(3) Xác định thói quen chi tiêu;\n(4) Dự tính các nguồn thu nhập;\n(5) Xác định thời gian hoàn thành;\n(6) Lên chiến lược thực hiện mục tiêu;\n(7) Cam kết và thực hiện mục tiêu.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-KTPL-011', E'DM-THPT-KTPL-011', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'GDKT_PL', 2080, E'5.1', NULL, E'Hệ thống chính trị nước CHXHCN Việt Nam', E'- Tranh thể hiện sơ đồ hệ thống chính trị Việt Nam. - Sơ đồ tổ chức bộ máy nhà nước ở Việt Nam.', E'HS nhận biết đặc điểm, cấu trúc, của bộ máy Nhà nước CHXHCN Việt Nam', E'Tranh gồm 1 tờ, nội dung tranh phản ánh rõ:\n- Sơ đồ hệ thống chính trị ở Việt Nam;\n- Sơ đồ tổ chức bộ máy nhà nước ở Việt Nam theo Hiến pháp 2013.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10', E'THIET_BI_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'THPT-KTPL-012', E'DM-THPT-KTPL-012', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'GDKT_PL', 2090, NULL, NULL, E'Hệ thống chính trị và pháp luật', E'Video/clip về nguyên tắc tổ chức và hoạt động của bộ máy Nhà nước CHXHCN Việt Nam theo Hiến pháp mới', E'HS hiểu được nguyên tắc hoạt động của bộ máy CHXHCN Việt Nam', E'Video/clip hình ảnh thực tế, minh họa nguyên tắc hoạt động của bộ máy Nhà nước CHXHCN Việt Nam.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-KTPL-013', E'DM-THPT-KTPL-013', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'GDKT_PL', 2100, E'5.2', NULL, E'Pháp luật nước CHXHCN Việt Nam', E'Tranh mô phỏng hệ thống pháp luật và văn bản pháp luật Việt Nam theo luật mới', E'HS nhận diện được hệ thống pháp luật và văn bản pháp luật Việt Nam', E'Nội dung tranh phản ánh rõ hệ thống pháp luật và văn bản pháp luật Việt Nam theo luật mới từ 01/01/2021.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10', E'Dùng cho lớp 10', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-KTPL-014', E'DM-THPT-KTPL-014', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'VAT_LY', 2110, E'1', E'Thiết bị dùng chung', NULL, E'Biến áp nguồn', E'Cấp nguồn cho các thí nghiệm', E'Điện áp vào 220V- 50Hz\nĐiện áp ra:\n- Điện áp xoay chiều (5A): (3, 6, 9, 12, 15, 24) V.\n- Điện áp một chiều (3A): điều chỉnh từ 0 đến 24V.\nCó đồng hồ chỉ thị điện áp ra; có mạch tự động đóng ngắt và bảo vệ quá dòng, đảm bảo an toàn về độ cách điện và độ bền điện trong quá sử dụng.', TRUE, TRUE, FALSE, E'CAI', E'Cái', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-VL-001', E'DM-THPT-VL-001', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'VAT_LY', 2120, E'2', E'Thiết bị dùng chung', NULL, E'Bộ thu nhận số liệu', E'Sử dụng cho các cảm biến trong danh mục', E'Có các cổng kết nối với các cảm biến và các cổng USB, SD để xuất dữ liệu; tích hợp màn hình màu, cảm ứng để trực tiếp hiển thị kết quả từ các cảm biến, các công cụ để phân tích dữ liệu, phần mềm tự động nhận dạng và hiển thị tên, loại cảm biến; có thể kết nối với máy tính lưu trữ, phân tích và trình chiếu dữ liệu; có thể sử dụng nguồn điện hoặc pin, pin phải có thời lượng đủ để thực hiện các bài thí nghiệm.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'02', 2, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-VL-002', E'DM-THPT-VL-002', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'VAT_LY', 2130, E'3', E'Thiết bị dùng chung', NULL, E'Bộ thiết bị đo kĩ thuật số tích hợp', E'Xác định khoảng cách, đo vận tốc, gia tốc, lực', E'Xe lăn có tích hợp thiết bị đo khoảng cách; đo lực với dải đo ± 100N, độ phân giải 0,1N, độ chính xác ± 1%; xác định vị trí với độ phân giải ± 0,2mm; đo vận tốc với dải đo ± 3m/s; đo gia tốc với dải đo ± 16g (g ≈ 9,8 m/s2).\n02 gia trọng khối lượng mỗi quả 250g.\n01 phần mềm tiếng Việt, kết nối không dây với điện thoại và/hoặc máy tính.\n01 máng đỡ dài ≥ 1000mm, độ chia nhỏ nhất 1mm, rộng ≥ 100mm, có rãnh dẫn hướng bánh xe của xe lăn, có các vít để chỉnh thăng bằng, có chặn ở 2 đầu máng, có thể lắp với giá thí nghiệm để thay đổi độ nghiêng.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-VL-003', E'DM-THPT-VL-003', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'VAT_LY', 2140, E'4', E'Thiết bị dùng chung', NULL, E'Bộ thiết bị dạy học điện tử, mô phỏng môn Vật lí', E'Giúp giáo viên xây dựng kế hoạch dạy học (giáo án) điện tử, chuẩn bị bài dạy, các học liệu điện tử, chuẩn bị các bài tập, bài kiểm tra, đánh giá điện tử phù hợp với Chương trình.', E'Đáp ứng yêu cầu của Chương trình môn Vật lý cấp THPT (CTGDPT 2018), có hệ thống học liệu điện tử (mô phỏng 3D, hình ảnh, sơ đồ, âm thanh, video, các câu hỏi, đề kiểm tra) đi kèm và được tổ chức, quản lý thành hệ thống thư viện điện tử, thuận lợi cho tra cứu và sử dụng. Bộ học liệu sử dụng được trên PC trong môi trường không kết nối internet. Phải đảm bảo tối thiểu các nhóm chức năng:\n- Nhóm chức năng hỗ trợ giảng dạy: soạn giáo án điện tử; hướng dẫn chuẩn bị bài giảng điện tử; học liệu điện tử (hình ảnh, sơ đồ, âm thanh, video); chỉnh sửa học liệu (cắt video);\n- Nhóm chức năng mô phỏng và tương tác 3D:\nĐiều hướng thay đổi trực tiếp góc nhìn (xoay 360 độ, phóng to, thu nhỏ); quan sát và hiển thị thông tin cụ thể của các lớp khác nhau trong một mô hình, lựa chọn tách lớp một phần nội dung bất kỳ; tích hợp mô hình 3D vào bài giảng. Đảm bảo tối thiểu các mô hình: Hệ Mặt trời, các hiện tượng thiên văn quan sát được từ Trái Đất, cấu tạo của tụ điện, trường hấp dẫn, mạch điện đơn giản có sử dụng thiết bị đầu ra, cấu trúc hạt nhân, quá trình chụp X quang.\n- Nhóm chức năng hỗ trợ công tác kiểm tra đánh giá: hướng dẫn, chuẩn bị các bài tập; đề kiểm tra.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-VL-004', E'DM-THPT-VL-004', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'VAT_LY', 2150, E'5', E'Thiết bị dùng chung', NULL, E'Dây nối', E'Nối các linh kiện điện', E'Bộ gồm 20 dây nối, tiết diện 0,75mm2, có phích cắm đàn hồi tương thích với đầu nối mạch điện, dài tối thiểu 500mm.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-VL-005', E'DM-THPT-VL-005', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'VAT_LY', 2160, E'6', E'Thiết bị dùng chung', NULL, E'Đồng hồ đo điện đa năng', E'Đo các đại lượng điện', E'Hiển thị đến 4 chữ số. Giới hạn đo:\n- Dòng điện một chiều: 10 A, các thang đo μA, mA và A;\n- Dòng điện xoay chiều: 10A, các thang đo μA, mA và A;\n- Điện áp một chiều: 600V, các thang đo mV và V;\n- Điện áp xoay chiều: 600V, các thang đo mV và V.', TRUE, TRUE, FALSE, E'CAI', E'Cái', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-VL-006', E'DM-THPT-VL-006', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'VAT_LY', 2170, E'7', E'Thiết bị dùng chung', NULL, E'Giá thí nghiệm', E'Lắp thiết bị', E'- 01 đế 3 chân hình sao bằng kim loại, khoảng 2,5 kg, bền, chắc, ổn định, có lỗ Ф10mm và vít M6 thẳng góc với lỗ để giữ trục Ф10mm, có các vít chỉnh thăng bằng, sơn màu tối.\n- 01 trụ inox đặc Ф10mm, dài 495mm, một đầu ren M6 x12mm, có tai hồng M6.\n- 02 trụ inox đặc Ф8mm dài 150mm, vê tròn mặt cắt\n- 04 khớp đa năng, hai miệng khoá thẳng góc với nhau, siết bằng hai vít M6 có tay vặn.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-VL-007', E'DM-THPT-VL-007', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
