(E'THPT', E'VAT_LY', 2270, E'1', E'Dụng cụ', E'Động học', E'Thiết bị đo độ dịch chuyển, tốc độ, vận tốc', E'Lấy số liệu vẽ đồ thị và tính gia tốc', E'Bộ thiết bị đo kĩ thuật số tích hợp (TBDC) được bố trí thích hợp để lấy số liệu vẽ đồ thị vẽ đồ thị vận tốc – thời gian, độ dịch chuyển – thời gian, tính gia tốc', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-VL-017', E'DM-THPT-VL-017', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'VAT_LY', 2280, E'2', E'Dụng cụ', E'Động học', E'Thiết bị đo vận tốc và gia tốc của vật rơi tự do', E'Đo gia tốc rơi tự do.', E'Bộ thiết bị gồm:\n- Giá đỡ bằng nhôm thẳng đứng, dài 1000 mm, có dây dọi, được gắn trên đế ba chân có vít điều chỉnh thăng bằng, phía trên có nam châm điện để giữ vật rơi;\n- Đồng hồ đo thời gian hiện số, có hai thang đo 9,999s và 99,99s, độ chia nhỏ nhất 0,001s, sử dụng kiểu hoạt động từ A đến B và 2 ổ cắm 5 chân A, B;\n- Công tắc với nút nhấn kép lắp trong hộp bảo vệ, một đầu có ổ cắm, đầu kia ra dây tín hiệu dài 1000 mm có phích cắm 5 chân;\n- Cổng quang điện hoặc sử dụng Thiết bị thu nhận số liệu (TBDC), cảm biến khoảng cách với thang đo từ 0,15m tới 1,6m, độ phân giải 1mm;\n- Giá thí nghiệm (TBDC);\n- Thước nhựa (có vạch đen), miếng đỡ mềm;\n- Vật rơi hình trụ kim loại, đường kính 10mm, dài 20mm.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-VL-018', E'DM-THPT-VL-018', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'VAT_LY', 2290, E'3', E'Dụng cụ', E'Động lực học', E'Thiết bị đo gia tốc', E'Xây dựng định luật 2 Newton', E'Bộ thiết bị đo kĩ thuật số tích hợp (TBDC) được bố trí thích hợp để lấy số liệu vẽ đồ thị hoặc dùng Thiết bị thu nhận số liệu (TBDC), cảm biến khoảng cách với Thang do từ 0,15m tới 1,6m độ phân giải 1mm;', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-VL-019', E'DM-THPT-VL-019', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'VAT_LY', 2300, E'4', E'Dụng cụ', E'Động lực học', E'Thiết bị tổng hợp hai lực đồng quy và song song', E'Tổng hợp hai lực đồng quy và song song', E'Bộ thiết bị gồm:\n- Bảng thép cứng và phẳng có độ dày > 0,5mm, kích thước (400x550)mm, sơn tĩnh điện màu trắng, nẹp viền xung quanh; hai vít M4x40mm lắp vòng đệm Ф12mm để treo lò xo; mặt sau có lắp 2 ke nhôm kích thước (20x30x30)mm để lắp vào đế 3 chân;\n- Thước đo góc: Ф180mm, độ chia nhỏ nhất 10;\n- Lực kế có đế nam châm loại 5 N;\n- Lò xo (TBDC);\n- Thanh treo: Bằng kim loại nhẹ, cứng, có 3 con trượt có móc treo để treo các quả kim loại, hai đầu có hai lỗ để móc treo hai lò xo;\n- Thanh định vị bằng kim loại nhẹ, mỏng, thẳng, sơn màu đen, gắn được lên bảng từ tính. Cuộn dây nhẹ mềm, không dãn, bền, màu tối.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-VL-020', E'DM-THPT-VL-020', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
