(E'THPT', E'VAT_LY', 2330, E'7', E'Dụng cụ', E'Biến dạng của vật rắn', E'Thiết bị chứng minh định luật Hooke', E'Tìm mối liên hệ giữa lực đàn hồi và độ biến dạng của lò xo', E'Bộ thiết bị gồm:\n- Trụ đỡ có kẹp, thước;\n- Quả kim loại, lò xo (TBDC);\n- Bộ thiết bị đo kĩ thuật số tích hợp hoặc sử dụng bộ thu nhận số liệu kèm Cảm biến lực có thang đo: ±50 N, độ phân giải tối thiểu: ±0.1 N.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-VL-023', E'DM-THPT-VL-023', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'VAT_LY', 2340, E'8', E'Dụng cụ', E'Dao động', E'Con lắc lò xo, con lắc đơn.', E'Tạo ra dao động và dao động tự do', E'Bộ thiết bị gồm:\n- Dây không giãn, quả cầu kim loại;\n- Giá đỡ và lò xo (TBDC);\n- Cảm biến khoảng cách có thang đo từ 0,15m đến 4m với độ phân giải ± 1mm. Hoặc sử dụng Thiết bị đo khoảng cách và tốc độ với giới hạn đo 800mm, độ phân giải 1mm, có màn hình hiển thị.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-VL-024', E'DM-THPT-VL-024', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
