(E'THPT', E'VAT_LY', 2360, E'10', E'Dụng cụ', E'Sóng', E'Thiết bị giao thoa sóng nước', E'Chứng minh sự giao thoa hai sóng kết hợp', E'Bộ thí nghiệm gồm:\n- Giá thí nghiệm loại khung hình hộp, kích thước (300x420x320)mm, có màn quan sát;\n- Bộ rung loại mô tơ 1 chiều có cam lệch tâm, sử dụng điện áp 12V, có bộ phận điều chỉnh tốc độ;\n- Cần tạo sóng loại tạo 2 sóng tròn;\n- Gương phẳng loại thủy tinh, đặt nghiêng 45° trong giá thí nghiệm;\n- 3 thanh chắn sóng: loại không có khe; loại có 1 khe; loại có 2 khe;\n- Đèn12V - 50W hoặc đèn led 3W có giá đỡ.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-VL-026', E'DM-THPT-VL-026', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'VAT_LY', 2370, E'11', E'Dụng cụ', E'Sóng', E'Thiết bị tạo sóng dừng', E'Tạo sóng dừng', E'Bộ thí nghiệm gồm:\n- Máy phát âm tần và giá thí nghiệm (TBDC);\n- Lò xo bằng dây thép, mạ niken, đàn hồi tốt, dài 300mm; - Dây đàn hồi mảnh, dài 1000mm;\n- Lực kế 5 N, độ chia nhỏ nhất 0,1N;\n- Ròng rọc có đường kính tối thiểu 20mm;\n- Bộ rung kiểu điện động.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-VL-027', E'DM-THPT-VL-027', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'VAT_LY', 2380, E'12', E'Dụng cụ', E'Sóng', E'Thiết bị đo tốc độ truyền âm', E'Đo tốc độ truyền âm', E'Bộ thí nghiệm gồm:\n- Máy phát âm tần (TBDC);\n- Bộ thu nhận số liệu (TBDC);\n- Cảm biến âm thanh với tần số 20~20000 Hz (TBDC);\n- Loa mini (TBDC);\n- Ống dẫn âm nhựa trong, đường kính 40mm, dài 1000mm, pit-tông di chuyển dễ dàng trong ống, 2 giá đỡ ống dẫn âm;\n- Thước mét.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-VL-028', E'DM-THPT-VL-028', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'VAT_LY', 2390, E'13', E'Dụng cụ', E'Trường điện (Điện trường)', E'Thiết bị thí nghiệm điện tích', E'Mô tả sự hút (đẩy) của điện tích lên nhau', E'Bộ thí nghiệm gồm:\n- Máy Uyn-xớt có khoảng cách phóng điện tối thiểu giữa hai điện cực 30mm, có hộp bảo quản bằng vật liệu trong suốt và bộ phận sấy;\n- Điện kế tĩnh điện có đường kính tối thiểu 200mm và đảm bảo độ nhạy;\n- Hai chiếc tua tĩnh điện. Mỗi chiếc có các tua bằng sợi tổng hợp; quả cầu bằng kim loại đường kính khoảng 12mm gắn trên trụ inox có đường kính tối thiểu 6mm, có đế.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-VL-029', E'DM-THPT-VL-029', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'VAT_LY', 2400, E'14', E'Dụng cụ', E'Dòng điện, mạch điện', E'Thiết bị khảo sát nguồn điện', E'Đo suất điện động và điện trở trong của pin hoặc acquy', E'Bộ thí nghiệm gồm:\n- Đồng hồ đo điện đa năng (TBDC); hoặc cảm biến dòng điện thang đo ±1A, độ phân giải: ±1mA (TBDC) , và cảm biến điện thế thang đo: ±6 V, độ phân giải: ±0,01V (TBDC);\n- 2 pin 1,5V hoặc acquy;\n- Biến trở 100Ω, dây nối, công tắc, bảng để lắp mạch.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-VL-030', E'DM-THPT-VL-030', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
