(E'THPT', E'VAT_LY', 2450, E'19', E'Dụng cụ', E'Khí lí tưởng', E'Thiết bị chứng minh định luật Charles', E'Chứng minh định luật Charles', E'Bộ thiết bị gồm:\n- Áp kế 0 - 250kPa (hoặc tương đương);\n- Xi-lanh bằng vật liệu trong, thể tích ≤ 150ml, trên thân có chia độ, pít tông được liên kết với trục inox có ren và cơ cấu để có thể dịch chuyển theo vạch chia; bộ phận cấp nhiệt;\n- Nhiệt kế 0 - 110°C, độ chia nhỏ nhất 1°C hoặc cảm biến nhiết độ có thang đo từ -20°C đến 110°C, độ phân giải ±0,1°C.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-VL-035', E'DM-THPT-VL-035', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'VAT_LY', 2460, E'20', E'Dụng cụ', E'Từ trường (Trường từ)', E'Thiết bị tạo từ phổ', E'Tạo ra các đường sức từ', E'Hộp nhựa (hoặc mica) trong, (250x150x5)mm, không nắp; mạt sắt có khối lượng 100g; nam châm vĩnh cửu (120x10x20)mm.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-VL-036', E'DM-THPT-VL-036', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
