(E'THPT', E'HOA_HOC', 2680, E'3', E'Thiết bị dùng chung', NULL, E'Tủ hút', E'Hút thải khí độc hại, bụi, sương và hơi hóa chất tại vùng làm việc của tủ.', E'- Đảm bảo 5 hệ thống chính:\n+ Thân tủ chính. Gồm cấu trúc bên trong: Thép không gỉ 304; Tấm Phenonic HPL chống hoá chất; Cấu trúc bên ngoài: Thép mạ kẽm phủ sơn tĩnh điện.\nCửa sổ phía trước: Kính trắng cường lực dày tối thiểu 5mm; thay đổi tuỳ chỉnh chiều cao.\nMặt bàn làm việc: vật liệu kháng hóa chất, cao 800mm.\n+ Quạt hút (đặt trên đỉnh tủ). Động cơ quạt hút loại chuyên dụng cho hút hoá chất. Độ ồn và rung động tự do thấp: 56-60dBA\n+ Đèn chiếu sáng\n+ Hệ thống nước (chậu rửa, vòi cấp xả nước, bộ xả đáy) bằng vật liệu tổng hợp chịu hóa chất\n+ Bộ phận lọc không khí: có carbon hoạt tính.\n- Kích thước hộp tủ phù hợp với diện tích phòng học bộ môn theo quy chuẩn:\n+ Dài: 1200-1500mm\n+ Rộng: 800-1200mm\n+ Cao: 1800-2200mm (chưa bao gồm đường ống khí thải)\n- Nguồn điện: 220/240V/ 50-60Hz, một pha', TRUE, TRUE, FALSE, E'CAI', E'Cái', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-HH-003', E'DM-THPT-HH-003', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'HOA_HOC', 2690, E'4', E'Thiết bị dùng chung', NULL, E'Tủ đựng hóa chất', E'Đựng hóa chất', E'- Kích thước:\n+ Dài: 1000 – 1500mm\n+ Rộng: 500 – 550mm\n+ Cao: 1600 – 1800mm\n- Vật liệu: bền, kháng hóa chất;\n- Có quạt hút xử lý khí thải bằng than hoạt tính, có thể thay đổi tốc độ quạt;\n- Số cánh cửa: 2 – 4 cửa độc lập.', TRUE, TRUE, FALSE, E'CAI', E'Cái', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-HH-004', E'DM-THPT-HH-004', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'HOA_HOC', 2700, E'5', E'Thiết bị dùng chung', NULL, E'Máy chiếu (hoặc Màn hình hiển thị)', E'Trình chiếu nội dung bài học', E'Máy chiếu:\nLoại thông dụng.\n- Có đủ cổng kết nối phù hợp.\n- Cường độ sáng tối thiểu 3.500 Ansilumens.\n- Độ phân giải tối thiểu XGA\n- Kích cỡ khi chiếu lên màn hình tối thiểu 100 inch\n- Điều khiển từ xa\n- Kèm theo màn chiếu và thiết bị điều khiển. Màn hình hiển thị:\nLoại thông dụng, màn hình tối thiểu 50 inch, Full HD\n- Có đủ cổng kết nối phù hợp\n- Có ngôn ngữ hiển thị Tiếng Việt\n- Sử dụng điện AC 90-220V/50Hz\n- Điều khiển từ xa', TRUE, FALSE, FALSE, E'CAI', E'Cái', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'MAY_MOC_THIET_BI', E'PHYSICAL', E'SERIAL', NULL, E'THPT-HH-005', E'DM-THPT-HH-005', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'HOA_HOC', 2710, E'6', E'Thiết bị dùng chung', NULL, E'Máy tính (để bàn hoặc xách tay)', E'Thiết kế, trình chiếu,…nội dung bài học', E'- Loại thông dụng, tối thiểu phải cài đặt được các phần mềm phục vụ dạy học\n- Có kết nối LAN, Wifi và Bluetooth.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_CNTT', E'PHYSICAL', E'SERIAL', NULL, E'THPT-HH-006', E'DM-THPT-HH-006', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'HOA_HOC', 2720, E'7', E'Thiết bị dùng chung', NULL, E'Bộ thiết bị dạy học điện tử, mô phỏng môn Hóa học', E'Giúp giáo viên xây dựng kế hoạch dạy học (giáo án) điện tử, chuẩn bị bài giảng điện tử, chuẩn bị các học liệu điện tử, chuẩn bị các bài tập, bài kiểm tra, đánh giá điện tử phù hợp với Chương trình', E'Bộ học liệu điện tử, mô phỏng môn Hóa học được xây dựng theo Chương trình môn Hóa học cấp THPT (CTGDPT 2018), có hệ thống học liệu điện tử (mô phỏng 3D, hình ảnh, sơ đồ, video, các câu hỏi, đề kiểm tra,) đi kèm và được tổ chức, quản lý thành hệ thống thư viện điện tử, thuận lợi cho tra cứu và sử dụng. Bộ học liệu sử dụng được trên PC trong môi trường không kết nối internet. Phải đảm bảo tối thiểu các nhóm chức năng:\n- Nhóm chức năng hỗ trợ giảng dạy: soạn giáo án điện tử; hướng dẫn chuẩn bị bài giảng điện tử; học liệu điện tử (hình ảnh, sơ đồ, âm thanh, video…); chỉnh sửa học liệu (cắt video);\n- Nhóm chức năng mô phỏng và tương tác 3D: Điều hướng thay đổi trực tiếp góc nhìn theo ý muốn (xoay 360 độ, phóng to, thu nhỏ); quan sát và hiển thị thông tin cụ thể của các lớp khác nhau trong một mô hình, lựa chọn tách lớp một phần nội dung bất kỳ; tích hợp mô hình 3D vào bài giảng. Đảm bảo tối thiểu các mô hình: cấu tạo nguyên tử (theo mô hình Rutherford), liên kết hóa học, cấu trúc phân tử của methane, ethane, ethylene, acetylene, benzene, methanol, ethanol, phenol, methanal, ethanal, acetic acid, ester, glucose, Fructose, saccharose, maltose, tinh bột, cellulose, methylamine, aniline, amino acid, protein. Cấu tạo của pin điện và bình điện phân.\n- Nhóm chức năng hỗ trợ công tác kiểm tra đánh giá: hướng dẫn, chuẩn bị các bài tập; đề kiểm tra.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-HH-007', E'DM-THPT-HH-007', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'HOA_HOC', 2730, E'8', E'Thiết bị dùng chung', NULL, E'Bộ dụng cụ đo các đại lượng không điện', E'Sử dụng để đo các đại lượng phổ biến môn Hóa học', E'- Bộ thu thập dữ liệu: sử dụng để thu thập, hiển thị, xử lý và lưu trữ kết quả của các cảm biến. Có các cổng kết nối với các cảm biến và các cổng USB, SD để xuất dữ liệu. Được tích hợp màn hình màu cảm ứng để trực tiếp hiển thị kết quả từ các cảm biến. Phần mềm tự động nhận dạng và hiển thị tên, loại cảm biến. Có thể kết nối với máy tính lưu trữ, phân tích và trình chiếu dữ liệu. Thiết bị có thể sử dụng nguồn điện hoặc pin, ở chế độ sử dụng pin, thời lượng phải đủ để thực hiện các bài thí nghiệm.\n- Cảm biến đo Nhiệt độ (Thang đo tối thiểu từ -20°C tới 110°C, độ phân giải tối thiểu ±0,1°C.\n- Cảm biến đo Áp suất khí (Thang đo: 0 đến 250kPa, độ phân giải tối thiểu ±0,3kPa).\n- Cảm biến đo Độ pH (Thang đo 0-14pH, độ phân giải ±0,01pH\n- Cảm biến điện thế (Thang đo: ±6V, độ phân giải tối thiểu 0,01V).\n- Cảm biến dòng điện (Thang đo: ±1A, độ phân giải tối thiểu ±1mA).\n- Cảm biến đo độ dẫn điện (Thang đo: 0- 20.000μS/cm, độ phân giải tối thiểu ±1%).', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'02', 2, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-HH-008', E'DM-THPT-HH-008', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'HOA_HOC', 2740, E'1', E'Thiết bị theo chủ đề › Tranh ảnh', NULL, E'Bảng tuần hoàn các nguyên tố hóa học', E'Cung cấp kiến thức về bảng tuần hoàn các nguyên tố hóa học.', E'- Dạng bảng dài 18 cột có đầy đủ các thông số cơ bản: STT, ký hiệu, tên gọi theo quy định, NTK TB, độ âm điện, cấu hình e hóa trị, có màu sắc phân biệt kim loại, phi kim và á kim, công thức tổng quát của oxide và hydroxide cao nhất;\n- Kích thước (1800x1200)mm dung sai 10mm, in offset 4 màu trên giấy couché có định lượng 200g/m2, cán láng OPP mờ.', TRUE, FALSE, FALSE, E'TO', E'Tờ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-HH-009', E'DM-THPT-HH-009', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'HOA_HOC', 2750, E'1.1', E'Thiết bị theo chủ đề › Băng/đĩa/phần mềm', E'Nhập môn hóa học', E'Một số thao tác thí nghiệm hóa học', E'Hướng dẫn các thao tác thực hiện thí nghiệm', E'Bộ video có nội dung gồm các thao tác cơ bản hướng dẫn thực hiện thí nghiệm hóa học ở trường phổ thông (các thao tác do con người thực hiện).', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-HH-010', E'DM-THPT-HH-010', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'HOA_HOC', 2760, E'1.2', E'Thiết bị theo chủ đề › Băng/đĩa/phần mềm', E'BĂNG/ĐĨA/PHẦN MỀM DÙNG CHUNG CHO NHIỀU CHỦ ĐỀ', E'Bộ mô phỏng 3D', E'- Cung cấp kiến thức.\n- Trợ giúp HS tự học', E'Bộ mô phỏng 3D có nội dung gồm:\n- Cấu tạo nguyên tử (theo mô hình Rutherford), liên kết hóa học, cấu trúc phân tử của methane, ethane, ethylene, acetylene, benzene, methanol, ethanol, phenol, methanal, ethanal, acetic acid, ester , glucose, fructose, saccharose, maltose, tinh bột, cellulose, methylamine, aniline, amino acid, protein. Cấu tạo của pin điện và bình điện phân;\n- Một số quá trình: Sự chuyển hóa của tinh bột trong cơ thể, sự tạo thành tinh bột trong cây xanh.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-HH-011', E'DM-THPT-HH-011', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'HOA_HOC', 2770, E'2.1', E'Thiết bị theo chủ đề › Băng/đĩa/phần mềm', E'Arene', E'Thí nghiệm phản ứng nitro hoá benzene', E'- Cung cấp kiến thức.\n- Trợ giúp HS tự học', E'Một thí nghiệm có nội dung gồm:\n- Video thí nghiệm thật về dụng cụ, hóa chất, các thao tác, hiện tượng và kết quả thí nghiệm;\n- Mô phỏng 3D mô tả tiến trình phản ứng ở cấp độ phân tử, phương trình hóa học của phản ứng.', FALSE, TRUE, FALSE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-HH-012', E'DM-THPT-HH-012', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
