(E'THPT', E'SINH_HOC', 4280, E'30', NULL, E'I. THIẾT BỊ DÙNG CHUNG', E'Máy cất nước 1 lần', E'Cung cấp nước cất để pha dung dịch', E'- Công suất cất nước 4 lít/h.\n- Chất lượng nước đầu ra: Độ pH: 5.5–6.5; Độ dẫn điện: < 2.5 µS/cm.\n- Có chế độ tự ngắt khi quá nhiệt hoặc mất nguồn nước vào.\n- Máy được thiết kế để trên bàn thí nghiệm hoặc treo tường.\n- Giá đỡ/Hộp bảo vệ bằng kim loại có sơn tĩnh điện chống gỉ sét.\n- Nguồn điện 220V/240V-50Hz-3kW\n- 01 can nhựa trắng chứa nước cất, thể tích 30l', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-SH-030', E'DM-THPT-SH-030', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'SINH_HOC', 4290, E'31', NULL, E'I. THIẾT BỊ DÙNG CHUNG', E'Tủ hút', E'Hút thải khí độc hại, bụi, sương và hơi hóa chất tại vùng làm việc của tủ.', E'- Đảm bảo 5 hệ thống chính:\n+ Thân tủ chính. Gồm cấu trúc bên trong: Thép không gỉ 304; Tấm Phenonic HPL chống hoá chất; Cấu trúc bên ngoài: Thép mạ kẽm phủ sơn tĩnh điện.\nCửa sổ phía trước: Kính trắng cường lực dày tối thiểu 5mm; thay đổi tuỳ chỉnh chiều cao.\nMặt bàn làm việc: vật liệu kháng hóa chất, cao 800mm.\n+ Quạt hút (đặt trên đỉnh tủ). Động cơ quạt hút loại chuyên dụng cho hút hoá chất. Độ ồn và rung động tự do thấp: 56-60 dBA\n+ Đèn chiếu sáng\n+ Hệ thống nước (chậu rửa, vòi cấp xả nước, bộ xả đáy) bằng vật liệu tổng hợp chịu hóa chất\n+ Bộ phận lọc không khí: có carbon hoạt tính.\n- Kích thước hộp tủ phù hợp với diện tích phòng học bộ môn theo quy chuẩn:\n+ Dài: 1200-1500mm\n+ Rộng: 800-1200mm\n+ Cao: 1800-2200mm (chưa bao gồm đường ống khí thải)\n- Nguồn điện cung cấp: 220/240V/ 50-60Hz, một pha', TRUE, TRUE, FALSE, E'CAI', E'Cái', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-SH-031', E'DM-THPT-SH-031', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'SINH_HOC', 4300, E'32', NULL, E'I. THIẾT BỊ DÙNG CHUNG', E'Tủ bảo quản kính hiển vi', E'Bảo quản kính hiển vi', E'Đáp ứng các yêu cầu bảo quản chất lượng của kính hiển vi', TRUE, TRUE, FALSE, E'CAI', E'Cái', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-SH-032', E'DM-THPT-SH-032', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'SINH_HOC', 4310, E'33', NULL, E'I. THIẾT BỊ DÙNG CHUNG', E'Tủ bảo quản hóa chất', E'Bảo quản hóa chất', E'- Kích thước:\n+ Dài: 1000 – 1500mm;\n+ Rộng: 500 – 550mm;\n+ Cao: 1600 – 1800mm;\n- Vật liệu: bền, kháng hóa chất.\n- Có quạt hút xử lý khí thải bằng than hoạt tính, có thể thay đổi tốc độ quạt.\n- Số cánh cửa: 2 – 4 cửa độc lập', TRUE, TRUE, FALSE, E'CAI', E'Cái', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-SH-033', E'DM-THPT-SH-033', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
