(E'THPT', E'SINH_HOC', 4570, E'3.1', E'Thiết bị theo các chủ đề', E'Thành phần hóa học của tế bào', E'Bộ thí nghiệm xác định thành phần hóa học của tế bào', E'Thực hành xác định (định tính) một số thành phần hoá học có trong tế bào (protein, lipid,...).', E'Bộ thí nghiệm gồm:\n- Cối, chày sứ; Ống nghiệm; Giá để ống nghiệm; Đèn cồn; Cốc thủy tinh loại 250ml; Kẹp ống nghiệm; Lọ kèm ống nhỏ giọt; Lọ có nút nhám; Quả bóp cao su; Bút viết kính; (TBDC)\n- Cốc thủy tinh 100 ml.', FALSE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-SH-059', E'DM-THPT-SH-059', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'SINH_HOC', 4580, E'3.2', E'Thiết bị theo các chủ đề', E'Cấu trúc tế bào', E'Bộ thí nghiệm quan sát cấu trúc tế bào', E'Thực hành làm tiêu bản và quan sát tế bào nhân thực và tế bào nhân sơ', E'Bộ thí nghiệm gồm:\nKính hiển vi; Lam kính; Lamen; Kim mũi mác;\nDao cắt tiêu bản; Pipet; Giấy thấm; Đĩa đồng hồ;\n; Găng tay; (TBDC)', FALSE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-SH-060', E'DM-THPT-SH-060', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'SINH_HOC', 4590, E'3.3', E'Thiết bị theo các chủ đề', E'Chu kì tế bào và phân bào', E'Bộ thí nghiệm làm tiêu bản về quá trình nguyên phân và giảm phân', E'Làm tiêu bản quan sát các kì của quá trình phân bào', E'Bộ thí nghiệm gồm:\n- Kính hiển vi; Bộ đồ mổ; Lam kính (10 cái) Lamen; Kim mũi mác;Dao cắt tiêu bản; Đèn cồn; Đĩa đồng hồ; Giấy thấm; Găng tay; (TBDC.)\n- Tiêu bản các giai đoạn của quá trình nguyên phân (Tiêu bản cố định, rõ nét nhìn thấy được các giai đoạn của quá trình nguyên phân ở hành tây, hành ta);\n- Tiêu bản các giai đoạn của quá trình giảm phân (Tiêu bản cố định, rõ nét nhìn thấy được các giai đoạn của quá trình, giảm phân ở châu chấu, hoa hành.', FALSE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-SH-061', E'DM-THPT-SH-061', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'SINH_HOC', 4600, E'3.4', E'Thiết bị theo các chủ đề', E'Vi sinh vật', E'Bộ thí nghiệm thực hành phương pháp nghiên cứu vi sinh vật và sản phẩm ứng dụng', E'Thực hành các phương pháp nghiên cứu vi sinh vật và tạo sản phẩm ứng dụng.', E'Bộ thí nghiệm gồm:\n- Đĩa petri; Lam kính; Lamen; Kim mũi mác; Kính hiển vi; Giấy thấm; Pipet; Đèn cồn; Bình tia nước; (TBDC);\n- Tủ sấy (01 cái), loại thông dụng trong phòng thí nghiệm;\n- Cốc thủy tinh 100 ml - Bình thủy tinh 2L có nắp đậy (Loại thông dụng);\n- Cốc thủy tinh 100 ml có nắp đậy (Loại thông dụng);\n- Khay inox (200x270)mm (Loại thông dụng);\n- Bát inox miệng 300mm (Loại thông dụng);\n- Ống đong 500ml (Loại thông dụng);\n- Giấy đo pH (Loại thông dụng) hoặc cảm biến độ pH (TBDC).', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-SH-062', E'DM-THPT-SH-062', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'SINH_HOC', 4610, E'3.5', E'Thiết bị theo các chủ đề', E'Trồng cây trong dung dịch', E'Bộ thiết bị khảo sát một số dữ liệu khi trồng cây', E'Nghiên cứu sự trao đổi nước và muối khoáng của thực vật khi trồng thủy canh.', E'Bộ thiết bị gồm:\n- Bộ thu nhận tín hiệu; Giấy đo pH hoặc Cảm biến độ pH; Cảm biến độ ẩm; Cân điện tử; (TBDC);\n- Thước nhựa loại thông dung, 300mm.', FALSE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-SH-063', E'DM-THPT-SH-063', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'SINH_HOC', 4620, E'3.6', E'Thiết bị theo các chủ đề', E'Trao đổi nước ở cơ thể thực vật.', E'Bộ thiết bị khảo sát định tính sự trao đổi nước ở cơ thể thực vật', E'Thực hiện được các thí nghiệm chứng minh sự hút nước ở rễ; vận chuyển nước ở thân và thoát hơi nước ở lá', E'Bộ thiết bị gồm:\n- Ống nghiệm; Giá đựng ống nghiệm; Pipet; Cốc thủy tinh; (TBDC)\n- Giấy clorua coban (1 hộp );\n- Nút cao su; Dao nhỏ.', FALSE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-SH-064', E'DM-THPT-SH-064', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'SINH_HOC', 4630, E'3.7', E'Thiết bị theo các chủ đề', E'Quan sát lục lạp và tách chiết các sắc tố trong lá cây', E'Bộ thiết bị quan sát lục lạp và tách chiết các sắc tố trong lá cây', E'Thực hành quan sát lục lạp trong tế bào thực vật; nhận biết, tách chiết các sắc tố (chlorophyll a, b; carotene và xanthophyll) trong lá cây', E'Bộ thiết bị gồm:\n- Cối, chày sứ Cốc đong; Pipet; Ống nghiệm; Giá để ống nghiệm; Kính hiển vi; Lamen; Lam kính; Đũa thủy tinh; (TBDC);\n- Phễu;\n- Thủy tinh, đường kính miệng phễu từ 80– 90mm, cuống phễu dài khoảng 65mm;\n- Bình tam giác, loại thủy tinh trung tính, chịu nhiệt, dung tích 100 ml, độ chia nhỏ nhất 20ml, đường kính miệng 20mm. Đảm bảo độ bền cơ học;\n- Thước nhựa;\n- Ống mao quản chấm sắc ký. Loại 1+2+3+4+5 µl, dài 125mm, có vạch mức;\n- Giấy sắc kí bản mỏng. Kích cỡ bản có sẵn (200x200mm; 100x200mm và 50x200mm);\n- Bút chỉ 2B.', FALSE, TRUE, FALSE, E'BO', E'Bộ', E'07', 7, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'THPT-SH-065', E'DM-THPT-SH-065', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
