(E'THPT', E'SINH_HOC', 5260, E'4.14', E'Thiết bị theo các chủ đề', E'Sinh thái nhân văn', E'Video về giá trị của sinh thái nhân văn trong việc phát triển bền vững ở một số lĩnh vực (nông nghiệp, phát triển đô thị, bảo tồn và phát triển, thích ứng với biến đổi khí hậu)', E'Tìm hiểu giá trị của sinh thái nhân văn trong việc phát triển bền vững ở một số lĩnh vực (nông nghiệp, phát triển đô thị, bảo tồn và phát triển, thích ứng với biến đổi khí hậu)', E'Video mô tả về giá trị của sinh thái nhân văn trong việc phát triển bền vững (ví dụ: ảnh hưởng của xây dựng đập hồ thủy điện đến sự phát triển của nông thôn, miền núi; phục hồi suy thoái vùng trung du; quản lý rừng ngập mặn; cách thiết kế một đô thị xanh)', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, E'01/GV', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-SH-127', E'DM-THPT-SH-128', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'CONG_NGHE', 5270, E'1', E'Định hướng công nghiệp › Thiết bị dùng chung', NULL, E'Bộ vật liệu cơ khí', E'Thực hành, vận dụng kiến thức vào thực tiễn.', E'Bộ vật liệu cơ khí gồm:\n- Tấm nhựa Formex (khổ A3, dày 3 và 5mm), số lượng 10 tấm mỗi loại;\n- Tấm nhựa Acrylic (A4, trong suốt, dày 3mm), số lượng 10 tấm;\n- Thanh keo nhiệt (đường kính 10mm), số lượng 10 thanh;\n- Vít ren và đai ốc M3, 100 cái;\n- Vít gỗ các loại, 100 cái;\n- Mũi khoan (đường kính 3mm), 5 mũi;\n- Bánh xe (đường kính 65mm, trục 5mm), 10 cái;\n- Hộp đựng dụng cụ làm bằng vật liệu nhựa cứng có độ bền cao, có tay xách, kích thước: (430x230x200)mm.', TRUE, TRUE, TRUE, E'BO', E'Bộ', E'03', 3, E'PER_SCHOOL', NULL, E'10,11,12', E'Dùng cho lớp 10, 11, 12', E'DO_DUNG_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'THPT-CN-001', E'DM-THPT-CN-001', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'CONG_NGHE', 5280, E'2', E'Định hướng công nghiệp › Thiết bị dùng chung', NULL, E'Bộ dụng cụ cơ khí', E'Thực hành, vận dụng kiến thức vào thực tiễn.', E'Bộ dụng cụ cơ khí gồm:\n- Thước lá (dài 300mm);\n- Thước cặp cơ (vật liệu: hợp kim thép, kích thước: 150mm, thang đo từ 0 đến 150mm; dung sai: 0,02mm);\n- Đầu vạch dấu (vật liệu: hợp kim thép HSS Độ cứng HRC58~65; kích thước: 130mm, đường kính: 13mm);\n- Thước đo góc (vật liệu: thép không gỉ; Khoảng đo: 0-180°/145mm; Độ chia: 1°, Độ chính xác: +/- 20′);\n- Thước đo mặt phẳng (loại thông dụng);\n- Dao dọc giấy (loại thông dụng);\n- Dao cắt nhựa Acrylic (loại thông dụng);\n- Ê tô nhỏ (Kích thước tổng thể 195x163mm; Ngàm mở rộng tối đa: 50mm; Vật liệu: Gang, thép);\n- Dũa (dẹt, tròn), mỗi loại một chiếc;\n- Cưa tay (vật liệu thép không gỉ, cán làm bằng nhựa hoặc bằng gỗ, lưỡi cưa làm bằng théo hợp kim carbon, chiều dài lưỡi cưa và tay cầm: 300mm);\n- Tuốc nơ vít mũi dẹt (cán làm bằng vật liệu cách điện, phần thân làm bằng vật liệu thép không gỉ, chiều dài: 250mm);\n- Tuốc nơ vít bốn cạnh (Cán làm bằng vật liệu cách điện, mũi và thân tròn làm bằng thép không gỉ, chiều dài: 250mm);\n- Mỏ lết cỡ nhỏ (vật liệu hợp kim thép cứng không gỉ, chiều dài 200mm);\n- Kìm mỏ vuông (mũi kìm làm bằng thép hợp kim cứng không gỉ, phần tay cầm làm bằng vật liệu cách điện, kích thước chiều dài: 180mm);\n- Búa cỡ nhỏ (Đầu búa làm bằng hợp kim cứng, cán búa làm bằng vật liệu cách điện chống trượt, chiều dài búa: 320mm);\n- Súng bắn keo (loại 10mm, công suất 60W).', TRUE, TRUE, TRUE, E'BO', E'Bộ', E'04', 4, E'PER_SCHOOL', NULL, E'10,11,12', E'Dùng cho lớp 10, 11, 12', E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-CN-002', E'DM-THPT-CN-002', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'CONG_NGHE', 5290, E'3', E'Định hướng công nghiệp › Thiết bị dùng chung', NULL, E'Bộ thiết bị cơ khí cỡ nhỏ', E'Thực hành, vận dụng kiến thức vào các vấn đề trong thực tiễn', E'Bộ thiết bị cơ khí cỡ nhỏ gồm:\n- Máy in 3D cỡ nhỏ (Công nghệ in: FDM, Độ phân giải layer: 0,05-0,3mm, Đường kính đầu in: 0,4mm/1,75MM, Vật liệu in: PLA, ABS, Kích thước làm việc tối đa: (200x200x180)mm, Kết nối: Thẻ SD, Cổng USB);\n- Khoan điện cầm tay (sử dụng pin)_03 chiếc.', TRUE, TRUE, TRUE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, E'10,11,12', E'Dùng cho lớp 10, 11, 12', E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-CN-003', E'DM-THPT-CN-003', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'CONG_NGHE', 5300, E'4', E'Định hướng công nghiệp › Thiết bị dùng chung', NULL, E'Bộ vật liệu điện', E'Thực hành, vận dụng kiến thức vào thực tiễn.', E'Bộ vật liệu điện gồm:\n- Pin lithium (loại 3.7V, 1200 maH), 9 cục;\n- Đế pin Lithium (loại đế ba), 03 cái;\n- Dây điện màu đen, mầu đỏ (đường kính 0.3mm), 20 m cho mỗi mầu;\n- Dây kẹp cá sấu 2 đầu (dài 300mm), 30 sợi;\n- Gen co nhiệt (đường kính 2 và 3mm), mỗi loại 2m;\n- Băng dính cách điện 05 cuộn;\n- Phíp đồng một mặt (A4, dày 1,2mm), 5 tấm;\n- Muối FeCl3, 500g;\n- Thiếc hàn cuộn (loại 100 g), 03 cuộn;\n- Nhựa thông 300g;\n- Hộp đựng dụng cụ làm bằng vật liệu nhựa cứng có độ bền cao, có tay xách, kích thước: (430x230x200)mm.', TRUE, TRUE, TRUE, E'BO', E'Bộ', E'04', 4, E'PER_SCHOOL', NULL, E'10,11,12', E'Dùng cho lớp 10, 11, 12', E'DO_DUNG_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'THPT-CN-004', E'DM-THPT-CN-004', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'CONG_NGHE', 5310, E'5', E'Định hướng công nghiệp › Thiết bị dùng chung', NULL, E'Bộ dụng cụ điện', E'Thực hành, vận dụng kiến thức vào thực tiễn.', E'Bộ dụng cụ điện gồm:\n- Sạc pin Lithium (khay sạc đôi, dòng sạc 600mA);\n- Đồng hồ vạn năng số (Độ phân giải hiển thị: 12.000 chữ số, Dải đo điện áp AC/DC/AC rms: 0 - 1000V; Sai số cơ bản: 0,5%, Dải đo dòng điện AC/DC: 0 - 10A; Sai số cơ bản: 1,5%, Tần số đo đến 1 MHz, Dải đo điện trở: 0 - 40 MΩ);\n- Bút thử điện (loại thông dụng);\n- Kìm tuốt dây điện (đầu kìm làm bằng hợp kim thép không gỉ, cán làm bằng vật liệu cách điện, Kích thước dây tuốt: 0.6;0.8;1.0, 1.3; 1.6; 2.0; 2.6mm, Kích thước chiều dài: 180x60mm);\n- Kìm mỏ nhọn (đầu kìm làm bằng hợp kim thép không gỉ, cán làm bằng vật liệu cách điện);\n- Kìm cắt (đầu kìm làm bằng hợp kim thép không gỉ, cán làm bằng vật liệu cách điện, Kích thước: (150x55x15)mm;\n- Mỏ hàn thiếc (AC 220V, 60W), kèm đế mỏ hàn (loại thông dụng);\n- Hộp đựng dụng cụ làm bằng vật liệu nhựa cứng có độ bền cao, có tay xách, kích thước: (430x230x200)mm.', TRUE, TRUE, TRUE, E'BO', E'Bộ', E'04', 4, E'PER_SCHOOL', NULL, E'10,11,12', E'Dùng cho lớp 10, 11, 12', E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-CN-005', E'DM-THPT-CN-005', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'CONG_NGHE', 5320, E'6', E'Định hướng công nghiệp › Thiết bị dùng chung', NULL, E'Dụng cụ đo các đại lượng không điện.', E'Thực hành, vận dụng kiến thức vào thực tiễn.', E'Bộ dụng cụ đo gồm:\n- Bộ thu thập dữ liệu: sử dụng để thu thập, hiển thị, xử lý và lưu trữ kết quả của các cảm biến tương thích trong danh mục. Có các cổng kết nối với các cảm biến và các cổng USB, SD để xuất dữ liệu. Được tích hợp màn hình màu, cảm ứng để trực tiếp hiển thị kết quả từ các cảm biến. Phần mềm tự động nhận dạng và hiển thị tên, loại cảm biến. Có thể kết nối với máy tính lưu trữ, phân tích và trình chiếu dữ liệu. Được tích hợp các công cụ để phân tích dữ liệu.\n- Cảm biến đo nồng độ khí C02 (thang đo: 0 ~ 50.000ppm, độ phân giải: 1ppm; độ chính xác: ±10%);\n- Cảm biến đo Lượng Oxi hòa tan trong nước (thang đo: 0 đến 20mg/L, độ chính xác: ±2%);\n- Cảm biến đo Nồng độ khí Oxi trong không khí (thang đo: 0 đến 27%, độ chính xác ±1% trên toàn thang đo, nhiệt độ hoạt động: -20 ~ 50°C, độ ẩm hoạt động: 0 ~ 99%);\n- Cảm biến đo Nhiệt độ (thang đo từ -20°C đến 120°C, độ phân giải ±0.03°C);\n- Cảm biến đo Độ ẩm (khoảng đo: 0 đến 100%, độ chính xác: ±3%);\n- Cảm biến đo Nồng độ mặn (thang đo: 0ppt ~ 50ppt, độ phân giải: ±0.1ppt, độ chính xác: ±1% trên toàn thang đo);\n- Cảm biến đo Độ pH (Thang đo: 0-14pH, độ phân giải: ±0,01pH, nhiệt độ hoạt động: 5- 60°C);\n- Cảm biến đo Cường độ âm thanh (tùy chọn 2 thang đo: 40 - 100 dBA hoặc 80 - 130 dBA, độ chính xác: ±0.1 dBA trên toàn thang đo);\n- Cảm biến đo Áp suất khí (thang đo: 0 đến 250kPa, độ phân giải: ±0.1kPa trên toàn thang đo).\n- Hộp đựng dụng cụ làm bằng vật liệu nhựa cứng có độ bền cao, có tay xách, kích thước: (430x230x200)mm', TRUE, TRUE, TRUE, E'BO', E'Bộ', E'02', 2, E'PER_SCHOOL', NULL, E'10,11,12', E'Dùng cho lớp 10, 11, 12', E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-CN-006', E'DM-THPT-CN-006', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'CONG_NGHE', 5330, E'7', E'Định hướng công nghiệp › Thiết bị dùng chung', NULL, E'Bộ công cụ phát triển ứng dụng dựa trên vi điều khiển.', E'Thực hành, vận dụng kiến thức vào thực tiễn.', E'Bộ dụng cụ bao gồm:\n- Mô đun hạ áp DC-DC (2A, 4 – 36 V);\n- Mô đun cảm biến: nhiệt độ (đầu ra số, độ chính xác: ± 0,5oC), độ ẩm (đầu ra số, độ chính xác: ± 2% RH), ánh sáng (đầu ra tương tự và số, sử dụng quang trở), khí gas (đầu ra tương tự và số), chuyển động (đầu ra số, góc quét: 120 độ), khoảng cách (dầu ra số, công nghệ siêu âm);\n- Nút ấn 4 chân, kích thước (6x6x5)mm;\n- Bảng mạch lập trình vi điều khiển mã nguồn mở (loại thông dụng);\n- Mô đun giao tiếp: Bluetooth (2.0, giao tiếp: serial port, tần số: 2,4 GHz), RFID (tần số sóng mang: 13,56 MHz, giao tiếp: SPI), Wifi (2,4 GHz, hỗ trợ chuẩn 802.11 b/g/n, hỗ trợ bảo mật: WPA/WPA2, giao tiếp: Micro USB);\n- Thiết bị chấp hành: Động cơ điện 1 chiều (9- 12V, 0,2A, 150-300 vòng/phút), Động cơ servo (4,8V, tốc độ: 0,1s/600), Động cơ bước (12-24V, bước góc: 1,80, kích thước: 42x42x41,5mm), còi báo (5V, tần số âm thanh: 2,5 KHz);\n- Mô đun chức năng: Mạch cầu H (5-24V, 2A), Điều khiển động cơ bước (giải điện áp hoạt động 8- 45V, dòng điện: 1,5 A), rơ le (12V);\n- Linh, phụ kiện: board test (150x55mm), dây dupont (loại thông dụng), linh kiện điện tử (điện trở, tụ điện các loại, transistor, LED, diode, công tắc các loại).\n- Hộp đựng dụng cụ làm bằng vật liệu nhựa cứng có độ bền cao, có tay xách, kích thước (430x230x200)mm', TRUE, TRUE, TRUE, E'BO', E'Bộ', E'04', 4, E'PER_SCHOOL', NULL, E'10,11,12', E'Dùng cho lớp 10, 11, 12', E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-CN-007', E'DM-THPT-CN-007', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'CONG_NGHE', 5340, E'8', E'Định hướng công nghiệp › Thiết bị dùng chung', NULL, E'Máy tính (để bàn hoặc xách tay)', E'Thiết kế, mô phỏng hệ thống cơ khí, mạch điện, in 3D', E'- Loại thông dụng, tối thiểu phải cài đặt được các phần mềm phục vụ dạy học. Đảm bảo được các nhiệm vụ Thiết kế, mô phỏng hệ thống cơ khí, mạch điện, in 3D.\n- Có kết nối LAN, Wifi và Bluetooth.', TRUE, TRUE, TRUE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, E'10,11,12', E'Dùng cho lớp 10, 11, 12', E'THIET_BI_CNTT', E'PHYSICAL', E'SERIAL', NULL, E'THPT-CN-008', E'DM-THPT-CN-008', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'CONG_NGHE', 5350, E'9', E'Định hướng công nghiệp › Thiết bị dùng chung', NULL, E'Biến áp nguồn', E'Sử dụng trong các bài thực hành, thí nghiệm', E'Điện áp vào 220V- 50Hz\nĐiện áp ra:\n- Điện áp xoay chiều (5A): (3, 6, 9, 12, 15, 24) V.\n- Điện áp một chiều (3A): điều chỉnh từ 0 đến 24 V.\nCó đồng hồ chỉ thị điện áp ra; có mạch đóng ngắt và bảo vệ quá dòng, đảm bảo an toàn về độ cách điện và độ bền điện trong quá trình sử dụng.', TRUE, TRUE, TRUE, E'BO', E'Bộ', E'04', 4, E'PER_SCHOOL', NULL, E'10,11,12', E'Dùng cho lớp 10, 11, 12', E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-CN-009', E'DM-THPT-CN-009', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
