(E'THPT', E'AM_NHAC', 6530, E'1', E'Thiết bị dùng chung cho các nội dung', NULL, E'Thiết bị âm thanh đa năng di động', E'GV và HS sử dụng khi nghe nhạc và các hoạt động âm nhạc khác', E'- Tích hợp được nhiều tính năng âm ly, loa, micro, đọc phát các định dạng tối thiểu ghi trên SD, USB trên thiết bị;\n- Kết nối line-in, audio in, bluetooth với nguồn phát âm thanh;\n- Công suất phù hợp với lớp học;\n- Kèm theo micro;\n- Nguồn điện: AC 220V/50Hz; DC, có ắc quy/pin sạc.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'MAY_MOC_THIET_BI', E'PHYSICAL', E'SERIAL', NULL, E'THPT-AN-022', E'DM-THPT-AN-022', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'MY_THUAT', 6540, E'1', NULL, E'Mĩ thuật tạo hình và mĩ thuật ứng dụng', E'Máy tính', E'Dùng cho GV, tìm kiếm tư liệu. Thực hành thiết kế và trình chiếu hình ảnh', E'- Loại thông dụng, tối thiểu phải cài đặt được các phần mềm phục vụ dạy và học;\n- Có kết nối LAN, Wifi và Bluetooth.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, E'10,11,12', E'Dùng cho lớp 10,11,12', E'THIET_BI_CNTT', E'PHYSICAL', E'SERIAL', NULL, E'THPT-MT-001', E'DM-THPT-MT-001', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'MY_THUAT', 6550, E'2', NULL, E'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', E'Máy chiếu (hoặc Màn hình hiển thị)', E'Dùng cho GV, trình chiếu, thuyết trình.', E'Máy chiếu:\n- Loại thông dụng;\n- Có đủ cổng kết nối phù hợp;\n- Cường độ sáng tối thiểu 3.500 Ansilumens;\n- Độ phân giải tối thiểu XGA;\n- Kích cỡ khi chiếu lên màn hình tối thiểu 100 inch;\n- Điều khiển từ xa;\n- Kèm theo màn chiếu và thiết bị điều khiển (nếu có).\nMàn hình hiển thị:\n- Loại thông dụng, màn hình tối thiểu 50 inch, Full HD;\n- Có đủ cổng kết nối phù hợp;\n- Có ngôn ngữ hiển thị Tiếng Việt;\n- Điều khiển từ xa;\n- Nguồn điện: AC 90-220V/50Hz.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, E'10,11,12', E'Dùng cho lớp 10,11,12', E'MAY_MOC_THIET_BI', E'PHYSICAL', E'SERIAL', NULL, E'THPT-MT-002', E'DM-THPT-MT-002', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'MY_THUAT', 6560, E'3', NULL, E'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', E'Đèn chiếu sáng', E'Chiếu sáng mẫu vẽ cho học sinh', E'Loại đèn thông dụng có chao; chân cao có điều chỉnh được các góc độ chiếu sáng khác nhau; dây điện dài; ánh sáng vàng; công suất tối thiểu 20W.', FALSE, TRUE, FALSE, E'BO', E'Bộ', E'02', 2, E'PER_SCHOOL', NULL, E'10,11,12', E'Dùng cho lớp 10, 11, 12', E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-MT-003', E'DM-THPT-MT-003', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'MY_THUAT', 6570, E'4', NULL, E'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', E'Giá để mãu vẽ và dụng cụ học tập', E'Bảo quản mẫu vẽ, dụng cụ và sản phẩm học tập.', E'- Giá có nhiều ngăn, bằng vật liệu cứng dễ tháo lắp và an toàn trong sử dụng;\n- Kích thước: Phù hợp với diện tích phòng học\nbộ môn và chiều cao trung bình của HS.', TRUE, TRUE, FALSE, E'CAI', E'Cái', E'02', 2, E'PER_SCHOOL', NULL, E'10,11,12', E'Dùng cho lớp 10,11,12', E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-MT-004', E'DM-THPT-MT-004', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'MY_THUAT', 6580, E'5', NULL, E'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', E'Bàn, ghế học mĩ thuật', E'Dùng cho HS vẽ, in, nặn, thiết kế', E'- Mặt bàn phẳng và chân chịu lực, chịu nước, có thể gấp gọn; Kích thước phù hợp với HS trung học phổ thông (600x1200)mm cao 850mm;\n- Ghế đơn không có tựa, điều chỉnh được cao/thấp.', FALSE, TRUE, FALSE, E'BO', E'Bộ', E'01/02HS', 1, E'PER_STUDENT', 2, E'10,11,12', E'Dùng cho lớp 10,11,12', E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-MT-005', E'DM-THPT-MT-005', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'MY_THUAT', 6590, E'6', NULL, E'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', E'Bục, bệ', E'Làm bục, bệ đặt mẫu cho HS vẽ', E'- Bộ bục, bệ gồm 2 loại có kích thước như sau: Loại (1) dài 800mm, rộng 800mm, cao 1000mm; Loại (2) dài 200mm, rộng 300mm, cao 200mm;\n- Chất liệu: Bằng gỗ có khung (hoặc vật liệu có độ cứng tương đương), không cong vênh, chịu được nước, an toàn trong sử dụng. Màu trắng hoặc màu sáng.', FALSE, TRUE, FALSE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, E'10,11,12', E'Dùng cho lớp 10,11,12', E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-MT-006', E'DM-THPT-MT-006', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'MY_THUAT', 6600, E'7', NULL, E'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', E'Tủ/giá', E'Bảo quản sản phẩm đồ dùng, công cụ học tập.', E'Chất liệu bằng sắt hoặc bằng gỗ; Kích thước (1760x1060x400)mm; ngăn đựng có thể thay đổi được chiều cao, cửa có khóa; chắc chắn, bền vững, đảm bảo an toàn khi sử dụng.', TRUE, TRUE, FALSE, E'CAI', E'Cái', E'03', 3, E'PER_SCHOOL', NULL, E'10,11,12', E'Dùng cho lớp 10,11,12', E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-MT-007', E'DM-THPT-MT-007', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'MY_THUAT', 6610, E'8', NULL, E'I. THIẾT BỊ, DỤNG CỤ DÙNG CHUNG', E'Mẫu vẽ', E'Làm mẫu vẽ cho HS', E'Bộ mẫu vẽ gồm có 6 khối\n- Khối cơ bản 3 khối:\n+ 01 khối lập phương kích thước: (250x250x250)mm.\n+ 01 khối cầu đường kính 200mm.\n+ 01 khối hình chóp tam giác cân, đáy hình vuông, kích thước: các cạnh đáy (200x200)mm; cao 400mm.\n- Khối biến thể 3 khối:\n+ 01 khối hộp chữ nhật kích thước: dài 300mm, rộng 150mm; cao100mm.\n+ 01 khối trụ kích thước: cao 300mm; đường kính 150mm.\n+ 01 khối chóp nón kích thước: chiều cao 350mm, đường kính đáy 250mm.\n- Chất liệu: Bằng gỗ, (hoặc vật liệu có độ cứng tương đương), không cong vênh, chịu được nước, an toàn trong sử dụng. Màu trắng hoặc ghi sáng.', FALSE, TRUE, FALSE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, E'10,11,12', E'Dùng cho lớp 10,11,12', E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-MT-008', E'DM-THPT-MT-008', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
