(E'THPT', E'MY_THUAT', 6920, E'1.1', NULL, E'Hình họa khối cơ bản', E'Tranh hướng dẫn cách vẽ hình họa khối cơ bản', E'HS tìm hiểu các bước vẽ khối cơ bản.', E'- 01 tờ tranh hướng dẫn các bước vẽ hình họa khối cơ bản bằng chì. Gồm các bước:\n+ Bước 1: Vẽ phác khung hình chung toàn bộ nhóm mẫu khối cơ bản.\n+ Bước 2: Xác định tỉ lệ. Vẽ phác khung hình riêng từng vật mẫu khối cơ bản và hoàn thiện phần hình.\n+ Bước 3: Phân định mảng sáng tối/đậm nhạt lớn của nhóm mẫu, của từng mẫu và diễn tả sáng tối/đậm nhạt của khối .\n+ Bước 4: Hoàn thiện bài vẽ (hình và đậm nhạt) theo tương quan chung.\n- Kích thước (790x540)mm.', TRUE, TRUE, FALSE, E'TO', E'Tờ', E'01', 1, E'PER_SCHOOL', NULL, E'10', E'Dùng cho lớp 10', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-MT-038', E'DM-THPT-MT-039', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'MY_THUAT', 6930, E'1.2', NULL, E'Hình họa tượng phạt mảng', E'Tranh hướng dẫn cách vẽ tượng phạt mảng', E'HS tìm hiểu các bước vẽ tượng phạt mảng.', E'- 01 tờ tranh hướng dẫn các bước vẽ tượng phạt mảng bằng chì. Gồm các bước:\n+ Bước 1: Vẽ phác khung hình chung toàn bộ đầu tượng và trục mặt (trục ngang và trục dọc)\n+ Bước 2: Xác định tỉ lệ và phác hình các mảng/diện lớn của tượng, các bộ phận: trán, mắt, mũi, miệng, cằm, tai.\n+ Bước 3: Vẽ chi tiết và diễn tả sáng tối/đậm nhạt theo diện mảng của tượng\n+ Bước 4: Hoàn thiện bài vẽ (hình và đậm nhạt) theo tương quan chung.\n- Kích thước (790x540)mm.', TRUE, TRUE, FALSE, E'TO', E'Tờ', E'01', 1, E'PER_SCHOOL', NULL, E'11', E'Dùng cho lớp 11', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-MT-039', E'DM-THPT-MT-040', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'MY_THUAT', 6940, E'1.3', NULL, E'Hình họa tượng chân dung', E'Tranh hướng dẫn cách vẽ tượng chân dung', E'HS tìm hiểu các bước vẽ tượng chân dung.', E'- 01 tờ tranh hướng dẫn các bước vẽ tượng chân dung bằng chì (hoặc than). Gồm các bước:\nBước 1: Vẽ phác khung hình chung toàn bộ đầu tượng và trục mặt (trục ngang và trục dọc)\n+ Bước 2: Xác định tỉ lệ và phác hình các các bộ phận: trán, mắt, mũi, miệng, cằm, tai.\n+ Bước 3: Vẽ chi tiết và diễn tả sáng tối/đậm nhạt của tượng.\n+ Bước 4: Hoàn thiện bài vẽ (hình và đậm nhạt) theo tương quan chung.\n- Kích thước (790x540)mm.', TRUE, TRUE, FALSE, E'TO', E'Tờ', E'01', 1, E'PER_SCHOOL', NULL, E'12', E'Dùng cho lớp 12', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-MT-040', E'DM-THPT-MT-041', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'MY_THUAT', 6950, E'2.1', NULL, E'Trang trí hình vuông', E'Tranh hướng dẫn cách trang trí hình vuông', E'HS tìm hiểu các bước vẽ trang trí hình vuông', E'- 01 tờ tranh hướng dẫn các bước vẽ trang trí hình vuông bằng màu bột hoặc màu nước. Gồm các bước:\n+ Bước 1: Kẻ các đường trục và sắp xếp bố cục mảng chính, mảng phụ trong hình vuông.\n+ Bước 2: Tìm đậm nhạt của các mảng chính, mảng phụ.\n+ Bước 3: Tìm họa tiết phù hợp với hình mảng và vẽ họa tiết vào mảng chính, mảng phụ của hình vuông.\n+ Bước 4: Vẽ màu và hoàn thiện bài (lưu ý màu sắc cần có đậm nhạt, nổi rõ trọng tâm).\nCuối tờ hình hướng dẫn có hai bài trang trí hình vuông hoàn thiện có bố cục, màu sắc và họa tiết khác nhau.\n- Kích thước (790x540)mm.', TRUE, TRUE, FALSE, E'TO', E'Tờ', E'01', 1, E'PER_SCHOOL', NULL, E'10', E'Dùng cho lớp 10', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-MT-041', E'DM-THPT-MT-042', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'MY_THUAT', 6960, E'2.2', NULL, E'Trang trí hình tròn', E'Tranh hướng dẫn cách trang trí hình tròn', E'HS tìm hiểu các bước vẽ trang trí hình tròn', E'- 01 tờ tranh hướng dẫn các bước vẽ trang trí hình tròn bằng màu bột hoặc màu nước. Gồm các bước:\n+ Bước 1: Kẻ các đường trục và sắp xếp bố cục mảng chính, mảng phụ trong hình tròn.\n+ Bước 2: Tìm đậm nhạt của các mảng chính, mảng phụ trong hình tròn.\n+ Bước 3: Tìm họa tiết phù hợp với hình mảng và vẽ họa tiết vào mảng chính, mảng phụ của hình tròn.\n+ Bước 4: Vẽ màu và hoàn thiện bài (lưu ý màu sắc cần có đậm nhạt, nổi rõ trọng tâm).\nCuối tờ hình hướng dẫn có hai bài trang trí hình tròn hoàn thiện có bố cục, màu sắc và họa tiết khác nhau.\n- Kích thước (790x540)mm.', TRUE, TRUE, FALSE, E'TO', E'Tờ', E'01', 1, E'PER_SCHOOL', NULL, E'11', E'Dùng cho lớp 11', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-MT-042', E'DM-THPT-MT-043', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'MY_THUAT', 6970, E'2.3', NULL, E'Trang trí đường diềm', E'Tranh hướng dẫn cách trang trí đường diềm', E'HS tìm hiểu các bước vẽ trang trí đường diềm', E'- 01 tờ tranh hướng dẫn các bước vẽ trang trí đường diềm bằng màu bột hoặc màu nước. Gồm các bước:\n+ Bước 1: Chia các khoảng cách đều nhau trên hai đường thẳng song song;\n+ Bước 2: Kẻ đường trục trong các ô của đường diềm;\n+ Bước 3: Tìm mảng chính, mảng phụ và vẽ họa tiết vào các ô của đường diềm;\n+ Bước 4: Vẽ màu và hoàn thiện bài (lưu ý: màu sắc cần có đậm nhạt, nổi rõ trọng tâm); Cuối tờ hình hướng dẫn có thêm hai đường diềm đã hoàn thiện: một đường diềm được sắp xếp nhắc lại; một đường diềm được sắp xếp xen kẽ.\n- Kích thước (790x540)mm.', TRUE, TRUE, FALSE, E'TO', E'Tờ', E'01', 1, E'PER_SCHOOL', NULL, E'12', E'Dùng cho lớp 12', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-MT-043', E'DM-THPT-MT-044', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'MY_THUAT', 6980, E'3.1', NULL, E'Bố cục tranh phong cảnh', E'Tranh hướng dẫn cách vẽ tranh phong cảnh (bằng chất liệu màu bột hoặc màu nước)', E'HS tìm hiểu các bước vẽ tranh phong cảnh bằng chất liệu màu bột hoặc màu nước', E'- 01 tờ tranh hướng dẫn các bước vẽ tranh bố cục phong cảnh bằng chất liệu màu bột hoặc màu nước. Gồm các bước:\n+ Bước 1: Chọn hình ảnh phong cảnh tiêu biểu phù hợp nội dung tranh. Vẽ phác bố cục mảng chính, mảng phụ cho bức tranh.\n+ Bước 2: Sắp xếp hình ảnh phong cảnh vào mảng chính, mảng phụ.\n+ Bước 3: Vẽ màu vào hình ảnh phong cảnh.\nMàu sắc có đậm - nhạt, thể hiện được không gian phong cảnh.\n+ Bước 4: Hoàn thiện tranh.\n- Kích thước (790x540)mm.', TRUE, TRUE, FALSE, E'TO', E'Tờ', E'01', 1, E'PER_SCHOOL', NULL, E'10', E'Dùng cho lớp 10', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-MT-044', E'DM-THPT-MT-045', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'MY_THUAT', 6990, E'3.2', NULL, E'Bố cục tranh nhân vật', E'Tranh hướng dẫn cách vẽ tranh bố cục nhân vật bằng chất liệu màu bột hoặc màu nước', E'HS tìm hiểu các bước vẽ bố cục nhân vật bằng chất liệu màu bột hoặc màu nước', E'- 01 tờ tranh hướng dẫn các bước vẽ tranh bố cục nhân vật bằng chất liệu màu bột hoặc màu nước. Gồm các bước:\n+ Bước 1: Chọn hình ảnh nhân vật tiêu biểu phù hợp nội dung tranh. Vẽ phác bố cục mảng chính, mảng phụ cho bức tranh.\n+ Bước 2: Sắp xếp hình ảnh nhân vật vào mảng chính, mảng phụ.\n+ Bước 3: Vẽ màu vào hình ảnh. Màu sắc có đậm - nhạt, thể hiện được nội dung của tranh.\n+ Bước 4: Hoàn thiện tranh.\n- Kích thước (790x540)mm.', TRUE, TRUE, FALSE, E'TO', E'Tờ', E'01', 1, E'PER_SCHOOL', NULL, E'11', E'Dùng cho lớp 11', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-MT-045', E'DM-THPT-MT-046', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'MY_THUAT', 7000, E'3.3', NULL, E'Bố cục tranh từ những hình khối cơ bản', E'Tranh hướng dẫn cách vẽ tranh bố cục từ những hình khối cơ bản bằng chất liệu màu bột hoặc màu nước', E'HS tìm hiểu các bước vẽ tranh bố cục từ những hình khối cơ bản bằng chất liệu màu bột hoặc màu nước', E'- 01 tờ tranh hướng dẫn các bước vẽ tranh bố cục từ các hình khối cơ bản bằng chất liệu màu bột hoặc màu nước. Gồm các bước:\n+ Bước 1: Chọn hình khối phù hợp ý tưởng. Vẽ phác bố cục mảng chính, mảng phụ cho bức tranh.\n+ Bước 2: Sắp xếp hình khối vào mảng chính, mảng phụ.\n+ Bước 3: Vẽ màu vào hình ảnh. Màu sắc có đậm - nhạt, thể hiện được trọng tâm tranh.\n+ Bước 4: Hoàn thiện tranh.\n- Kích thước (790x540)mm.', TRUE, TRUE, FALSE, E'TO', E'Tờ', E'01', 1, E'PER_SCHOOL', NULL, E'12', E'Dùng cho lớp 12', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-MT-046', E'DM-THPT-MT-047', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)');
INSERT INTO dm03_rows VALUES
(E'THPT', E'MY_THUAT', 7010, E'1', NULL, E'Tượng tròn', E'Phiên bản tượng tròn', E'Làm mẫu cho HS quan sát, tìm hiểu', E'Bộ tượng gồm 2 tác phẩm điêu khắc:\n- 01 Phiên bản mô tả một tác phẩm điêu khắc tiêu biểu của mĩ thuật Việt Nam\n- 01 Phiên bản mô tả một tác phẩm điêu khắc tiêu biểu của mĩ thuật thế giới\nKích thước: chiều cao từ 600mm đến 700mm\nVật liệu: Bằng nhựa Composit, (hoặc vật liệu có độ cứng tương đương), không cong vênh, chịu được nước, an toàn trong sử dụng. Màu theo phiên bản mẫu.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, E'11', E'Dùng cho lớp 11', E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-MT-047', E'DM-THPT-MT-048', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'MY_THUAT', 7020, E'2', NULL, E'Đầu tượng', E'Tượng chân dung', E'Làm mẫu vẽ cho HS', E'Bộ mẫu gồm ba đầu tượng:\n+ Tượng phạt mảng (mẫu nam trẻ)\n+ Tượng chân dung nam trẻ.\n+ Tượng chân dung nữ trẻ.\nMỗi tượng có phần: đế tượng, phần cổ tượng và phần đầu chân dung người. Tỉ lệ 1/1 (theo mẫu đầu tượng hiện hành). Chất liệu thạch cao hoặc vật liệu có độ cứng tương đương.', FALSE, TRUE, FALSE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, E'10,11,12', E'Dùng cho lớp 10,11,12', E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-MT-048', E'DM-THPT-MT-049', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'HD_TRAI_NGHIEM', 7030, E'1', E'Thiết bị dùng chung', NULL, E'Bộ học liệu điện tử hỗ trợ giáo viên', E'Giúp giáo viên xây dựng kế hoạch tổ chức hoạt động (giáo án) điện tử, chuẩn bị bài giảng điện tử, chuẩn bị các học liệu điện tử, chuẩn bị các bài tập, bài kiểm tra, đánh giá điện tử phù hợp với Chương trình.', E'Bộ học liệu điện tử được xây dựng theo Chương trình Hoạt động trải nghiệm, hướng nghiệp cấp THPT (CTGDPT 2018), có hệ thống học liệu điện tử (hình ảnh, sơ đồ, video, các câu hỏi) đi kèm và được tổ chức, quản lý thành hệ thống thư viện điện tử, thuận lợi cho tra cứu và sử dụng. Bộ học liệu sử dụng được trên máy tính trong môi trường không kết nối internet. Phải đảm bảo tối thiểu các chức năng:\n- Chức năng hỗ trợ soạn giáo án điện tử;\n- Chức năng hướng dẫn chuẩn bị bài giảng điện tử;\n- Chức năng hướng dẫn và chuẩn bị, chỉnh sửa sử dụng học liệu điện tử (hình ảnh, sơ đồ, video…);\n- Chức năng tương tác giữa giáo viên và học sinh;\n- Chức năng hướng dẫn và chuẩn bị các bài tập;\n- Chức năng hỗ trợ chuẩn bị công tác đánh giá. Bộ học liệu điện tử bao gồm các video, hình ảnh minh họa, hướng dẫn tổ chức các hoạt động trải nghiệm, hướng nghiệp như: Hoạt động tham quan, cắm trại, thực địa; diễn đàn, sân khấu hóa, hội thảo, hội thi, trò chơi; các hoạt động tình nguyện nhân đạo, lao động công ích, tuyên truyền; hoạt động khảo sát, điều tra, làm dự án nghiên cứu, sáng tạo công nghệ, nghệ thuật.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10,11,12', E'Dùng cho lớp 10,11, 12', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-HDTN-001', E'DM-THPT-HDTN-001', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'HD_TRAI_NGHIEM', 7040, E'1', E'Thiết bị theo các chủ đề › Tranh ảnh', E'Hoạt động hướng nghiệp', E'Bộ tranh về Các nhóm nghề cơ bản', E'Học sinh phân loại các nhóm nghề\nXác định được những hoạt động sản xuất, kinh doanh, dịch vụ của địa phương và nêu được thông tin, yêu cầu cơ bản về các nhóm nghề này\nPhân loại được các nhóm nghề cơ bản; chỉ ra được đặc trưng, yêu cầu của từng nhóm nghề\nTrình bày được xu hướng phát triển nghề nghiệp trong xã hội hiện đại.\nChỉ ra được những phẩm chất và năng lực cần có của người lao động trong xã hội hiện đại', E'Bộ tranh rời, kích thước (290x210)mm, in offset 4 màu trên giấy couché, định lượng 200g/m2, cán láng OPP mờ (hoặc in màu trên nhựa). Bộ tranh minh họa các hình ảnh:\nNhóm Quản lý\n- Quản lý nhân sự;\n- Quản lý giáo dục;\n- Huấn luyện viên;\n- Tiếp thị và bán hàng;\n- Quản lý tài chính;\n- Quản lý khách sạn;\n- Cảnh sát;\n- Thanh tra;\n- Nhà sản xuất truyền hình;\n- Nhân viên bất động sản;\n- Du lịch;\n- Đại lý kinh doanh/phân phối sản phẩm;\n- Bảo hiểm;\n- Chính trị gia.\nNhóm Kỹ thuật\n- Phi công;\n- Tài xế;\n- Thuyền trưởng;\n- Nuôi trồng thủy sản;\n- Lập trình viên;\n- Kỹ sư máy tính;\n- Phát triển website;\n- Lính cứu hỏa;\n- Đầu bếp;\n- Nhân viên pha chế rượu;\n- Thợ sửa chữa;\n- Huấn luyện viên thể thao;\n- Thợ mộc;\n- Vận động viên;\n- Nhà sản xuất.\nNhóm Nghiên cứu\n- Kiến trúc sư;\n- Kỹ sư;\n- Nhà khoa học;\n- Công nghệ thực phẩm;\n- Khí tượng thủy văn;\n- Bác sĩ dinh dưỡng;\n- Bác sỹ;\n- Dược sĩ;\n- Chuyên gia vật lý trị liệu;\n- Bác sĩ đa khoa;\n- Bác sĩ thú y;\n- Luật sư;\n- Nhà kinh tế học;\n- Nhà phân tích tài chính;\n- Nhà động vật học.\nNhóm Nghệ thuật\n- Họa sĩ phim hoạt họa;\n- Thiết kế thời trang;\n- Họa sĩ đồ họa;\n- Nhiếp ảnh gia;\n- Diễn viên;\n- Nhạc sĩ;\n- Diễn viên múa;\n- Người mẫu thời trang;\nNhóm Xã hội\n- Chăm sóc sức khỏe;\n- Huấn luyện viên;\n- Giáo viên;\n- Tư vấn viên;\n- Luật sư;\n- Nhân viên công tác xã hội;\n- Thợ làm tóc;\n- Tiếp viên hàng không;\n- Nhà thẩm mỹ học;\n- Chăm sóc khách hàng;\n- Trị liệu tâm lí;\n- Y tá;\n- Điều dưỡng;\n- Nhà ngoại giao.\nNhóm Nghiệp vụ\n- Nhân viên tòa án;\n- Thư ký;\n- Nhân viên lưu giữ hồ sơ;\n- Kế toán;\n- Kiểm toán;\n- Thu ngân;\n- Chuyên gia phân tích tín dụng/ngân sách;\n- Nhà định giá bất động sản;\n- Nhân viên kiểm soát không lưu;\n- Giám sát nhà kho;\n- Hành chính văn phòng;\n- Nhân viên xử lý dữ liệu;', FALSE, TRUE, FALSE, E'BO', E'Bộ', E'01/4HS- 6HS', 1, E'PER_STUDENT', 6, E'10,11,12', E'Dùng cho lớp 10,11, 12', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'THPT-HDTN-002', E'DM-THPT-HDTN-002', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'HD_TRAI_NGHIEM', 7050, E'1.1', E'Thiết bị theo các chủ đề › Video/clip', E'Hoạt động hướng nghiệp', E'Video về nhóm ngành quản lý', E'Xác định được những hoạt động sản xuất, kinh doanh, dịch vụ của địa phương và nêu được thông tin, yêu cầu cơ bản về các nhóm nghề này\nPhân loại được các nhóm nghề cơ bản; chỉ ra được đặc trưng, yêu cầu của từng nhóm nghề\nTrình bày được xu hướng phát triển nghề nghiệp trong xã hội hiện đại.\nChỉ ra được những phẩm chất và năng lực cần có của người lao động trong xã hội hiện đại', E'Video hình ảnh thực tế, giới thiệu về đặc điểm của các ngành nghề trong nhóm nghành quản lý, bao gồm:\n- Quản lý nhân sự;\n- Quản lý giáo dục;\n- Huấn luyện viên;\n- Tiếp thị và bán hàng;\n- Quản lý tài chính;\n- Quản lý khách sạn;\n- Cảnh sát;\n- Thanh tra;', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10,11,12', E'Dùng cho lớp 10,11, 12', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-HDTN-003', E'DM-THPT-HDTN-003', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'HD_TRAI_NGHIEM', 7060, E'1.2', E'Thiết bị theo các chủ đề › Video/clip', E'Hoạt động hướng nghiệp', E'Video về nhóm ngành kỹ thuật', E'Xác định được những hoạt động sản xuất, kinh doanh, dịch vụ của địa phương và nêu được thông tin, yêu cầu cơ bản về các nhóm nghề này\nPhân loại được các nhóm nghề cơ bản; chỉ ra được đặc trưng, yêu cầu của từng nhóm nghề\nTrình bày được xu hướng phát triển nghề nghiệp trong xã hội hiện đại.\nChỉ ra được những phẩm chất và năng lực cần có của người lao động trong xã hội hiện đại', E'Video hình ảnh thực tế, giới thiệu về đặc điểm của các ngành nghề trong nhóm nghành kỹ thuật, bao gồm:\n- Phi công;\n- Thuyền trưởng;\n- Nuôi trồng thủy sản;\n- Lập trình viên;\n- Phát triển website;\n- Lính cứu hỏa;\n- Đầu bếp;\n- Nhân viên pha chế rượu;\n- Thợ sửa chữa.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10,11', E'Dùng cho lớp 10,11', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-HDTN-004', E'DM-THPT-HDTN-004', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'HD_TRAI_NGHIEM', 7070, E'1.3', E'Thiết bị theo các chủ đề › Video/clip', E'Hoạt động hướng nghiệp', E'Video về nhóm ngành nghiên cứu', E'Xác định được những hoạt động sản xuất, kinh doanh, dịch vụ của địa phương và nêu được thông tin, yêu cầu cơ bản về các nhóm nghề này\nPhân loại được các nhóm nghề cơ bản; chỉ ra được đặc trưng, yêu cầu của từng nhóm nghề\nTrình bày được xu hướng phát triển nghề nghiệp trong xã hội hiện đại.\nChỉ ra được những phẩm chất và năng lực cần có của người lao động trong xã hội hiện đại', E'Video hình ảnh thực tế, giới thiệu về đặc điểm của các ngành nghề trong nhóm nghành nghiên cứu, bao gồm:\n- Kiến trúc sư;\n- Kỹ sư;\n- Nhà khoa học;\n- Công nghệ thực phẩm;\n- Khí tượng thủy văn;\n- Dược sĩ;\n- Nha sĩ;\n- Bác sĩ đa khoa;\n- Bác sĩ thú y.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'11', E'Dùng cho lớp 11', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-HDTN-005', E'DM-THPT-HDTN-005', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'HD_TRAI_NGHIEM', 7080, E'1.4', E'Thiết bị theo các chủ đề › Video/clip', E'Hoạt động hướng nghiệp', E'Video về nhóm ngành nghệ thuật', E'Xác định được những hoạt động sản xuất, kinh doanh, dịch vụ của địa phương và nêu được thông tin, yêu cầu cơ bản về các nhóm nghề này\nPhân loại được các nhóm nghề cơ bản; chỉ ra được đặc trưng, yêu cầu của từng nhóm nghề\nTrình bày được xu hướng phát triển nghề nghiệp trong xã hội hiện đại.\nChỉ ra được những phẩm chất và năng lực cần có của người lao động trong xã hội hiện đại', E'Video hình ảnh thực tế, giới thiệu về đặc điểm của các ngành nghề trong nhóm nghành nghệ thuật, bao gồm:\n- Thiết kế thời trang;\n- Họa sĩ đồ họa;\n- Nhiếp ảnh gia;\n- Diễn viên;\n- Nhạc sĩ;\n- Người mẫu thời trang.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'11', E'Dùng cho lớp 11', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-HDTN-006', E'DM-THPT-HDTN-006', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'HD_TRAI_NGHIEM', 7090, E'1.5', E'Thiết bị theo các chủ đề › Video/clip', E'Hoạt động hướng nghiệp', E'Video về nhóm ngành xã hội', E'Xác định được những hoạt động sản xuất, kinh doanh, dịch vụ của địa phương và nêu được thông tin, yêu cầu cơ bản về các nhóm nghề này\nPhân loại được các nhóm nghề cơ bản; chỉ ra được đặc trưng, yêu cầu của từng nhóm nghề\nTrình bày được xu hướng phát triển nghề nghiệp trong xã hội hiện đại.\nChỉ ra được những phẩm chất và năng lực cần có của người lao động trong xã hội hiện đại', E'Video hình ảnh thực tế, giới thiệu về đặc điểm của các ngành nghề trong nhóm nghành xã hội, bao gồm:\n- Giáo viên;\n- Tư vấn viên;\n- Luật sư;\n- Nhân viên xã hội;\n- Tiếp viên hàng không.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'12', E'Dùng cho lớp 12', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-HDTN-007', E'DM-THPT-HDTN-007', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'HD_TRAI_NGHIEM', 7100, E'1.6', E'Thiết bị theo các chủ đề › Video/clip', E'Hoạt động hướng nghiệp', E'Video về nhóm ngành nghiệp vụ', E'Xác định được những hoạt động sản xuất, kinh doanh, dịch vụ của địa phương và nêu được thông tin, yêu cầu cơ bản về các nhóm nghề này\nPhân loại được các nhóm nghề cơ bản; chỉ ra được đặc trưng, yêu cầu của từng nhóm nghề\nTrình bày được xu hướng phát triển nghề nghiệp trong xã hội hiện đại.\nChỉ ra được những phẩm chất và năng lực cần có của người lao động trong xã hội hiện đại', E'Video hình ảnh thực tế, giới thiệu về đặc điểm của các ngành nghề trong nhóm nghành nghiệp vụ, bao gồm:\n- Truyền thông và hồ sơ;\n- Nhân viên lưu giữ hồ sơ;\n- Kế toán/kiểm toán;’\n- Thu ngân;\n- Nhân viên kiểm soát không lưu.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'11', E'Dùng cho lớp 11', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-HDTN-008', E'DM-THPT-HDTN-008', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'HD_TRAI_NGHIEM', 7110, E'1.7', E'Thiết bị theo các chủ đề › Video/clip', E'Hoạt động hướng nghiệp', E'Video về an toàn lao động nghề nghiệp', E'Tìm hiểu được những điều kiện đảm bảo an toàn và sức khoẻ nghề nghiệp trong từng lĩnh vực nghề nghiệp.', E'Video hình ảnh thực tế, giới thiệu về an toàn lao động nghề nghiệp mô tả khái niệm, các quy định của pháp luật, lợi ích của an toàn lao động.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10,11,12', E'Dùng cho lớp 10,11, 12', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-HDTN-009', E'DM-THPT-HDTN-009', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'HD_TRAI_NGHIEM', 7120, E'2.1', E'Thiết bị theo các chủ đề › Video/clip', E'Hoạt động xây dựng cộng đồng', E'Video về thực trạng văn hóa ứng xử nơi công cộng', NULL, E'Video hình ảnh thực tế, nội dung về thực trạng văn hóa ứng xử nơi công cộng.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'10,11,12', E'Dùng cho lớp 10,11, 12', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'THPT-HDTN-010', E'DM-THPT-HDTN-010', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'HD_TRAI_NGHIEM', 7130, E'3.1', E'Thiết bị theo các chủ đề › Dụng cụ', NULL, E'Bộ dụng cụ lao động sân trường', E'Giúp học sinh trải nghiệm với lao động', E'Bộ công cụ lao động:\n- Bộ dụng cụ làm vệ sinh trường học, bao gồm: chổi rễ, ky hốt rác có cán bằng nhựa, găng tay lao động phù hợp với học sinh, khẩu trang y tế;\n- Bộ công cụ làm vệ sinh lớp học, bao gồm: chổi đót (hoặc chổi nhựa), khăn lau, ky hốt rác có cán bằng nhựa, khẩu trang y tế, giỏ đựng rác bằng nhựa có quai xách;\n- Bộ dụng cụ chăm sóc hoa, cây trồng thông thường, bao gồm: xẻng, bình tưới cây 4 lít bằng nhựa, kéo cắt cành.', FALSE, FALSE, FALSE, E'BO', E'Bộ', E'05/trường', 5, E'PER_SCHOOL', NULL, E'10,11,12', E'Dùng cho lớp 10,11, 12', E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THPT-HDTN-011', E'DM-THPT-HDTN-011', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'CHUNG', 7140, E'1', NULL, NULL, E'Bảng nhóm', E'Dùng cho dạy học và hoạt động giáo dục.', E'Kích thước (400x600x0,5)mm, một mặt mầu trắng kẻ li ô li dùng để viết bút dạ xoá được; một mặt màu xanh, dòng kẻ ô vuông trắng dùng để viết phấn.', FALSE, TRUE, FALSE, E'CHIEC', E'Chiếc', E'12/trường', 12, E'PER_SCHOOL', NULL, NULL, NULL, E'DO_DUNG_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DC-001', E'DM-THPT-DC-001', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'CHUNG', 7150, E'2', NULL, NULL, E'Tủ đựng thiết bị', E'Đựng thiết bị', E'Kích thước (1760x1060x400)mm; ngăn đựng có thể thay đổi được chiều cao; cửa có khóa; chắc chắn, bền vững, đảm bảo an toàn khi sử dụng.', TRUE, TRUE, FALSE, E'CHIEC', E'Chiếc', E'03/trường', 3, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DC-002', E'DM-THPT-DC-002', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'CHUNG', 7160, E'3', NULL, NULL, E'Giá để thiết bị', E'Để thiết bị', E'Bằng kim loại hoặc gỗ, kích thước phù hợp với thiết bị.', TRUE, FALSE, FALSE, E'CHIEC', E'Chiếc', E'03/trường', 3, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DC-003', E'DM-THPT-DC-003', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
