(E'THPT', E'CHUNG', 7230, E'7.3', NULL, NULL, E'Thiết bị âm thanh đa năng di động', E'Dùng cho dạy học và hoạt động giáo dục.', E'- Tích hợp được nhiều tính năng âm ly, loa, micro, đọc phát các định dạng tối thiểu ghi trên SD, USB trên thiết bị;\n- Kết nối line-in, audio in, bluetooth với nguồn phát âm thanh;\n- Công suất phù hợp với lớp học;\n- Kèm theo micro;\n- Nguồn điện: AC 220V/50Hz; DC, có ắc quy/pin sạc.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01 bộ (hoặc chiếc)/5 lớp', 1, E'PER_CLASS', 5, NULL, NULL, E'MAY_MOC_THIET_BI', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DC-010', E'DM-THPT-DC-010', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'CHUNG', 7240, E'8', NULL, NULL, E'Thiết bị trình chiếu', E'Dùng chung cho toàn trường, các môn học và hoạt động giáo dục (căn cứ điều kiện thực tế của nhà trường để lựa chọn các thiết bị dưới đây cho phù hợp)', E'Dùng chung cho toàn trường, các môn học và hoạt động giáo dục (căn cứ điều kiện thực tế của nhà trường để lựa chọn các thiết bị dưới đây cho phù hợp)', FALSE, FALSE, FALSE, NULL, NULL, E'01 bộ (hoặc chiếc)/5 lớp', 1, E'PER_CLASS', 5, NULL, NULL, E'THIET_BI_CNTT', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DC-011', E'DM-THPT-DC-011', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
