(E'THPT', E'CHUNG', 7260, E'8.2', NULL, NULL, E'Máy chiếu (hoặc Màn hình hiển thị)', E'Trình chiếu', E'Máy chiếu:\n- Loại thông dụng;\n- Có đủ cổng kết nối phù hợp;\n- Cường độ sáng tối thiểu 3.500 Ansilumens;\n- Độ phân giải tối thiểu XGA;\n- Kích cỡ khi chiếu lên màn hình tối thiểu 100 inch;\n- Điều khiển từ xa;\n- Kèm theo màn chiếu và thiết bị điều khiển (nếu có);\nMàn hình hiển thị:\n- Loại thông dụng, màn hình tối thiểu 50 inch, Full HD;\n- Có đủ cổng kết nối phù hợp;\n- Có ngôn ngữ hiển thị Tiếng Việt;\n- Điều khiển từ xa;\n- Nguồn điện: AC 90-220V/50Hz.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01 bộ (hoặc chiếc)/5 lớp', 1, E'PER_CLASS', 5, NULL, NULL, E'MAY_MOC_THIET_BI', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DC-013', E'DM-THPT-DC-013', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'CHUNG', 7270, E'8.3', NULL, NULL, E'Đầu DVD', E'Dùng cho dạy học và hoạt động giáo dục.', E'- Loại thông dụng;\n- Đọc đĩa DVD, VCD/CD, CD – RW và các chuẩn thông dụng khác;\n- Có cổng kết nối USB, thẻ nhớ;\n- Tín hiệu ra dưới dạng AV, HDMI;\n- Chức năng tua tiến, tua lùi, tạm dừng;\n- Điều khiển từ xa;\n- Nguồn điện: 90V – 240V/50 Hz.', TRUE, FALSE, FALSE, E'CHIEC', E'Chiếc', E'01 bộ (hoặc chiếc)/5 lớp', 1, E'PER_CLASS', 5, NULL, NULL, E'MAY_MOC_THIET_BI', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DC-014', E'DM-THPT-DC-014', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'CHUNG', 7280, E'8.4', NULL, NULL, E'Máy chiếu vật thể', E'Dạy học', E'- Loại thông dụng, Full HD;\n- Cảm biến hình ảnh tối thiểu 5MP;\n- Zoom quang học tối thiểu 10x;\n- Phụ kiện kèm theo.', TRUE, TRUE, FALSE, E'CHIEC', E'Chiếc', E'01 bộ (hoặc chiếc)/5 lớp', 1, E'PER_CLASS', 5, NULL, NULL, E'THIET_BI_CNTT', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DC-015', E'DM-THPT-DC-015', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
(E'THPT', E'CHUNG', 7290, E'9', NULL, NULL, E'Máy in', NULL, E'Loại thông dụng, công nghệ laze, tốc độ tối thiểu 16 tờ khổ A4/phút.', TRUE, FALSE, FALSE, E'CHIEC', E'Chiếc', E'02/trường', 2, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_CNTT', E'PHYSICAL', E'SERIAL', NULL, E'THPT-DC-016', E'DM-THPT-DC-016', E'TT 39/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)'),
