--liquibase formatted sql
--changeset tutn:037-dinh-muc-thpt
--comment Danh mục thiết bị dạy học tối thiểu THPT theo 06/VBHN-BGDĐT, gồm 732 dòng.

ALTER TABLE equipment_norms ADD COLUMN grade_levels VARCHAR(40);
ALTER TABLE equipment_norms ADD COLUMN section_name VARCHAR(500);

CREATE TEMP TABLE dm03_rows (
    level VARCHAR(10), subject VARCHAR(64), sort INTEGER, item_no VARCHAR(20), section VARCHAR(500),
    topic VARCHAR(500), name TEXT, purpose TEXT, description TEXT, teacher BOOLEAN, student BOOLEAN,
    optional BOOLEAN, unit VARCHAR(64), unit_text VARCHAR(50), qty_text VARCHAR(100), qty NUMERIC(14,3),
    basis VARCHAR(20), size INTEGER, grades VARCHAR(40), note TEXT, type VARCHAR(64),
    pod VARCHAR(30), tracking VARCHAR(20), category VARCHAR(30), catalog_code VARCHAR(64),
    norm_code VARCHAR(64), legal VARCHAR(255)
) ON COMMIT DROP;








ON CONFLICT (code) DO NOTHING;

ON CONFLICT (code) DO NOTHING;

     standard_version, status, created_at)
SELECT 'STD-THPT-06-VBHN', 'Danh mục thiết bị dạy học tối thiểu cấp THPT', 20, TRUE,
       'Thông tư 39/2021/TT-BGDĐT, sửa đổi bởi Thông tư 26/2023/TT-BGDĐT (06/VBHN-BGDĐT)',
       l.id, y.id, '06/VBHN-BGDĐT', 'ACTIVE', now()
FROM education_levels l LEFT JOIN school_years y ON y.code = '2024-2025'
WHERE l.code = 'THPT' AND NOT EXISTS
    (SELECT 1 FROM equipment_standards WHERE code = 'STD-THPT-06-VBHN');

UPDATE equipment_standards SET status = 'RETIRED', active = FALSE, updated_at = now()
WHERE status = 'ACTIVE' AND code <> 'STD-THPT-06-VBHN';

CREATE UNIQUE INDEX uq_equipment_standards_one_active_level
    ON equipment_standards (education_level_id) WHERE status = 'ACTIVE';

     grade_id, unit_id, tracking_type, minimum_required, asset_category, physical_or_digital,
     legal_basis, used_by_teacher, used_by_student, description, created_at)
SELECT DISTINCT ON (r.catalog_code)
    r.catalog_code, left(r.name, 255), r.sort, TRUE, t.id, s.id, l.id, g.id, u.id,
    r.tracking, TRUE, r.category, r.pod, r.legal, r.teacher, r.student, r.description, now()
FROM dm03_rows r
JOIN education_levels l ON l.code = 'THPT'
JOIN subjects s ON s.code = CASE r.subject
    WHEN 'CHUNG' THEN 'DUNGCHUNG' WHEN 'TIENG_ANH' THEN 'NGOAINGU'
    WHEN 'NGU_VAN' THEN 'NGUVAN' WHEN 'VAT_LY' THEN 'VATLI'
    WHEN 'HOA_HOC' THEN 'HOAHOC' WHEN 'SINH_HOC' THEN 'SINHHOC'
    WHEN 'LICH_SU' THEN 'LICHSU' WHEN 'DIA_LY' THEN 'DIALI'
    WHEN 'GDKT_PL' THEN 'GDKTPL' WHEN 'TIN_HOC' THEN 'TINHOC'
    WHEN 'CONG_NGHE' THEN 'CONGNGHE' WHEN 'AM_NHAC' THEN 'AMNHAC'
    WHEN 'MY_THUAT' THEN 'MITHUAT' WHEN 'THE_DUC' THEN 'GDTC'
    WHEN 'HD_TRAI_NGHIEM' THEN 'HDTN' ELSE r.subject END
JOIN equipment_types t ON t.code = r.type
LEFT JOIN units u ON u.code = r.unit
LEFT JOIN grades g ON g.code = 'K' || r.grades
WHERE NOT EXISTS (SELECT 1 FROM equipment_catalogs c WHERE c.code = r.catalog_code)
ORDER BY r.catalog_code, r.sort;

     subject_id, unit_id, min_quantity, norm_basis, basis_size, quantity_text, unit_text,
     grade_id, grade_levels, item_no, section_name, topic, purpose, description,
     for_teacher, for_student, optional, created_at)
SELECT r.norm_code, left(r.name, 255), r.sort, TRUE, left(r.note, 500),
       sd.id, c.id, c.equipment_type_id, c.subject_id, u.id, r.qty,
       COALESCE(r.basis, 'PER_SCHOOL'), r.size, r.qty_text, r.unit_text,
       g.id, r.grades, r.item_no, r.section, r.topic, r.purpose, r.description,
       r.teacher, r.student, r.optional, now()
FROM dm03_rows r
JOIN equipment_standards sd ON sd.code = 'STD-THPT-06-VBHN'
JOIN equipment_catalogs c ON c.code = r.catalog_code
LEFT JOIN units u ON u.code = r.unit
LEFT JOIN grades g ON g.code = 'K' || r.grades
WHERE NOT EXISTS (SELECT 1 FROM equipment_norms n WHERE n.code = r.norm_code)
ORDER BY r.sort;

UPDATE equipment_catalogs c SET minimum_required = EXISTS (
    SELECT 1 FROM equipment_norms n JOIN equipment_standards s ON s.id = n.standard_id
    WHERE n.catalog_id = c.id AND n.active AND s.status = 'ACTIVE'
) WHERE c.owner_school_id IS NULL;
